window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["DAN"]={"book":"DAN","editions":{"hbo-source":[[1,1,"בִּ⁠שְׁנַ֣ת שָׁל֔וֹשׁ לְ⁠מַלְכ֖וּת יְהוֹיָקִ֣ים מֶֽלֶךְ־יְהוּדָ֑ה בָּ֣א נְבוּכַדְנֶאצַּ֧ר מֶֽלֶךְ־בָּבֶ֛ל יְרוּשָׁלִַ֖ם וַ⁠יָּ֥צַר עָלֶֽי⁠הָ׃","bi̇⁠şĕ̌na֣ţ şá̌l֔wòş̌ lĕ⁠malĕk֖ẇţ yĕhwòyáqi֣ym meֽlekĕ-yĕhẇdá֑h bá֣̇ʼ nĕbẇkadĕneʼẕȧ֧r meֽlekĕ-bá̇be֛l yĕrẇşá̌lia֖m wa⁠yá֥̇ẕar ʻáleֽy⁠há׃"],[1,2,"וַ⁠יִּתֵּן֩ אֲדֹנָ֨⁠י בְּ⁠יָד֜⁠וֹ אֶת־יְהוֹיָקִ֣ים מֶֽלֶךְ־יְהוּדָ֗ה וּ⁠מִ⁠קְצָת֙ כְּלֵ֣י בֵית־הָֽ⁠אֱלֹהִ֔ים וַ⁠יְבִיאֵ֥⁠ם אֶֽרֶץ־שִׁנְעָ֖ר בֵּ֣ית אֱלֹהָ֑י⁠ו וְ⁠אֶת־הַ⁠כֵּלִ֣ים הֵבִ֔יא בֵּ֖ית אוֹצַ֥ר אֱלֹהָֽי⁠ו׃","wa⁠yi̇ţé̇n֩ ʼàdòná֨⁠y bĕ̇⁠yád֜⁠wò ʼeţ-yĕhwòyáqi֣ym meֽlekĕ-yĕhẇdá֗h ẇ⁠mi⁠qĕẕáţ֙ kĕ̇lé֣y béyţ-háֽ⁠ʼèlòhi֔ym wa⁠yĕbiyʼé֥⁠m ʼeֽreẕ-şǐnĕʻá֖r bé֣̇yţ ʼèlòhá֑y⁠w wĕ⁠ʼeţ-ha⁠ké̇li֣ym hébi֔yʼ bé֖̇yţ ʼwòẕa֥r ʼèlòháֽy⁠w׃"],[1,3,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ לְ⁠אַשְׁפְּנַ֖ז רַ֣ב סָרִיסָ֑י⁠ו לְ⁠הָבִ֞יא מִ⁠בְּנֵ֧י יִשְׂרָאֵ֛ל וּ⁠מִ⁠זֶּ֥רַע הַ⁠מְּלוּכָ֖ה וּ⁠מִן־הַֽ⁠פַּרְתְּמִֽים׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ lĕ⁠ʼaşĕ̌pĕ̇na֖z ra֣b sáriysá֑y⁠w lĕ⁠hábi֞yʼ mi⁠bĕ̇né֧y yişĕ̂ráʼé֛l ẇ⁠mi⁠zė֥raʻ ha⁠mĕ̇lẇká֖h ẇ⁠min-haֽ⁠pȧrĕţĕ̇miֽym׃"],[1,4,"יְלָדִ֣ים אֲשֶׁ֣ר אֵֽין־בָּ⁠הֶ֣ם כָּל־מאום וְ⁠טוֹבֵ֨י מַרְאֶ֜ה וּ⁠מַשְׂכִּילִ֣ים בְּ⁠כָל־חָכְמָ֗ה וְ⁠יֹ֤דְעֵי דַ֨עַת֙ וּ⁠מְבִינֵ֣י מַדָּ֔ע וַ⁠אֲשֶׁר֙ כֹּ֣חַ בָּ⁠הֶ֔ם לַ⁠עֲמֹ֖ד בְּ⁠הֵיכַ֣ל הַ⁠מֶּ֑לֶךְ וּֽ⁠לֲ⁠לַמְּדָ֥⁠ם סֵ֖פֶר וּ⁠לְשׁ֥וֹן כַּשְׂדִּֽים׃","yĕládi֣ym ʼàşě֣r ʼéֽyn-bá̇⁠he֣m ká̇l-mʼwm wĕ⁠twòbé֨y marĕʼe֜h ẇ⁠maşĕ̂ki̇yli֣ym bĕ̇⁠kál-ẖákĕmá֗h wĕ⁠yò֤dĕʻéy da֨ʻaţ֙ ẇ⁠mĕbiyné֣y madá̇֔ʻ wa⁠ʼàşěr֙ kò֣̇ẖa bá̇⁠he֔m la⁠ʻàmò֖d bĕ̇⁠héyka֣l ha⁠mė֑lekĕ ẇֽ⁠là⁠lamĕ̇dá֥⁠m sé֖per ẇ⁠lĕş֥̌wòn kȧşĕ̂diֽ̇ym׃"],[1,5,"וַ⁠יְמַן֩ לָ⁠הֶ֨ם הַ⁠מֶּ֜לֶךְ דְּבַר־י֣וֹם בְּ⁠יוֹמ֗⁠וֹ מִ⁠פַּת־בַּ֤ג הַ⁠מֶּ֨לֶךְ֙ וּ⁠מִ⁠יֵּ֣ין מִשְׁתָּ֔י⁠ו וּֽ⁠לְ⁠גַדְּלָ֖⁠ם שָׁנִ֣ים שָׁל֑וֹשׁ וּ⁠מִ֨⁠קְצָתָ֔⁠ם יַֽעַמְד֖וּ לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yĕman֩ lá⁠he֨m ha⁠mė֜lekĕ dĕ̇bar-y֣wòm bĕ̇⁠ywòm֗⁠wò mi⁠pȧţ-bȧ֤g ha⁠mė֨lekĕ֙ ẇ⁠mi⁠yé֣̇yn mişĕ̌ţá̇֔y⁠w ẇֽ⁠lĕ⁠gadĕ̇lá֖⁠m şá̌ni֣ym şá̌l֑wòş̌ ẇ⁠mi֨⁠qĕẕáţá֔⁠m yaֽʻamĕd֖ẇ li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[1,6,"וַ⁠יְהִ֥י בָ⁠הֶ֖ם מִ⁠בְּנֵ֣י יְהוּדָ֑ה דָּנִיֵּ֣אל חֲנַנְיָ֔ה מִֽישָׁאֵ֖ל וַ⁠עֲזַרְיָֽה׃","wa⁠yĕhi֥y bá⁠he֖m mi⁠bĕ̇né֣y yĕhẇdá֑h dá̇niyé֣̇ʼl ẖànanĕyá֔h miֽyşá̌ʼé֖l wa⁠ʻàzarĕyáֽh׃"],[1,7,"וַ⁠יָּ֧שֶׂם לָ⁠הֶ֛ם שַׂ֥ר הַ⁠סָּרִיסִ֖ים שֵׁמ֑וֹת וַ⁠יָּ֨שֶׂם לְ⁠דָֽנִיֵּ֜אל בֵּ֣לְטְשַׁאצַּ֗ר וְ⁠לַֽ⁠חֲנַנְיָה֙ שַׁדְרַ֔ךְ וּ⁠לְ⁠מִֽישָׁאֵ֣ל מֵישַׁ֔ךְ וְ⁠לַ⁠עֲזַרְיָ֖ה עֲבֵ֥ד נְגֽוֹ׃","wa⁠yá֧̇şêm lá⁠he֛m şâ֥r ha⁠sá̇riysi֖ym şé̌m֑wòţ wa⁠yá̇֨şêm lĕ⁠dáֽniyé̇֜ʼl bé֣̇lĕtĕşǎʼẕȧ֗r wĕ⁠laֽ⁠ẖànanĕyáh֙ şǎdĕra֔kĕ ẇ⁠lĕ⁠miֽyşá̌ʼé֣l méyşǎ֔kĕ wĕ⁠la⁠ʻàzarĕyá֖h ʻàbé֥d nĕgֽwò׃"],[1,8,"וַ⁠יָּ֤שֶׂם דָּנִיֵּאל֙ עַל־לִבּ֔⁠וֹ אֲשֶׁ֧ר לֹֽא־יִתְגָּאַ֛ל בְּ⁠פַתְבַּ֥ג הַ⁠מֶּ֖לֶךְ וּ⁠בְ⁠יֵ֣ין מִשְׁתָּ֑י⁠ו וַ⁠יְבַקֵּשׁ֙ מִ⁠שַּׂ֣ר הַ⁠סָּרִיסִ֔ים אֲשֶׁ֖ר לֹ֥א יִתְגָּאָֽל׃","wa⁠yá֤̇şêm dá̇niyé̇ʼl֙ ʻal-liḃ֔⁠wò ʼàşě֧r lòֽʼ-yiţĕgá̇ʼa֛l bĕ̇⁠paţĕbȧ֥g ha⁠mė֖lekĕ ẇ⁠bĕ⁠yé֣yn mişĕ̌ţá֑̇y⁠w wa⁠yĕbaqé̇ş̌֙ mi⁠şȧ֣̂r ha⁠sá̇riysi֔ym ʼàşě֖r lò֥ʼ yiţĕgá̇ʼáֽl׃"],[1,9,"וַ⁠יִּתֵּ֤ן הָֽ⁠אֱלֹהִים֙ אֶת־דָּ֣נִיֵּ֔אל לְ⁠חֶ֖סֶד וּֽ⁠לְ⁠רַחֲמִ֑ים לִ⁠פְנֵ֖י שַׂ֥ר הַ⁠סָּרִיסִֽים׃","wa⁠yi̇ţé֤̇n háֽ⁠ʼèlòhiym֙ ʼeţ-dá֣̇niyé̇֔ʼl lĕ⁠ẖe֖sed ẇֽ⁠lĕ⁠raẖàmi֑ym li⁠pĕné֖y şâ֥r ha⁠sá̇riysiֽym׃"],[1,10,"וַ⁠יֹּ֜אמֶר שַׂ֤ר הַ⁠סָּרִיסִים֙ לְ⁠דָ֣נִיֵּ֔אל יָרֵ֤א אֲנִי֙ אֶת־אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ אֲשֶׁ֣ר מִנָּ֔ה אֶת־מַאֲכַלְ⁠כֶ֖ם וְ⁠אֶת־מִשְׁתֵּי⁠כֶ֑ם אֲשֶׁ֡ר לָ⁠מָּה֩ יִרְאֶ֨ה אֶת־פְּנֵי⁠כֶ֜ם זֹֽעֲפִ֗ים מִן־הַ⁠יְלָדִים֙ אֲשֶׁ֣ר כְּ⁠גִֽילְ⁠כֶ֔ם וְ⁠חִיַּבְתֶּ֥ם אֶת־רֹאשִׁ֖⁠י לַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֜ʼmer şâ֤r ha⁠sá̇riysiym֙ lĕ⁠dá֣niyé̇֔ʼl yáré֤ʼ ʼàniy֙ ʼeţ-ʼàdòni֣⁠y ha⁠mė֔lekĕ ʼàşě֣r miná̇֔h ʼeţ-maʼàkalĕ⁠ke֖m wĕ⁠ʼeţ-mişĕ̌ţé̇y⁠ke֑m ʼàşě֡r lá⁠má̇h֩ yirĕʼe֨h ʼeţ-pĕ̇néy⁠ke֜m zòֽʻàpi֗ym min-ha⁠yĕládiym֙ ʼàşě֣r kĕ̇⁠giֽylĕ⁠ke֔m wĕ⁠ẖiyȧbĕţė֥m ʼeţ-ròʼşǐ֖⁠y la⁠mėֽlekĕ׃"],[1,11,"וַ⁠יֹּ֥אמֶר דָּנִיֵּ֖אל אֶל־הַ⁠מֶּלְצַ֑ר אֲשֶׁ֤ר מִנָּה֙ שַׂ֣ר הַ⁠סָּֽרִיסִ֔ים עַל־דָּנִיֵּ֣אל חֲנַנְיָ֔ה מִֽישָׁאֵ֖ל וַ⁠עֲזַרְיָֽה׃","wa⁠yò֥̇ʼmer dá̇niyé֖̇ʼl ʼel-ha⁠mėlĕẕa֑r ʼàşě֤r miná̇h֙ şâ֣r ha⁠sáֽ̇riysi֔ym ʻal-dá̇niyé֣̇ʼl ẖànanĕyá֔h miֽyşá̌ʼé֖l wa⁠ʻàzarĕyáֽh׃"],[1,12,"נַס־נָ֥א אֶת־עֲבָדֶ֖י⁠ךָ יָמִ֣ים עֲשָׂרָ֑ה וְ⁠יִתְּנוּ־לָ֜⁠נוּ מִן־הַ⁠זֵּרֹעִ֛ים וְ⁠נֹאכְלָ֖ה וּ⁠מַ֥יִם וְ⁠נִשְׁתֶּֽה׃","nas-ná֥ʼ ʼeţ-ʻàbáde֖y⁠ká yámi֣ym ʻàşá̂rá֑h wĕ⁠yiţĕ̇nẇ-lá֜⁠nẇ min-ha⁠zé̇ròʻi֛ym wĕ⁠nòʼkĕlá֖h ẇ⁠ma֥yim wĕ⁠nişĕ̌ţėֽh׃"],[1,13,"וְ⁠יֵרָא֤וּ לְ⁠פָנֶ֨י⁠ךָ֙ מַרְאֵ֔י⁠נוּ וּ⁠מַרְאֵה֙ הַ⁠יְלָדִ֔ים הָ⁠אֹ֣כְלִ֔ים אֵ֖ת פַּתְבַּ֣ג הַ⁠מֶּ֑לֶךְ וְ⁠כַ⁠אֲשֶׁ֣ר תִּרְאֵ֔ה עֲשֵׂ֖ה עִם־עֲבָדֶֽי⁠ךָ׃","wĕ⁠yéráʼ֤ẇ lĕ⁠páne֨y⁠ká֙ marĕʼé֔y⁠nẇ ẇ⁠marĕʼéh֙ ha⁠yĕládi֔ym há⁠ʼò֣kĕli֔ym ʼé֖ţ pȧţĕbȧ֣g ha⁠mė֑lekĕ wĕ⁠ka⁠ʼàşě֣r ţi̇rĕʼé֔h ʻàşé֖̂h ʻim-ʻàbádeֽy⁠ká׃"],[1,14,"וַ⁠יִּשְׁמַ֥ע לָ⁠הֶ֖ם לַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠יְנַסֵּ֖⁠ם יָמִ֥ים עֲשָׂרָֽה׃","wa⁠yi̇şĕ̌ma֥ʻ lá⁠he֖m la⁠dá̇bá֣r ha⁠zė֑h wa⁠yĕnasé֖̇⁠m yámi֥ym ʻàşá̂ráֽh׃"],[1,15,"וּ⁠מִ⁠קְצָת֙ יָמִ֣ים עֲשָׂרָ֔ה נִרְאָ֤ה מַרְאֵי⁠הֶם֙ ט֔וֹב וּ⁠בְרִיאֵ֖י בָּשָׂ֑ר מִן־כָּל־הַ⁠יְלָדִ֔ים הָ⁠אֹ֣כְלִ֔ים אֵ֖ת פַּתְבַּ֥ג הַ⁠מֶּֽלֶךְ׃","ẇ⁠mi⁠qĕẕáţ֙ yámi֣ym ʻàşá̂rá֔h nirĕʼá֤h marĕʼéy⁠hem֙ t֔wòb ẇ⁠bĕriyʼé֖y bá̇şá֑̂r min-ká̇l-ha⁠yĕládi֔ym há⁠ʼò֣kĕli֔ym ʼé֖ţ pȧţĕbȧ֥g ha⁠mėֽlekĕ׃"],[1,16,"וַ⁠יְהִ֣י הַ⁠מֶּלְצַ֗ר נֹשֵׂא֙ אֶת־פַּתְבָּגָ֔⁠ם וְ⁠יֵ֖ין מִשְׁתֵּי⁠הֶ֑ם וְ⁠נֹתֵ֥ן לָ⁠הֶ֖ם זֵרְעֹנִֽים׃","wa⁠yĕhi֣y ha⁠mėlĕẕa֗r nòşé̂ʼ֙ ʼeţ-pȧţĕbá̇gá֔⁠m wĕ⁠yé֖yn mişĕ̌ţé̇y⁠he֑m wĕ⁠nòţé֥n lá⁠he֖m zérĕʻòniֽym׃"],[1,17,"וְ⁠הַ⁠יְלָדִ֤ים הָ⁠אֵ֨לֶּה֙ אַרְבַּעְתָּ֔⁠ם נָתַ֨ן לָ⁠הֶ֧ם הָֽ⁠אֱלֹהִ֛ים מַדָּ֥ע וְ⁠הַשְׂכֵּ֖ל בְּ⁠כָל־סֵ֣פֶר וְ⁠חָכְמָ֑ה וְ⁠דָנִיֵּ֣אל הֵבִ֔ין בְּ⁠כָל־חָז֖וֹן וַ⁠חֲלֹמֽוֹת׃","wĕ⁠ha⁠yĕládi֤ym há⁠ʼé֨lėh֙ ʼarĕbȧʻĕţá̇֔⁠m náţa֨n lá⁠he֧m háֽ⁠ʼèlòhi֛ym madá֥̇ʻ wĕ⁠haşĕ̂ké֖̇l bĕ̇⁠kál-sé֣per wĕ⁠ẖákĕmá֑h wĕ⁠dániyé֣̇ʼl hébi֔yn bĕ̇⁠kál-ẖáz֖wòn wa⁠ẖàlòmֽwòţ׃"],[1,18,"וּ⁠לְ⁠מִ⁠קְצָת֙ הַ⁠יָּמִ֔ים אֲשֶׁר־אָמַ֥ר הַ⁠מֶּ֖לֶךְ לַ⁠הֲבִיאָ֑⁠ם וַ⁠יְבִיאֵ⁠ם֙ שַׂ֣ר הַ⁠סָּרִיסִ֔ים לִ⁠פְנֵ֖י נְבֻכַדְנֶצַּֽר׃","ẇ⁠lĕ⁠mi⁠qĕẕáţ֙ ha⁠yá̇mi֔ym ʼàşěr-ʼáma֥r ha⁠mė֖lekĕ la⁠hàbiyʼá֑⁠m wa⁠yĕbiyʼé⁠m֙ şâ֣r ha⁠sá̇riysi֔ym li⁠pĕné֖y nĕbukadĕneẕȧֽr׃"],[1,19,"וַ⁠יְדַבֵּ֣ר אִתָּ⁠ם֮ הַ⁠מֶּלֶךְ֒ וְ⁠לֹ֤א נִמְצָא֙ מִ⁠כֻּלָּ֔⁠ם כְּ⁠דָנִיֵּ֣אל חֲנַנְיָ֔ה מִֽישָׁאֵ֖ל וַ⁠עֲזַרְיָ֑ה וַ⁠יַּֽעַמְד֖וּ לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yĕdabé֣̇r ʼiţá̇⁠m֮ ha⁠mėlekĕ֒ wĕ⁠lò֤ʼ nimĕẕáʼ֙ mi⁠ku̇lá̇֔⁠m kĕ̇⁠dániyé֣̇ʼl ẖànanĕyá֔h miֽyşá̌ʼé֖l wa⁠ʻàzarĕyá֑h wa⁠yȧֽʻamĕd֖ẇ li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[1,20,"וְ⁠כֹ֗ל דְּבַר֙ חָכְמַ֣ת בִּינָ֔ה אֲשֶׁר־בִּקֵּ֥שׁ מֵ⁠הֶ֖ם הַ⁠מֶּ֑לֶךְ וַֽ⁠יִּמְצָאֵ֞⁠ם עֶ֣שֶׂר יָד֗וֹת עַ֤ל כָּל־הַֽ⁠חַרְטֻמִּים֙ הָֽ⁠אַשָּׁפִ֔ים אֲשֶׁ֖ר בְּ⁠כָל־מַלְכוּתֽ⁠וֹ׃","wĕ⁠kò֗l dĕ̇bar֙ ẖákĕma֣ţ bi̇yná֔h ʼàşěr-bi̇qé֥̇ş̌ mé⁠he֖m ha⁠mė֑lekĕ waֽ⁠yi̇mĕẕáʼé֞⁠m ʻe֣şêr yád֗wòţ ʻa֤l ká̇l-haֽ⁠ẖarĕtumi̇ym֙ háֽ⁠ʼaşá̇̌pi֔ym ʼàşě֖r bĕ̇⁠kál-malĕkẇţֽ⁠wò׃"],[1,21,"וַֽ⁠יְהִי֙ דָּֽנִיֵּ֔אל עַד־שְׁנַ֥ת אַחַ֖ת לְ⁠כ֥וֹרֶשׁ הַ⁠מֶּֽלֶךְ׃פ","waֽ⁠yĕhiy֙ dáֽ̇niyé̇֔ʼl ʻad-şĕ̌na֥ţ ʼaẖa֖ţ lĕ⁠k֥wòreş̌ ha⁠mėֽlekĕ׃p"],[2,1,"וּ⁠בִ⁠שְׁנַ֣ת שְׁתַּ֗יִם לְ⁠מַלְכוּת֙ נְבֻֽכַדְנֶצַּ֔ר חָלַ֥ם נְבֻֽכַדְנֶצַּ֖ר חֲלֹמ֑וֹת וַ⁠תִּתְפָּ֣עֶם רוּח֔⁠וֹ וּ⁠שְׁנָת֖⁠וֹ נִהְיְתָ֥ה עָלָֽי⁠ו׃","ẇ⁠bi⁠şĕ̌na֣ţ şĕ̌ţȧ֗yim lĕ⁠malĕkẇţ֙ nĕbuֽkadĕneẕȧ֔r ẖála֥m nĕbuֽkadĕneẕȧ֖r ẖàlòm֑wòţ wa⁠ţi̇ţĕpá֣̇ʻem rẇẖ֔⁠wò ẇ⁠şĕ̌náţ֖⁠wò nihĕyĕţá֥h ʻáláֽy⁠w׃"],[2,2,"וַ⁠יֹּ֣אמֶר הַ֠⁠מֶּלֶךְ לִ⁠קְרֹ֨א לַֽ⁠חַרְטֻמִּ֜ים וְ⁠לָֽ⁠אַשָּׁפִ֗ים וְ⁠לַֽ⁠מְכַשְּׁפִים֙ וְ⁠לַ⁠כַּשְׂדִּ֔ים לְ⁠הַגִּ֥יד לַ⁠מֶּ֖לֶךְ חֲלֹמֹתָ֑י⁠ו וַ⁠יָּבֹ֕אוּ וַ⁠יַּֽעַמְד֖וּ לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yò֣̇ʼmer ha֠⁠mėlekĕ li⁠qĕrò֨ʼ laֽ⁠ẖarĕtumi̇֜ym wĕ⁠láֽ⁠ʼaşá̇̌pi֗ym wĕ⁠laֽ⁠mĕkaşĕ̇̌piym֙ wĕ⁠la⁠kȧşĕ̂di̇֔ym lĕ⁠hagi֥̇yd la⁠mė֖lekĕ ẖàlòmòţá֑y⁠w wa⁠yá̇bò֕ʼẇ wa⁠yȧֽʻamĕd֖ẇ li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[2,3,"וַ⁠יֹּ֧אמֶר לָ⁠הֶ֛ם הַ⁠מֶּ֖לֶךְ חֲל֣וֹם חָלָ֑מְתִּי וַ⁠תִּפָּ֣עֶם רוּחִ֔⁠י לָ⁠דַ֖עַת אֶֽת־הַ⁠חֲלֽוֹם׃","wa⁠yò֧̇ʼmer lá⁠he֛m ha⁠mė֖lekĕ ẖàl֣wòm ẖálá֑mĕţi̇y wa⁠ţi̇pá֣̇ʻem rẇẖi֔⁠y lá⁠da֖ʻaţ ʼeֽţ-ha⁠ẖàlֽwòm׃"],[2,4,"וַֽ⁠יְדַבְּר֧וּ הַ⁠כַּשְׂדִּ֛ים לַ⁠מֶּ֖לֶךְ אֲרָמִ֑ית מַלְכָּ⁠א֙ לְ⁠עָלְמִ֣ין חֱיִ֔י אֱמַ֥ר חֶלְמָ֛⁠א ל⁠עבדי⁠ך וּ⁠פִשְׁרָ֥⁠א נְחַוֵּֽא׃","waֽ⁠yĕdabĕ̇r֧ẇ ha⁠kȧşĕ̂di֛̇ym la⁠mė֖lekĕ ʼàrámi֑yţ malĕká̇⁠ʼ֙ lĕ⁠ʻálĕmi֣yn ẖèyi֔y ʼèma֥r ẖelĕmá֛⁠ʼ l⁠ʻbdy⁠k ẇ⁠pişĕ̌rá֥⁠ʼ nĕẖawéֽ̇ʼ׃"],[2,5,"עָנֵ֤ה מַלְכָּ⁠א֙ וְ⁠אָמַ֣ר ל⁠כשדי⁠א מִלְּתָ֖⁠א מִנִּ֣⁠י אַזְדָּ֑א הֵ֣ן לָ֤א תְהֽוֹדְעוּנַּ֨⁠נִי֙ חֶלְמָ֣⁠א וּ⁠פִשְׁרֵ֔⁠הּ הַדָּמִין֙ תִּתְעַבְד֔וּן וּ⁠בָתֵּי⁠כ֖וֹן נְוָלִ֥י יִתְּשָׂמֽוּן׃","ʻáné֤h malĕká̇⁠ʼ֙ wĕ⁠ʼáma֣r l⁠kşdy⁠ʼ milĕ̇ţá֖⁠ʼ mini֣̇⁠y ʼazĕdá֑̇ʼ hé֣n lá֤ʼ ţĕhֽwòdĕʻẇnȧ֨⁠niy֙ ẖelĕmá֣⁠ʼ ẇ⁠pişĕ̌ré֔⁠ḣ hadá̇miyn֙ ţi̇ţĕʻabĕd֔ẇn ẇ⁠báţé̇y⁠k֖wòn nĕwáli֥y yiţĕ̇şá̂mֽẇn׃"],[2,6,"וְ⁠הֵ֨ן חֶלְמָ֤⁠א וּ⁠פִשְׁרֵ⁠הּ֙ תְּֽהַחֲוֺ֔ן מַתְּנָ֤ן וּ⁠נְבִזְבָּה֙ וִ⁠יקָ֣ר שַׂגִּ֔יא תְּקַבְּל֖וּן מִן־קֳדָמָ֑⁠י לָהֵ֕ן חֶלְמָ֥⁠א וּ⁠פִשְׁרֵ֖⁠הּ הַחֲוֺֽ⁠נִי׃","wĕ⁠hé֨n ẖelĕmá֤⁠ʼ ẇ⁠pişĕ̌ré⁠ḣ֙ ţĕֽ̇haẖàwֺ֔n maţĕ̇ná֤n ẇ⁠nĕbizĕbá̇h֙ wi⁠yqá֣r şâgi̇֔yʼ ţĕ̇qabĕ̇l֖ẇn min-qodámá֑⁠y láhé֕n ẖelĕmá֥⁠ʼ ẇ⁠pişĕ̌ré֖⁠ḣ haẖàwֺֽ⁠niy׃"],[2,7,"עֲנ֥וֹ תִנְיָנ֖וּת וְ⁠אָמְרִ֑ין מַלְכָּ֕⁠א חֶלְמָ֛⁠א יֵאמַ֥ר לְ⁠עַבְד֖וֹ⁠הִי וּ⁠פִשְׁרָ֥⁠ה נְהַחֲוֵֽה׃","ʻàn֥wò ţinĕyán֖ẇţ wĕ⁠ʼámĕri֑yn malĕká̇֕⁠ʼ ẖelĕmá֛⁠ʼ yéʼma֥r lĕ⁠ʻabĕd֖wò⁠hiy ẇ⁠pişĕ̌rá֥⁠h nĕhaẖàwéֽh׃"],[2,8,"עָנֵ֤ה מַלְכָּ⁠א֙ וְ⁠אָמַ֔ר מִן־יַצִּיב֙ יָדַ֣ע אֲנָ֔ה דִּ֥י עִדָּנָ֖⁠א אַנְתּ֣וּן זָבְנִ֑ין כָּ⁠ל־קֳבֵל֙ דִּ֣י חֲזֵית֔וֹן דִּ֥י אַזְדָּ֖א מִנִּ֥⁠י מִלְּתָֽ⁠א׃","ʻáné֤h malĕká̇⁠ʼ֙ wĕ⁠ʼáma֔r min-yaẕi̇yb֙ yáda֣ʻ ʼàná֔h di֥̇y ʻidá̇ná֖⁠ʼ ʼanĕţ֣̇ẇn zábĕni֑yn ká̇⁠l-qobél֙ di֣̇y ẖàzéyţ֔wòn di֥̇y ʼazĕdá֖̇ʼ mini֥̇⁠y milĕ̇ţáֽ⁠ʼ׃"],[2,9,"דִּ֣י הֵן־חֶלְמָ⁠א֩ לָ֨א תְהֽוֹדְעֻנַּ֜⁠נִי חֲדָה־הִ֣יא דָֽתְ⁠כ֗וֹן וּ⁠מִלָּ֨ה כִדְבָ֤ה וּ⁠שְׁחִיתָה֙ הזמנתון לְ⁠מֵאמַ֣ר קָֽדָמַ֔⁠י עַ֛ד דִּ֥י עִדָּנָ֖⁠א יִשְׁתַּנֵּ֑א לָהֵ֗ן חֶלְמָ⁠א֙ אֱמַ֣רוּ לִ֔⁠י וְֽ⁠אִנְדַּ֕ע דִּ֥י פִשְׁרֵ֖⁠הּ תְּהַחֲוֻנַּֽ⁠נִי׃","di֣̇y hén-ẖelĕmá⁠ʼ֩ lá֨ʼ ţĕhֽwòdĕʻunȧ֜⁠niy ẖàdáh-hi֣yʼ dáֽţĕ⁠k֗wòn ẇ⁠milá̇֨h kidĕbá֤h ẇ⁠şĕ̌ẖiyţáh֙ hzmnţwn lĕ⁠méʼma֣r qáֽdáma֔⁠y ʻa֛d di֥̇y ʻidá̇ná֖⁠ʼ yişĕ̌ţȧné֑̇ʼ láhé֗n ẖelĕmá⁠ʼ֙ ʼèma֣rẇ li֔⁠y wֽĕ⁠ʼinĕdȧ֕ʻ di֥̇y pişĕ̌ré֖⁠ḣ ţĕ̇haẖàwunȧֽ⁠niy׃"],[2,10,"עֲנ֨וֹ כשדי⁠א קֳדָם־מַלְכָּ⁠א֙ וְ⁠אָ֣מְרִ֔ין לָֽא־אִיתַ֤י אֲנָשׁ֙ עַל־יַבֶּשְׁתָּ֔⁠א דִּ֚י מִלַּ֣ת מַלְכָּ֔⁠א יוּכַ֖ל לְ⁠הַחֲוָיָ֑ה כָּ⁠ל־קֳבֵ֗ל דִּ֚י כָּל־מֶ֨לֶךְ֙ רַ֣ב וְ⁠שַׁלִּ֔יט מִלָּ֤ה כִ⁠דְנָה֙ לָ֣א שְׁאֵ֔ל לְ⁠כָל־חַרְטֹּ֖ם וְ⁠אָשַׁ֥ף וְ⁠כַשְׂדָּֽי׃","ʻàn֨wò kşdy⁠ʼ qodám-malĕká̇⁠ʼ֙ wĕ⁠ʼá֣mĕri֔yn láֽʼ-ʼiyţa֤y ʼànáş̌֙ ʻal-yabėşĕ̌ţá̇֔⁠ʼ di֚̇y milȧ֣ţ malĕká̇֔⁠ʼ yẇka֖l lĕ⁠haẖàwáyá֑h ká̇⁠l-qobé֗l di֚̇y ká̇l-me֨lekĕ֙ ra֣b wĕ⁠şǎli̇֔yt milá֤̇h ki⁠dĕnáh֙ lá֣ʼ şĕ̌ʼé֔l lĕ⁠kál-ẖarĕtò֖̇m wĕ⁠ʼáşǎ֥p wĕ⁠kaşĕ̂dáֽ̇y׃"],[2,11,"וּ⁠מִלְּתָ֨⁠א דִֽי־מַלְכָּ֤⁠ה שָׁאֵל֙ יַקִּירָ֔ה וְ⁠אָחֳרָן֙ לָ֣א אִיתַ֔י דִּ֥י יְחַוִּנַּ֖⁠הּ קֳדָ֣ם מַלְכָּ֑⁠א לָהֵ֣ן אֱלָהִ֔ין דִּ֚י מְדָ֣רְ⁠ה֔וֹן עִם־בִּשְׂרָ֖⁠א לָ֥א אִיתֽוֹ⁠הִי׃","ẇ⁠milĕ̇ţá֨⁠ʼ diֽy-malĕká֤̇⁠h şá̌ʼél֙ yaqi̇yrá֔h wĕ⁠ʼáẖorán֙ lá֣ʼ ʼiyţa֔y di֥̇y yĕẖawi̇nȧ֖⁠ḣ qodá֣m malĕká֑̇⁠ʼ láhé֣n ʼèláhi֔yn di֚̇y mĕdá֣rĕ⁠h֔wòn ʻim-bi̇şĕ̂rá֖⁠ʼ lá֥ʼ ʼiyţֽwò⁠hiy׃"],[2,12,"כָּ⁠ל־קֳבֵ֣ל דְּנָ֔ה מַלְכָּ֕⁠א בְּנַ֖ס וּ⁠קְצַ֣ף שַׂגִּ֑יא וַ⁠אֲמַר֙ לְ⁠ה֣וֹבָדָ֔ה לְ⁠כֹ֖ל חַכִּימֵ֥י בָבֶֽל׃","ká̇⁠l-qobé֣l dĕ̇ná֔h malĕká̇֕⁠ʼ bĕ̇na֖s ẇ⁠qĕẕa֣p şâgi֑̇yʼ wa⁠ʼàmar֙ lĕ⁠h֣wòbádá֔h lĕ⁠kò֖l ẖaki̇ymé֥y bábeֽl׃"],[2,13,"וְ⁠דָתָ֣⁠א נֶפְקַ֔ת וְ⁠חַכִּֽימַיָּ֖⁠א מִֽתְקַטְּלִ֑ין וּ⁠בְע֛וֹ דָּנִיֵּ֥אל וְ⁠חַבְר֖וֹ⁠הִי לְ⁠הִתְקְטָלָֽה׃פ","wĕ⁠dáţá֣⁠ʼ nepĕqa֔ţ wĕ⁠ẖakiֽ̇ymayá֖̇⁠ʼ miֽţĕqatĕ̇li֑yn ẇ⁠bĕʻ֛wò dá̇niyé֥̇ʼl wĕ⁠ẖabĕr֖wò⁠hiy lĕ⁠hiţĕqĕtáláֽh׃p"],[2,14,"בֵּ⁠אדַ֣יִן דָּנִיֵּ֗אל הֲתִיב֙ עֵטָ֣א וּ⁠טְעֵ֔ם לְ⁠אַרְי֕וֹךְ רַב־טַבָּחַיָּ֖⁠א דִּ֣י מַלְכָּ֑⁠א דִּ֚י נְפַ֣ק לְ⁠קַטָּלָ֔ה לְ⁠חַכִּימֵ֖י בָּבֶֽל׃","bé̇⁠ʼda֣yin dá̇niyé̇֗ʼl hàţiyb֙ ʻétá֣ʼ ẇ⁠tĕʻé֔m lĕ⁠ʼarĕy֕wòkĕ rab-tabá̇ẖayá֖̇⁠ʼ di֣̇y malĕká֑̇⁠ʼ di֚̇y nĕpa֣q lĕ⁠qatá̇lá֔h lĕ⁠ẖaki̇ymé֖y bá̇beֽl׃"],[2,15,"עָנֵ֣ה וְ⁠אָמַ֗ר לְ⁠אַרְיוֹךְ֙ שַׁלִּיטָ֣⁠א דִֽי־מַלְכָּ֔⁠א עַל־מָ֥ה דָתָ֛⁠א מְהַחְצְפָ֖ה מִן־קֳדָ֣ם מַלְכָּ֑⁠א אֱדַ֣יִן מִלְּתָ֔⁠א הוֹדַ֥ע אַרְי֖וֹךְ לְ⁠דָנִיֵּֽאל׃","ʻáné֣h wĕ⁠ʼáma֗r lĕ⁠ʼarĕywòkĕ֙ şǎli̇ytá֣⁠ʼ diֽy-malĕká̇֔⁠ʼ ʻal-má֥h dáţá֛⁠ʼ mĕhaẖĕẕĕpá֖h min-qodá֣m malĕká֑̇⁠ʼ ʼèda֣yin milĕ̇ţá֔⁠ʼ hwòda֥ʻ ʼarĕy֖wòkĕ lĕ⁠dániyéֽ̇ʼl׃"],[2,16,"וְ⁠דָ֣נִיֵּ֔אל עַ֖ל וּ⁠בְעָ֣ה מִן־מַלְכָּ֑⁠א דִּ֚י זְמָ֣ן יִנְתֵּן־לֵ֔⁠הּ וּ⁠פִשְׁרָ֖⁠א לְ⁠הַֽחֲוָיָ֥ה לְ⁠מַלְכָּֽ⁠א׃פ","wĕ⁠dá֣niyé̇֔ʼl ʻa֖l ẇ⁠bĕʻá֣h min-malĕká֑̇⁠ʼ di֚̇y zĕmá֣n yinĕţé̇n-lé֔⁠ḣ ẇ⁠pişĕ̌rá֖⁠ʼ lĕ⁠haֽẖàwáyá֥h lĕ⁠malĕkáֽ̇⁠ʼ׃p"],[2,17,"אֱדַ֥יִן דָּֽנִיֵּ֖אל לְ⁠בַיְתֵ֣⁠הּ אֲזַ֑ל וְ֠⁠לַ⁠חֲנַנְיָה מִֽישָׁאֵ֧ל וַ⁠עֲזַרְיָ֛ה חַבְר֖וֹ⁠הִי מִלְּתָ֥⁠א הוֹדַֽע׃","ʼèda֥yin dáֽ̇niyé֖̇ʼl lĕ⁠bayĕţé֣⁠ḣ ʼàza֑l wĕ֠⁠la⁠ẖànanĕyáh miֽyşá̌ʼé֧l wa⁠ʻàzarĕyá֛h ẖabĕr֖wò⁠hiy milĕ̇ţá֥⁠ʼ hwòdaֽʻ׃"],[2,18,"וְ⁠רַחֲמִ֗ין לְ⁠מִבְעֵא֙ מִן־קֳדָם֙ אֱלָ֣הּ שְׁמַיָּ֔⁠א עַל־רָזָ֖⁠ה דְּנָ֑ה דִּ֣י לָ֤א יְהֹֽבְדוּן֙ דָּנִיֵּ֣אל וְ⁠חַבְר֔וֹ⁠הִי עִם־שְׁאָ֖ר חַכִּימֵ֥י בָבֶֽל׃","wĕ⁠raẖàmi֗yn lĕ⁠mibĕʻéʼ֙ min-qodám֙ ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ ʻal-rázá֖⁠h dĕ̇ná֑h di֣̇y lá֤ʼ yĕhòֽbĕdẇn֙ dá̇niyé֣̇ʼl wĕ⁠ẖabĕr֔wò⁠hiy ʻim-şĕ̌ʼá֖r ẖaki̇ymé֥y bábeֽl׃"],[2,19,"אֱדַ֗יִן לְ⁠דָנִיֵּ֛אל בְּ⁠חֶזְוָ֥⁠א דִֽי־לֵילְיָ֖⁠א רָזָ֣⁠ה גֲלִ֑י אֱדַ֨יִן֙ דָּֽנִיֵּ֔אל בָּרִ֖ךְ לֶ⁠אֱלָ֥הּ שְׁמַיָּֽ⁠א׃","ʼèda֗yin lĕ⁠dániyé֛̇ʼl bĕ̇⁠ẖezĕwá֥⁠ʼ diֽy-léylĕyá֖⁠ʼ rázá֣⁠h gàli֑y ʼèda֨yin֙ dáֽ̇niyé̇֔ʼl bá̇ri֖kĕ le⁠ʼèlá֥ḣ şĕ̌mayáֽ̇⁠ʼ׃"],[2,20,"עָנֵ֤ה דָֽנִיֵּאל֙ וְ⁠אָמַ֔ר לֶהֱוֵ֨א שְׁמֵ֤⁠הּ דִּֽי־אֱלָהָ⁠א֙ מְבָרַ֔ךְ מִן־עָלְמָ֖⁠א וְ⁠עַ֣ד־עָלְמָ֑⁠א דִּ֧י חָכְמְתָ֛⁠א וּ⁠גְבוּרְתָ֖⁠א דִּ֥י לֵֽ⁠הּ־הִֽיא׃","ʻáné֤h dáֽniyé̇ʼl֙ wĕ⁠ʼáma֔r lehèwé֨ʼ şĕ̌mé֤⁠ḣ diֽ̇y-ʼèláhá⁠ʼ֙ mĕbára֔kĕ min-ʻálĕmá֖⁠ʼ wĕ⁠ʻa֣d-ʻálĕmá֑⁠ʼ di֧̇y ẖákĕmĕţá֛⁠ʼ ẇ⁠gĕbẇrĕţá֖⁠ʼ di֥̇y léֽ⁠ḣ-hiֽyʼ׃"],[2,21,"וְ֠⁠הוּא מְהַשְׁנֵ֤א עִדָּנַיָּ⁠א֙ וְ⁠זִמְנַיָּ֔⁠א מְהַעְדֵּ֥ה מַלְכִ֖ין וּ⁠מְהָקֵ֣ים מַלְכִ֑ין יָהֵ֤ב חָכְמְתָ⁠א֙ לְ⁠חַכִּימִ֔ין וּ⁠מַנְדְּעָ֖⁠א לְ⁠יָדְעֵ֥י בִינָֽה׃","wĕ֠⁠hẇʼ mĕhaşĕ̌né֤ʼ ʻidá̇nayá̇⁠ʼ֙ wĕ⁠zimĕnayá̇֔⁠ʼ mĕhaʻĕdé֥̇h malĕki֖yn ẇ⁠mĕháqé֣ym malĕki֑yn yáhé֤b ẖákĕmĕţá⁠ʼ֙ lĕ⁠ẖaki̇ymi֔yn ẇ⁠manĕdĕ̇ʻá֖⁠ʼ lĕ⁠yádĕʻé֥y biynáֽh׃"],[2,22,"ה֛וּא גָּלֵ֥א עַמִּיקָתָ֖⁠א וּ⁠מְסַתְּרָתָ֑⁠א יָדַע֙ מָ֣ה בַ⁠חֲשׁוֹכָ֔⁠א ו⁠נהיר⁠א עִמֵּ֥⁠הּ שְׁרֵֽא׃","h֛ẇʼ gá̇lé֥ʼ ʻami̇yqáţá֖⁠ʼ ẇ⁠mĕsaţĕ̇ráţá֑⁠ʼ yádaʻ֙ má֣h ba⁠ẖàş̌wòká֔⁠ʼ w⁠nhyr⁠ʼ ʻimé֥̇⁠ḣ şĕ̌réֽʼ׃"],[2,23,"לָ֣⁠ךְ ׀ אֱלָ֣הּ אֲבָהָתִ֗⁠י מְהוֹדֵ֤א וּ⁠מְשַׁבַּח֙ אֲנָ֔ה דִּ֧י חָכְמְתָ֛⁠א וּ⁠גְבוּרְתָ֖⁠א יְהַ֣בְתְּ לִ֑⁠י וּ⁠כְעַ֤ן הֽוֹדַעְתַּ֨⁠נִי֙ דִּֽי־בְעֵ֣ינָא מִנָּ֔⁠ךְ דִּֽי־מִלַּ֥ת מַלְכָּ֖⁠א הוֹדַעְתֶּֽ⁠נָא׃","lá֣⁠kĕ ׀ ʼèlá֣ḣ ʼàbáháţi֗⁠y mĕhwòdé֤ʼ ẇ⁠mĕşǎbȧẖ֙ ʼàná֔h di֧̇y ẖákĕmĕţá֛⁠ʼ ẇ⁠gĕbẇrĕţá֖⁠ʼ yĕha֣bĕţĕ̇ li֑⁠y ẇ⁠kĕʻa֤n hֽwòdaʻĕţȧ֨⁠niy֙ diֽ̇y-bĕʻé֣ynáʼ miná̇֔⁠kĕ diֽ̇y-milȧ֥ţ malĕká֖̇⁠ʼ hwòdaʻĕţėֽ⁠náʼ׃"],[2,24,"כָּ⁠ל־קֳבֵ֣ל דְּנָ֗ה דָּֽנִיֵּאל֙ עַ֣ל עַל־אַרְי֔וֹךְ דִּ֚י מַנִּ֣י מַלְכָּ֔⁠א לְ⁠הוֹבָדָ֖ה לְ⁠חַכִּימֵ֣י בָבֶ֑ל אֲזַ֣ל ׀ וְ⁠כֵ֣ן אֲמַר־לֵ֗⁠הּ לְ⁠חַכִּימֵ֤י בָבֶל֙ אַל־תְּהוֹבֵ֔ד הַעֵ֨לְ⁠נִי֙ קֳדָ֣ם מַלְכָּ֔⁠א וּ⁠פִשְׁרָ֖⁠א לְ⁠מַלְכָּ֥⁠א אֲחַוֵּֽא׃ס","ká̇⁠l-qobé֣l dĕ̇ná֗h dáֽ̇niyé̇ʼl֙ ʻa֣l ʻal-ʼarĕy֔wòkĕ di֚̇y mani֣̇y malĕká̇֔⁠ʼ lĕ⁠hwòbádá֖h lĕ⁠ẖaki̇ymé֣y bábe֑l ʼàza֣l ׀ wĕ⁠ké֣n ʼàmar-lé֗⁠ḣ lĕ⁠ẖaki̇ymé֤y bábel֙ ʼal-ţĕ̇hwòbé֔d haʻé֨lĕ⁠niy֙ qodá֣m malĕká̇֔⁠ʼ ẇ⁠pişĕ̌rá֖⁠ʼ lĕ⁠malĕká֥̇⁠ʼ ʼàẖawéֽ̇ʼ׃s"],[2,25,"אֱדַ֤יִן אַרְיוֹךְ֙ בְּ⁠הִתְבְּהָלָ֔ה הַנְעֵ֥ל לְ⁠דָנִיֵּ֖אל קֳדָ֣ם מַלְכָּ֑⁠א וְ⁠כֵ֣ן אֲמַר־לֵ֗⁠הּ דִּֽי־הַשְׁכַּ֤חַת גְּבַר֙ מִן־בְּנֵ֤י גָֽלוּתָ⁠א֙ דִּ֣י יְה֔וּד דִּ֥י פִשְׁרָ֖⁠א לְ⁠מַלְכָּ֥⁠א יְהוֹדַֽע׃","ʼèda֤yin ʼarĕywòkĕ֙ bĕ̇⁠hiţĕbĕ̇hálá֔h hanĕʻé֥l lĕ⁠dániyé֖̇ʼl qodá֣m malĕká֑̇⁠ʼ wĕ⁠ké֣n ʼàmar-lé֗⁠ḣ diֽ̇y-haşĕ̌kȧ֤ẖaţ gĕ̇bar֙ min-bĕ̇né֤y gáֽlẇţá⁠ʼ֙ di֣̇y yĕh֔ẇd di֥̇y pişĕ̌rá֖⁠ʼ lĕ⁠malĕká֥̇⁠ʼ yĕhwòdaֽʻ׃"],[2,26,"עָנֵ֤ה מַלְכָּ⁠א֙ וְ⁠אָמַ֣ר לְ⁠דָנִיֵּ֔אל דִּ֥י שְׁמֵ֖⁠הּ בֵּלְטְשַׁאצַּ֑ר ה⁠איתי⁠ך כָּהֵ֗ל לְ⁠הוֹדָעֻתַ֛⁠נִי חֶלְמָ֥⁠א דִֽי־חֲזֵ֖ית וּ⁠פִשְׁרֵֽ⁠הּ׃","ʻáné֤h malĕká̇⁠ʼ֙ wĕ⁠ʼáma֣r lĕ⁠dániyé̇֔ʼl di֥̇y şĕ̌mé֖⁠ḣ bé̇lĕtĕşǎʼẕȧ֑r h⁠ʼyţy⁠k ká̇hé֗l lĕ⁠hwòdáʻuţa֛⁠niy ẖelĕmá֥⁠ʼ diֽy-ẖàzé֖yţ ẇ⁠pişĕ̌réֽ⁠ḣ׃"],[2,27,"עָנֵ֧ה דָנִיֵּ֛אל קֳדָ֥ם מַלְכָּ֖⁠א וְ⁠אָמַ֑ר רָזָ⁠ה֙ דִּֽי־מַלְכָּ֣⁠א שָׁאֵ֔ל לָ֧א חַכִּימִ֣ין אָֽשְׁפִ֗ין חַרְטֻמִּין֙ גָּזְרִ֔ין יָכְלִ֖ין לְ⁠הַֽחֲוָיָ֥ה לְ⁠מַלְכָּֽ⁠א׃","ʻáné֧h dániyé֛̇ʼl qodá֥m malĕká֖̇⁠ʼ wĕ⁠ʼáma֑r rázá⁠h֙ diֽ̇y-malĕká֣̇⁠ʼ şá̌ʼé֔l lá֧ʼ ẖaki̇ymi֣yn ʼáֽşĕ̌pi֗yn ẖarĕtumi̇yn֙ gá̇zĕri֔yn yákĕli֖yn lĕ⁠haֽẖàwáyá֥h lĕ⁠malĕkáֽ̇⁠ʼ׃"],[2,28,"בְּרַ֡ם אִיתַ֞י אֱלָ֤הּ בִּ⁠שְׁמַיָּ⁠א֙ גָּלֵ֣א רָזִ֔ין וְ⁠הוֹדַ֗ע לְ⁠מַלְכָּ⁠א֙ נְבֽוּכַדְנֶצַּ֔ר מָ֛ה דִּ֥י לֶהֱוֵ֖א בְּ⁠אַחֲרִ֣ית יוֹמַיָּ֑⁠א חֶלְמָ֨⁠ךְ וְ⁠חֶזְוֵ֥י רֵאשָׁ֛⁠ךְ עַֽל־מִשְׁכְּבָ֖⁠ךְ דְּנָ֥ה הֽוּא׃פ","bĕ̇ra֡m ʼiyţa֞y ʼèlá֤ḣ bi̇⁠şĕ̌mayá̇⁠ʼ֙ gá̇lé֣ʼ rázi֔yn wĕ⁠hwòda֗ʻ lĕ⁠malĕká̇⁠ʼ֙ nĕbֽẇkadĕneẕȧ֔r má֛h di֥̇y lehèwé֖ʼ bĕ̇⁠ʼaẖàri֣yţ ywòmayá֑̇⁠ʼ ẖelĕmá֨⁠kĕ wĕ⁠ẖezĕwé֥y réʼşá֛̌⁠kĕ ʻaֽl-mişĕ̌kĕ̇bá֖⁠kĕ dĕ̇ná֥h hֽẇʼ׃p"],[2,29,"אַ֣נְתְּה מַלְכָּ֗⁠א רַעְיוֹנָ⁠ךְ֙ עַל־מִשְׁכְּבָ֣⁠ךְ סְלִ֔קוּ מָ֛ה דִּ֥י לֶהֱוֵ֖א אַחֲרֵ֣י דְנָ֑ה וְ⁠גָלֵ֧א רָזַיָּ֛⁠א הוֹדְעָ֖⁠ךְ מָה־דִ֥י לֶהֱוֵֽא׃","ʼa֣nĕţĕ̇h malĕká̇֗⁠ʼ raʻĕywòná⁠kĕ֙ ʻal-mişĕ̌kĕ̇bá֣⁠kĕ sĕli֔qẇ má֛h di֥̇y lehèwé֖ʼ ʼaẖàré֣y dĕná֑h wĕ⁠gálé֧ʼ rázayá֛̇⁠ʼ hwòdĕʻá֖⁠kĕ máh-di֥y lehèwéֽʼ׃"],[2,30,"וַ⁠אֲנָ֗ה לָ֤א בְ⁠חָכְמָה֙ דִּֽי־אִיתַ֥י בִּ⁠י֙ מִן־כָּל־חַיַּיָּ֔⁠א רָזָ֥⁠א דְנָ֖ה גֱּלִ֣י לִ֑⁠י לָהֵ֗ן עַל־דִּבְרַת֙ דִּ֤י פִשְׁרָ⁠א֙ לְ⁠מַלְכָּ֣⁠א יְהוֹדְע֔וּן וְ⁠רַעְיוֹנֵ֥י לִבְבָ֖⁠ךְ תִּנְדַּֽע׃","wa⁠ʼàná֗h lá֤ʼ bĕ⁠ẖákĕmáh֙ diֽ̇y-ʼiyţa֥y bi̇⁠y֙ min-ká̇l-ẖayȧyá̇֔⁠ʼ rázá֥⁠ʼ dĕná֖h gè̇li֣y li֑⁠y láhé֗n ʻal-di̇bĕraţ֙ di֤̇y pişĕ̌rá⁠ʼ֙ lĕ⁠malĕká֣̇⁠ʼ yĕhwòdĕʻ֔ẇn wĕ⁠raʻĕywòné֥y libĕbá֖⁠kĕ ţi̇nĕdȧֽʻ׃"],[2,31,"אַ֣נְתְּה מַלְכָּ֗⁠א חָזֵ֤ה הֲוַ֨יְתָ֙ וַ⁠אֲל֨וּ צְלֵ֥ם חַד֙ שַׂגִּ֔יא צַלְמָ֨⁠א דִּכֵּ֥ן רַ֛ב וְ⁠זִיוֵ֥⁠הּ יַתִּ֖יר קָאֵ֣ם לְ⁠קָבְלָ֑⁠ךְ וְ⁠רֵוֵ֖⁠הּ דְּחִֽיל׃","ʼa֣nĕţĕ̇h malĕká̇֗⁠ʼ ẖázé֤h hàwa֨yĕţá֙ wa⁠ʼàl֨ẇ ẕĕlé֥m ẖad֙ şâgi̇֔yʼ ẕalĕmá֨⁠ʼ di̇ké֥̇n ra֛b wĕ⁠ziywé֥⁠ḣ yaţi֖̇yr qáʼé֣m lĕ⁠qábĕlá֑⁠kĕ wĕ⁠réwé֖⁠ḣ dĕ̇ẖiֽyl׃"],[2,32,"ה֣וּא צַלְמָ֗⁠א רֵאשֵׁ⁠הּ֙ דִּֽי־דְהַ֣ב טָ֔ב חֲד֥וֹ⁠הִי וּ⁠דְרָע֖וֹ⁠הִי דִּ֣י כְסַ֑ף מְע֥וֹ⁠הִי וְ⁠יַרְכָתֵ֖⁠הּ דִּ֥י נְחָֽשׁ׃","h֣ẇʼ ẕalĕmá֗⁠ʼ réʼşé̌⁠ḣ֙ diֽ̇y-dĕha֣b tá֔b ẖàd֥wò⁠hiy ẇ⁠dĕráʻ֖wò⁠hiy di֣̇y kĕsa֑p mĕʻ֥wò⁠hiy wĕ⁠yarĕkáţé֖⁠ḣ di֥̇y nĕẖáֽş̌׃"],[2,33,"שָׁק֖וֹ⁠הִי דִּ֣י פַרְזֶ֑ל רַגְל֕וֹ⁠הִי מנ⁠הון דִּ֣י פַרְזֶ֔ל ו⁠מנ⁠הון דִּ֥י חֲסַֽף׃","şá̌q֖wò⁠hiy di֣̇y parĕze֑l ragĕl֕wò⁠hiy mn⁠hwn di֣̇y parĕze֔l w⁠mn⁠hwn di֥̇y ẖàsaֽp׃"],[2,34,"חָזֵ֣ה הֲוַ֗יְתָ עַ֠ד דִּ֣י הִתְגְּזֶ֤רֶת אֶ֨בֶן֙ דִּי־לָ֣א בִ⁠ידַ֔יִן וּ⁠מְחָ֤ת לְ⁠צַלְמָ⁠א֙ עַל־רַגְל֔וֹ⁠הִי דִּ֥י פַרְזְלָ֖⁠א וְ⁠חַסְפָּ֑⁠א וְ⁠הַדֵּ֖קֶת הִמּֽוֹן׃","ẖázé֣h hàwa֗yĕţá ʻa֠d di֣̇y hiţĕgĕ̇ze֤reţ ʼe֨ben֙ di̇y-lá֣ʼ bi⁠yda֔yin ẇ⁠mĕẖá֤ţ lĕ⁠ẕalĕmá⁠ʼ֙ ʻal-ragĕl֔wò⁠hiy di֥̇y parĕzĕlá֖⁠ʼ wĕ⁠ẖasĕpá֑̇⁠ʼ wĕ⁠hadé֖̇qeţ hiṁֽwòn׃"],[2,35,"בֵּ⁠אדַ֣יִן דָּ֣קוּ כַ⁠חֲדָ֡ה פַּרְזְלָ⁠א֩ חַסְפָּ֨⁠א נְחָשָׁ֜⁠א כַּסְפָּ֣⁠א וְ⁠דַהֲבָ֗⁠א וַ⁠הֲווֹ֙ כְּ⁠ע֣וּר מִן־אִדְּרֵי־קַ֔יִט וּ⁠נְשָׂ֤א הִמּוֹן֙ רוּחָ֔⁠א וְ⁠כָל־אֲתַ֖ר לָא־הִשְׁתֲּכַ֣ח לְ⁠ה֑וֹן וְ⁠אַבְנָ֣⁠א ׀ דִּֽי־מְחָ֣ת לְ⁠צַלְמָ֗⁠א הֲוָ֛ת לְ⁠ט֥וּר רַ֖ב וּ⁠מְלָ֥ת כָּל־אַרְעָֽ⁠א׃","bé̇⁠ʼda֣yin dá֣̇qẇ ka⁠ẖàdá֡h pȧrĕzĕlá⁠ʼ֩ ẖasĕpá̇֨⁠ʼ nĕẖáşá̌֜⁠ʼ kȧsĕpá֣̇⁠ʼ wĕ⁠dahàbá֗⁠ʼ wa⁠hàwwò֙ kĕ̇⁠ʻ֣ẇr min-ʼidĕ̇réy-qa֔yit ẇ⁠nĕşá֤̂ʼ hiṁwòn֙ rẇẖá֔⁠ʼ wĕ⁠kál-ʼàţa֖r láʼ-hişĕ̌ţà̇ka֣ẖ lĕ⁠h֑wòn wĕ⁠ʼabĕná֣⁠ʼ ׀ diֽ̇y-mĕẖá֣ţ lĕ⁠ẕalĕmá֗⁠ʼ hàwá֛ţ lĕ⁠t֥ẇr ra֖b ẇ⁠mĕlá֥ţ ká̇l-ʼarĕʻáֽ⁠ʼ׃"],[2,36,"דְּנָ֣ה חֶלְמָ֔⁠א וּ⁠פִשְׁרֵ֖⁠הּ נֵאמַ֥ר קֳדָם־מַלְכָּֽ⁠א׃","dĕ̇ná֣h ẖelĕmá֔⁠ʼ ẇ⁠pişĕ̌ré֖⁠ḣ néʼma֥r qodám-malĕkáֽ̇⁠ʼ׃"],[2,37,"אַ֣נְתְּה מַלְכָּ֔⁠א מֶ֖לֶךְ מַלְכַיָּ֑⁠א דִּ֚י אֱלָ֣הּ שְׁמַיָּ֔⁠א מַלְכוּתָ֥⁠א חִסְנָ֛⁠א וְ⁠תָקְפָּ֥⁠א וִֽ⁠יקָרָ֖⁠א יְהַב־לָֽ⁠ךְ׃","ʼa֣nĕţĕ̇h malĕká̇֔⁠ʼ me֖lekĕ malĕkayá֑̇⁠ʼ di֚̇y ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ malĕkẇţá֥⁠ʼ ẖisĕná֛⁠ʼ wĕ⁠ţáqĕpá֥̇⁠ʼ wiֽ⁠yqárá֖⁠ʼ yĕhab-láֽ⁠kĕ׃"],[2,38,"וּ⁠בְ⁠כָל־דִּ֣י דארין בְּֽנֵי־אֲ֠נָשָׁ⁠א חֵיוַ֨ת בָּרָ֤⁠א וְ⁠עוֹף־שְׁמַיָּ⁠א֙ יְהַ֣ב בִּ⁠ידָ֔⁠ךְ וְ⁠הַשְׁלְטָ֖⁠ךְ בְּ⁠כָלְּ⁠ה֑וֹן אַנְתְּה־ה֔וּא רֵאשָׁ֖⁠ה דִּ֥י דַהֲבָֽ⁠א׃","ẇ⁠bĕ⁠kál-di֣̇y dʼryn bĕֽ̇néy-ʼà֠náşá̌⁠ʼ ẖéywa֨ţ bá̇rá֤⁠ʼ wĕ⁠ʻwòp-şĕ̌mayá̇⁠ʼ֙ yĕha֣b bi̇⁠ydá֔⁠kĕ wĕ⁠haşĕ̌lĕtá֖⁠kĕ bĕ̇⁠kálĕ̇⁠h֑wòn ʼanĕţĕ̇h-h֔ẇʼ réʼşá֖̌⁠h di֥̇y dahàbáֽ⁠ʼ׃"],[2,39,"וּ⁠בָתְרָ֗⁠ךְ תְּק֛וּם מַלְכ֥וּ אָחֳרִ֖י ארע⁠א מִנָּ֑⁠ךְ וּ⁠מַלְכ֨וּ תליתיא אָחֳרִי֙ דִּ֣י נְחָשָׁ֔⁠א דִּ֥י תִשְׁלַ֖ט בְּ⁠כָל־אַרְעָֽ⁠א׃","ẇ⁠báţĕrá֗⁠kĕ ţĕ̇q֛ẇm malĕk֥ẇ ʼáẖori֖y ʼrʻ⁠ʼ miná֑̇⁠kĕ ẇ⁠malĕk֨ẇ ţlyţyʼ ʼáẖoriy֙ di֣̇y nĕẖáşá̌֔⁠ʼ di֥̇y ţişĕ̌la֖t bĕ̇⁠kál-ʼarĕʻáֽ⁠ʼ׃"],[2,40,"וּ⁠מַלְכוּ֙ רביעיה תֶּהֱוֵ֥א תַקִּיפָ֖ה כְּ⁠פַרְזְלָ֑⁠א כָּ⁠ל־קֳבֵ֗ל דִּ֤י פַרְזְלָ⁠א֙ מְהַדֵּ֤ק וְ⁠חָשֵׁל֙ כֹּ֔לָּ⁠א וּֽ⁠כְ⁠פַרְזְלָ֛⁠א דִּֽי־מְרָעַ֥ע כָּל־אִלֵּ֖ין תַּדִּ֥ק וְ⁠תֵרֹֽעַ׃","ẇ⁠malĕkẇ֙ rbyʻyh ţėhèwé֥ʼ ţaqi̇ypá֖h kĕ̇⁠parĕzĕlá֑⁠ʼ ká̇⁠l-qobé֗l di֤̇y parĕzĕlá⁠ʼ֙ mĕhadé֤̇q wĕ⁠ẖáşé̌l֙ kò̇֔lá̇⁠ʼ ẇֽ⁠kĕ⁠parĕzĕlá֛⁠ʼ diֽ̇y-mĕráʻa֥ʻ ká̇l-ʼilé֖̇yn ţȧdi֥̇q wĕ⁠ţéròֽʻa׃"],[2,41,"וְ⁠דִֽי־חֲזַ֜יְתָה רַגְלַיָּ֣⁠א וְ⁠אֶצְבְּעָתָ֗⁠א מנ⁠הון חֲסַ֤ף דִּֽי־פֶחָר֙ ו⁠מנ⁠הון פַּרְזֶ֔ל מַלְכ֤וּ פְלִיגָה֙ תֶּהֱוֵ֔ה וּ⁠מִן־נִצְבְּתָ֥⁠א דִ֥י פַרְזְלָ֖⁠א לֶֽהֱוֵא־בַ֑⁠הּ כָּ⁠ל־קֳבֵל֙ דִּ֣י חֲזַ֔יְתָה פַּ֨רְזְלָ֔⁠א מְעָרַ֖ב בַּ⁠חֲסַ֥ף טִינָֽ⁠א׃","wĕ⁠diֽy-ẖàza֜yĕţáh ragĕlayá֣̇⁠ʼ wĕ⁠ʼeẕĕbĕ̇ʻáţá֗⁠ʼ mn⁠hwn ẖàsa֤p diֽ̇y-peẖár֙ w⁠mn⁠hwn pȧrĕze֔l malĕk֤ẇ pĕliygáh֙ ţėhèwé֔h ẇ⁠min-niẕĕbĕ̇ţá֥⁠ʼ di֥y parĕzĕlá֖⁠ʼ leֽhèwéʼ-ba֑⁠ḣ ká̇⁠l-qobél֙ di֣̇y ẖàza֔yĕţáh pȧ֨rĕzĕlá֔⁠ʼ mĕʻára֖b bȧ⁠ẖàsa֥p tiynáֽ⁠ʼ׃"],[2,42,"וְ⁠אֶצְבְּעָת֙ רַגְלַיָּ֔⁠א מנ⁠הון פַּרְזֶ֖ל ו⁠מנ⁠הון חֲסַ֑ף מִן־קְצָ֤ת מַלְכוּתָ⁠א֙ תֶּהֱוֵ֣ה תַקִּיפָ֔ה וּ⁠מִנַּ֖⁠הּ תֶּהֱוֵ֥ה תְבִירָֽה׃","wĕ⁠ʼeẕĕbĕ̇ʻáţ֙ ragĕlayá̇֔⁠ʼ mn⁠hwn pȧrĕze֖l w⁠mn⁠hwn ẖàsa֑p min-qĕẕá֤ţ malĕkẇţá⁠ʼ֙ ţėhèwé֣h ţaqi̇ypá֔h ẇ⁠minȧ֖⁠ḣ ţėhèwé֥h ţĕbiyráֽh׃"],[2,43,"די חֲזַ֗יְתָ פַּרְזְלָ⁠א֙ מְעָרַב֙ בַּ⁠חֲסַ֣ף טִינָ֔⁠א מִתְעָרְבִ֤ין לֶהֱוֺן֙ בִּ⁠זְרַ֣ע אֲנָשָׁ֔⁠א וְ⁠לָֽא־לֶהֱוֺ֥ן דָּבְקִ֖ין דְּנָ֣ה עִם־דְּנָ֑ה הֵֽא־כְ⁠דִ֣י פַרְזְלָ֔⁠א לָ֥א מִתְעָרַ֖ב עִם־חַסְפָּֽ⁠א׃","dy ẖàza֗yĕţá pȧrĕzĕlá⁠ʼ֙ mĕʻárab֙ bȧ⁠ẖàsa֣p tiyná֔⁠ʼ miţĕʻárĕbi֤yn lehèwֺn֙ bi̇⁠zĕra֣ʻ ʼànáşá̌֔⁠ʼ wĕ⁠láֽʼ-lehèwֺ֥n dá̇bĕqi֖yn dĕ̇ná֣h ʻim-dĕ̇ná֑h héֽʼ-kĕ⁠di֣y parĕzĕlá֔⁠ʼ lá֥ʼ miţĕʻára֖b ʻim-ẖasĕpáֽ̇⁠ʼ׃"],[2,44,"וּֽ⁠בְ⁠יוֹמֵי⁠ה֞וֹן דִּ֧י מַלְכַיָּ֣⁠א אִנּ֗וּן יְקִים֩ אֱלָ֨הּ שְׁמַיָּ֤⁠א מַלְכוּ֙ דִּ֤י לְ⁠עָלְמִין֙ לָ֣א תִתְחַבַּ֔ל וּ⁠מַ֨לְכוּתָ֔⁠ה לְ⁠עַ֥ם אָחֳרָ֖ן לָ֣א תִשְׁתְּבִ֑ק תַּדִּ֤ק וְ⁠תָסֵיף֙ כָּל־אִלֵּ֣ין מַלְכְוָתָ֔⁠א וְ⁠הִ֖יא תְּק֥וּם לְ⁠עָלְמַיָּֽ⁠א׃","ẇֽ⁠bĕ⁠ywòméy⁠h֞wòn di֧̇y malĕkayá֣̇⁠ʼ ʼiṅ֗ẇn yĕqiym֩ ʼèlá֨ḣ şĕ̌mayá֤̇⁠ʼ malĕkẇ֙ di֤̇y lĕ⁠ʻálĕmiyn֙ lá֣ʼ ţiţĕẖabȧ֔l ẇ⁠ma֨lĕkẇţá֔⁠h lĕ⁠ʻa֥m ʼáẖorá֖n lá֣ʼ ţişĕ̌ţĕ̇bi֑q ţȧdi֤̇q wĕ⁠ţáséyp֙ ká̇l-ʼilé֣̇yn malĕkĕwáţá֔⁠ʼ wĕ⁠hi֖yʼ ţĕ̇q֥ẇm lĕ⁠ʻálĕmayáֽ̇⁠ʼ׃"],[2,45,"כָּ⁠ל־קֳבֵ֣ל דִּֽי־חֲזַ֡יְתָ דִּ֣י מִ⁠טּוּרָ⁠א֩ אִתְגְּזֶ֨רֶת אֶ֜בֶן דִּי־לָ֣א בִ⁠ידַ֗יִן וְ֠⁠הַדֶּקֶת פַּרְזְלָ֨⁠א נְחָשָׁ֤⁠א חַסְפָּ⁠א֙ כַּסְפָּ֣⁠א וְ⁠דַהֲבָ֔⁠א אֱלָ֥הּ רַב֙ הוֹדַ֣ע לְ⁠מַלְכָּ֔⁠א מָ֛ה דִּ֥י לֶהֱוֵ֖א אַחֲרֵ֣י דְנָ֑ה וְ⁠יַצִּ֥יב חֶלְמָ֖⁠א וּ⁠מְהֵימַ֥ן פִּשְׁרֵֽ⁠הּ׃פ","ká̇⁠l-qobé֣l diֽ̇y-ẖàza֡yĕţá di֣̇y mi⁠ṫẇrá⁠ʼ֩ ʼiţĕgĕ̇ze֨reţ ʼe֜ben di̇y-lá֣ʼ bi⁠yda֗yin wĕ֠⁠hadėqeţ pȧrĕzĕlá֨⁠ʼ nĕẖáşá֤̌⁠ʼ ẖasĕpá̇⁠ʼ֙ kȧsĕpá֣̇⁠ʼ wĕ⁠dahàbá֔⁠ʼ ʼèlá֥ḣ rab֙ hwòda֣ʻ lĕ⁠malĕká̇֔⁠ʼ má֛h di֥̇y lehèwé֖ʼ ʼaẖàré֣y dĕná֑h wĕ⁠yaẕi֥̇yb ẖelĕmá֖⁠ʼ ẇ⁠mĕhéyma֥n pi̇şĕ̌réֽ⁠ḣ׃p"],[2,46,"בֵּ֠⁠אדַיִן מַלְכָּ֤⁠א נְבֽוּכַדְנֶצַּר֙ נְפַ֣ל עַל־אַנְפּ֔וֹ⁠הִי וּ⁠לְ⁠דָנִיֵּ֖אל סְגִ֑ד וּ⁠מִנְחָה֙ וְ⁠נִ֣יחֹחִ֔ין אֲמַ֖ר לְ⁠נַסָּ֥כָה לֵֽ⁠הּ׃","bé̇֠⁠ʼdayin malĕká֤̇⁠ʼ nĕbֽẇkadĕneẕȧr֙ nĕpa֣l ʻal-ʼanĕṗ֔wò⁠hiy ẇ⁠lĕ⁠dániyé֖̇ʼl sĕgi֑d ẇ⁠minĕẖáh֙ wĕ⁠ni֣yẖòẖi֔yn ʼàma֖r lĕ⁠nasá֥̇káh léֽ⁠ḣ׃"],[2,47,"עָנֵה֩ מַלְכָּ֨⁠א לְ⁠דָנִיֵּ֜אל וְ⁠אָמַ֗ר מִן־קְשֹׁט֙ דִּ֣י אֱלָהֲ⁠כ֗וֹן ה֣וּא אֱלָ֧הּ אֱלָהִ֛ין וּ⁠מָרֵ֥א מַלְכִ֖ין וְ⁠גָלֵ֣ה רָזִ֑ין דִּ֣י יְכֵ֔לְתָּ לְ⁠מִגְלֵ֖א רָזָ֥⁠ה דְנָֽה׃","ʻánéh֩ malĕká̇֨⁠ʼ lĕ⁠dániyé̇֜ʼl wĕ⁠ʼáma֗r min-qĕşò̌t֙ di֣̇y ʼèláhà⁠k֗wòn h֣ẇʼ ʼèlá֧ḣ ʼèláhi֛yn ẇ⁠máré֥ʼ malĕki֖yn wĕ⁠gálé֣h rázi֑yn di֣̇y yĕké֔lĕţá̇ lĕ⁠migĕlé֖ʼ rázá֥⁠h dĕnáֽh׃"],[2,48,"אֱדַ֨יִן מַלְכָּ֜⁠א לְ⁠דָנִיֵּ֣אל רַבִּ֗י וּ⁠מַתְּנָ֨ן רַבְרְבָ֤ן שַׂגִּיאָן֙ יְהַב־לֵ֔⁠הּ וְ⁠הַ֨שְׁלְטֵ֔⁠הּ עַ֖ל כָּל־מְדִינַ֣ת בָּבֶ֑ל וְ⁠רַב־סִגְנִ֔ין עַ֖ל כָּל־חַכִּימֵ֥י בָבֶֽל׃","ʼèda֨yin malĕká̇֜⁠ʼ lĕ⁠dániyé֣̇ʼl rabi̇֗y ẇ⁠maţĕ̇ná֨n rabĕrĕbá֤n şâgi̇yʼán֙ yĕhab-lé֔⁠ḣ wĕ⁠ha֨şĕ̌lĕté֔⁠ḣ ʻa֖l ká̇l-mĕdiyna֣ţ bá̇be֑l wĕ⁠rab-sigĕni֔yn ʻa֖l ká̇l-ẖaki̇ymé֥y bábeֽl׃"],[2,49,"וְ⁠דָנִיֵּאל֙ בְּעָ֣א מִן־מַלְכָּ֔⁠א וּ⁠מַנִּ֗י עַ֤ל עֲבִֽידְתָּ⁠א֙ דִּ֚י מְדִינַ֣ת בָּבֶ֔ל לְ⁠שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ וְ⁠דָנִיֵּ֖אל בִּ⁠תְרַ֥ע מַלְכָּֽ⁠א׃פ","wĕ⁠dániyé̇ʼl֙ bĕ̇ʻá֣ʼ min-malĕká̇֔⁠ʼ ẇ⁠mani̇֗y ʻa֤l ʻàbiֽydĕţá̇⁠ʼ֙ di֚̇y mĕdiyna֣ţ bá̇be֔l lĕ⁠şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò wĕ⁠dániyé֖̇ʼl bi̇⁠ţĕra֥ʻ malĕkáֽ̇⁠ʼ׃p"],[3,1,"נְבוּכַדְנֶצַּ֣ר מַלְכָּ֗⁠א עֲבַד֙ צְלֵ֣ם דִּֽי־דְהַ֔ב רוּמֵ⁠הּ֙ אַמִּ֣ין שִׁתִּ֔ין פְּתָיֵ֖⁠הּ אַמִּ֣ין שִׁ֑ת אֲקִימֵ⁠הּ֙ בְּ⁠בִקְעַ֣ת דּוּרָ֔א בִּ⁠מְדִינַ֖ת בָּבֶֽל׃","nĕbẇkadĕneẕȧ֣r malĕká̇֗⁠ʼ ʻàbad֙ ẕĕlé֣m diֽ̇y-dĕha֔b rẇmé⁠ḣ֙ ʼami֣̇yn şǐţi̇֔yn pĕ̇ţáyé֖⁠ḣ ʼami֣̇yn şǐ֑ţ ʼàqiymé⁠ḣ֙ bĕ̇⁠biqĕʻa֣ţ ḋẇrá֔ʼ bi̇⁠mĕdiyna֖ţ bá̇beֽl׃"],[3,2,"וּ⁠נְבוּכַדְנֶצַּ֣ר מַלְכָּ֡⁠א שְׁלַ֡ח לְ⁠מִכְנַ֣שׁ ׀ לַֽ⁠אֲחַשְׁדַּרְפְּנַיָּ֡⁠א סִגְנַיָּ֣⁠א וּֽ⁠פַחֲוָתָ֡⁠א אֲדַרְגָּזְרַיָּ⁠א֩ גְדָ֨בְרַיָּ֤⁠א דְּתָבְרַיָּ⁠א֙ תִּפְתָּיֵ֔⁠א וְ⁠כֹ֖ל שִׁלְטֹנֵ֣י מְדִֽינָתָ֑⁠א לְ⁠מֵתֵא֙ לַ⁠חֲנֻכַּ֣ת צַלְמָ֔⁠א דִּ֥י הֲקֵ֖ים נְבוּכַדְנֶצַּ֥ר מַלְכָּֽ⁠א׃","ẇ⁠nĕbẇkadĕneẕȧ֣r malĕká̇֡⁠ʼ şĕ̌la֡ẖ lĕ⁠mikĕna֣ş̌ ׀ laֽ⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇֡⁠ʼ sigĕnayá֣̇⁠ʼ ẇֽ⁠paẖàwáţá֡⁠ʼ ʼàdarĕgá̇zĕrayá̇⁠ʼ֩ gĕdá֨bĕrayá֤̇⁠ʼ dĕ̇ţábĕrayá̇⁠ʼ֙ ţi̇pĕţá̇yé֔⁠ʼ wĕ⁠kò֖l şǐlĕtòné֣y mĕdiֽynáţá֑⁠ʼ lĕ⁠méţéʼ֙ la⁠ẖànukȧ֣ţ ẕalĕmá֔⁠ʼ di֥̇y hàqé֖ym nĕbẇkadĕneẕȧ֥r malĕkáֽ̇⁠ʼ׃"],[3,3,"בֵּ⁠אדַ֡יִן מִֽתְכַּנְּשִׁ֡ין אֲחַשְׁדַּרְפְּנַיָּ֡⁠א סִגְנַיָּ֣⁠א וּֽ⁠פַחֲוָתָ֡⁠א אֲדַרְגָּזְרַיָּ֣⁠א גְדָבְרַיָּ⁠א֩ דְּתָ֨בְרַיָּ֜⁠א תִּפְתָּיֵ֗⁠א וְ⁠כֹל֙ שִׁלְטֹנֵ֣י מְדִֽינָתָ֔⁠א לַ⁠חֲנֻכַּ֣ת צַלְמָ֔⁠א דִּ֥י הֲקֵ֖ים נְבוּכַדְנֶצַּ֣ר מַלְכָּ֑⁠א ו⁠קאמין לָ⁠קֳבֵ֣ל צַלְמָ֔⁠א דִּ֥י הֲקֵ֖ים נְבוּכַדְנֶצַּֽר׃","bé̇⁠ʼda֡yin miֽţĕkȧnĕ̇şǐ֡yn ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇֡⁠ʼ sigĕnayá֣̇⁠ʼ ẇֽ⁠paẖàwáţá֡⁠ʼ ʼàdarĕgá̇zĕrayá֣̇⁠ʼ gĕdábĕrayá̇⁠ʼ֩ dĕ̇ţá֨bĕrayá̇֜⁠ʼ ţi̇pĕţá̇yé֗⁠ʼ wĕ⁠kòl֙ şǐlĕtòné֣y mĕdiֽynáţá֔⁠ʼ la⁠ẖànukȧ֣ţ ẕalĕmá֔⁠ʼ di֥̇y hàqé֖ym nĕbẇkadĕneẕȧ֣r malĕká֑̇⁠ʼ w⁠qʼmyn lá⁠qobé֣l ẕalĕmá֔⁠ʼ di֥̇y hàqé֖ym nĕbẇkadĕneẕȧֽr׃"],[3,4,"וְ⁠כָרוֹזָ֖⁠א קָרֵ֣א בְ⁠חָ֑יִל לְ⁠כ֤וֹן אָֽמְרִין֙ עַֽמְמַיָּ֔⁠א אֻמַּיָּ֖⁠א וְ⁠לִשָּׁנַיָּֽ⁠א׃","wĕ⁠kárwòzá֖⁠ʼ qáré֣ʼ bĕ⁠ẖá֑yil lĕ⁠k֤wòn ʼáֽmĕriyn֙ ʻaֽmĕmayá̇֔⁠ʼ ʼumȧyá֖̇⁠ʼ wĕ⁠lişá̇̌nayáֽ̇⁠ʼ׃"],[3,5,"בְּ⁠עִדָּנָ֡⁠א דִּֽי־תִשְׁמְע֡וּן קָ֣ל קַרְנָ֣⁠א מַ֠שְׁרוֹקִיתָ⁠א קיתרוס סַבְּכָ֤א פְּסַנְתֵּרִין֙ סוּמְפֹּ֣נְיָ֔ה וְ⁠כֹ֖ל זְנֵ֣י זְמָרָ֑⁠א תִּפְּל֤וּן וְ⁠תִסְגְּדוּן֙ לְ⁠צֶ֣לֶם דַּהֲבָ֔⁠א דִּ֥י הֲקֵ֖ים נְבוּכַדְנֶצַּ֥ר מַלְכָּֽ⁠א׃","bĕ̇⁠ʻidá̇ná֡⁠ʼ diֽ̇y-ţişĕ̌mĕʻ֡ẇn qá֣l qarĕná֣⁠ʼ ma֠şĕ̌rwòqiyţá⁠ʼ qyţrws sabĕ̇ká֤ʼ pĕ̇sanĕţé̇riyn֙ sẇmĕpò֣̇nĕyá֔h wĕ⁠kò֖l zĕné֣y zĕmárá֑⁠ʼ ţi̇pĕ̇l֤ẇn wĕ⁠ţisĕgĕ̇dẇn֙ lĕ⁠ẕe֣lem dȧhàbá֔⁠ʼ di֥̇y hàqé֖ym nĕbẇkadĕneẕȧ֥r malĕkáֽ̇⁠ʼ׃"],[3,6,"וּ⁠מַן־דִּי־לָ֥א יִפֵּ֖ל וְ⁠יִסְגֻּ֑ד בַּ⁠הּ־שַׁעֲתָ֣⁠א יִתְרְמֵ֔א לְ⁠גֽוֹא־אַתּ֥וּן נוּרָ֖⁠א יָקִֽדְתָּֽ⁠א׃","ẇ⁠man-di̇y-lá֥ʼ yipé֖̇l wĕ⁠yisĕgu֑̇d bȧ⁠ḣ-şǎʻàţá֣⁠ʼ yiţĕrĕmé֔ʼ lĕ⁠gֽwòʼ-ʼaţ֥̇ẇn nẇrá֖⁠ʼ yáqiֽdĕţáֽ̇⁠ʼ׃"],[3,7,"כָּ⁠ל־קֳבֵ֣ל דְּנָ֡ה בֵּ⁠הּ־זִמְנָ֡⁠א כְּ⁠דִ֣י שָֽׁמְעִ֣ין כָּֽל־עַמְמַיָּ֡⁠א קָ֣ל קַרְנָ⁠א֩ מַשְׁר֨וֹקִיתָ֜⁠א קיתרס שַׂבְּכָא֙ פְּסַנְטֵרִ֔ין וְ⁠כֹ֖ל זְנֵ֣י זְמָרָ֑⁠א נָֽפְלִ֨ין כָּֽל־עַֽמְמַיָּ֜⁠א אֻמַיָּ֣⁠א וְ⁠לִשָּׁנַיָּ֗⁠א סָֽגְדִין֙ לְ⁠צֶ֣לֶם דַּהֲבָ֔⁠א דִּ֥י הֲקֵ֖ים נְבוּכַדְנֶצַּ֥ר מַלְכָּֽ⁠א׃","ká̇⁠l-qobé֣l dĕ̇ná֡h bé̇⁠ḣ-zimĕná֡⁠ʼ kĕ̇⁠di֣y şáֽ̌mĕʻi֣yn káֽ̇l-ʻamĕmayá̇֡⁠ʼ qá֣l qarĕná⁠ʼ֩ maşĕ̌r֨wòqiyţá֜⁠ʼ qyţrs şâbĕ̇káʼ֙ pĕ̇sanĕtéri֔yn wĕ⁠kò֖l zĕné֣y zĕmárá֑⁠ʼ náֽpĕli֨yn káֽ̇l-ʻaֽmĕmayá̇֜⁠ʼ ʼumayá֣̇⁠ʼ wĕ⁠lişá̇̌nayá̇֗⁠ʼ sáֽgĕdiyn֙ lĕ⁠ẕe֣lem dȧhàbá֔⁠ʼ di֥̇y hàqé֖ym nĕbẇkadĕneẕȧ֥r malĕkáֽ̇⁠ʼ׃"],[3,8,"כָּ⁠ל־קֳבֵ֤ל דְּנָה֙ בֵּ⁠הּ־זִמְנָ֔⁠א קְרִ֖בוּ גֻּבְרִ֣ין כַּשְׂדָּאִ֑ין וַ⁠אֲכַ֥לוּ קַרְצֵי⁠ה֖וֹן דִּ֥י יְהוּדָיֵֽ⁠א׃","ká̇⁠l-qobé֤l dĕ̇náh֙ bé̇⁠ḣ-zimĕná֔⁠ʼ qĕri֖bẇ gu̇bĕri֣yn kȧşĕ̂dá̇ʼi֑yn wa⁠ʼàka֥lẇ qarĕẕéy⁠h֖wòn di֥̇y yĕhẇdáyéֽ⁠ʼ׃"],[3,9,"עֲנוֹ֙ וְ⁠אָ֣מְרִ֔ין לִ⁠נְבוּכַדְנֶצַּ֖ר מַלְכָּ֑⁠א מַלְכָּ֖⁠א לְ⁠עָלְמִ֥ין חֱיִֽי׃","ʻànwò֙ wĕ⁠ʼá֣mĕri֔yn li⁠nĕbẇkadĕneẕȧ֖r malĕká֑̇⁠ʼ malĕká֖̇⁠ʼ lĕ⁠ʻálĕmi֥yn ẖèyiֽy׃"],[3,10,"אנתה מַלְכָּ⁠א֮ שָׂ֣מְתָּ טְּעֵם֒ דִּ֣י כָל־אֱנָ֡שׁ דִּֽי־יִשְׁמַ֡ע קָ֣ל קַרְנָ֣⁠א מַ֠שְׁרֹקִיתָ⁠א קיתרס שַׂבְּכָ֤א פְסַנְתֵּרִין֙ ו⁠סיפניה וְ⁠כֹ֖ל זְנֵ֣י זְמָרָ֑⁠א יִפֵּ֥ל וְ⁠יִסְגֻּ֖ד לְ⁠צֶ֥לֶם דַּהֲבָֽ⁠א׃","ʼnţh malĕká̇⁠ʼ֮ şá֣̂mĕţá̇ tĕ̇ʻém֒ di֣̇y kál-ʼèná֡ş̌ diֽ̇y-yişĕ̌ma֡ʻ qá֣l qarĕná֣⁠ʼ ma֠şĕ̌ròqiyţá⁠ʼ qyţrs şâbĕ̇ká֤ʼ pĕsanĕţé̇riyn֙ w⁠sypnyh wĕ⁠kò֖l zĕné֣y zĕmárá֑⁠ʼ yipé֥̇l wĕ⁠yisĕgu֖̇d lĕ⁠ẕe֥lem dȧhàbáֽ⁠ʼ׃"],[3,11,"וּ⁠מַן־דִּי־לָ֥א יִפֵּ֖ל וְ⁠יִסְגֻּ֑ד יִתְרְמֵ֕א לְ⁠גֽוֹא־אַתּ֥וּן נוּרָ֖⁠א יָקִֽדְתָּֽ⁠א׃","ẇ⁠man-di̇y-lá֥ʼ yipé֖̇l wĕ⁠yisĕgu֑̇d yiţĕrĕmé֕ʼ lĕ⁠gֽwòʼ-ʼaţ֥̇ẇn nẇrá֖⁠ʼ yáqiֽdĕţáֽ̇⁠ʼ׃"],[3,12,"אִיתַ֞י גֻּבְרִ֣ין יְהוּדָאיִ֗ן דִּֽי־מַנִּ֤יתָ יָתְ⁠הוֹן֙ עַל־עֲבִידַת֙ מְדִינַ֣ת בָּבֶ֔ל שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ גֻּבְרַיָּ֣⁠א אִלֵּ֗ךְ לָא־שָׂ֨מֽוּ עלי⁠ך מַלְכָּ⁠א֙ טְעֵ֔ם ל⁠אלהי⁠ך לָ֣א פָלְחִ֔ין וּ⁠לְ⁠צֶ֧לֶם דַּהֲבָ֛⁠א דִּ֥י הֲקֵ֖ימְתָּ לָ֥א סָגְדִֽין׃ס","ʼiyţa֞y gu̇bĕri֣yn yĕhẇdáʼyi֗n diֽ̇y-mani֤̇yţá yáţĕ⁠hwòn֙ ʻal-ʻàbiydaţ֙ mĕdiyna֣ţ bá̇be֔l şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò gu̇bĕrayá֣̇⁠ʼ ʼilé̇֗kĕ láʼ-şá̂֨mֽẇ ʻly⁠k malĕká̇⁠ʼ֙ tĕʻé֔m l⁠ʼlhy⁠k lá֣ʼ pálĕẖi֔yn ẇ⁠lĕ⁠ẕe֧lem dȧhàbá֛⁠ʼ di֥̇y hàqé֖ymĕţá̇ lá֥ʼ ságĕdiֽyn׃s"],[3,13,"בֵּ⁠אדַ֤יִן נְבוּכַדְנֶצַּר֙ בִּ⁠רְגַ֣ז וַ⁠חֲמָ֔ה אֲמַר֙ לְ⁠הַיְתָיָ֔ה לְ⁠שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ בֵּ⁠אדַ֨יִן֙ גֻּבְרַיָּ֣⁠א אִלֵּ֔ךְ הֵיתָ֖יוּ קֳדָ֥ם מַלְכָּֽ⁠א׃","bé̇⁠ʼda֤yin nĕbẇkadĕneẕȧr֙ bi̇⁠rĕga֣z wa⁠ẖàmá֔h ʼàmar֙ lĕ⁠hayĕţáyá֔h lĕ⁠şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò bé̇⁠ʼda֨yin֙ gu̇bĕrayá֣̇⁠ʼ ʼilé̇֔kĕ héyţá֖yẇ qodá֥m malĕkáֽ̇⁠ʼ׃"],[3,14,"עָנֵ֤ה נְבֻֽכַדְנֶצַּר֙ וְ⁠אָמַ֣ר לְ⁠ה֔וֹן הַ⁠צְדָּ֕א שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ לֵֽ⁠אלָהַ֗⁠י לָ֤א אִֽיתֵי⁠כוֹן֙ פָּֽלְחִ֔ין וּ⁠לְ⁠צֶ֧לֶם דַּהֲבָ֛⁠א דִּ֥י הֲקֵ֖ימֶת לָ֥א סָֽגְדִֽין׃","ʻáné֤h nĕbuֽkadĕneẕȧr֙ wĕ⁠ʼáma֣r lĕ⁠h֔wòn ha⁠ẕĕdá̇֕ʼ şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò léֽ⁠ʼláha֗⁠y lá֤ʼ ʼiֽyţéy⁠kwòn֙ páֽ̇lĕẖi֔yn ẇ⁠lĕ⁠ẕe֧lem dȧhàbá֛⁠ʼ di֥̇y hàqé֖ymeţ lá֥ʼ sáֽgĕdiֽyn׃"],[3,15,"כְּעַ֞ן הֵ֧ן אִֽיתֵי⁠כ֣וֹן עֲתִידִ֗ין דִּ֣י בְ⁠עִדָּנָ֡⁠א דִּֽי־תִשְׁמְע֡וּן קָ֣ל קַרְנָ֣⁠א מַשְׁרוֹקִיתָ֣⁠א קיתרס שַׂבְּכָ֡א פְּסַנְתֵּרִין֩ וְ⁠סוּמְפֹּ֨נְיָ֜ה וְ⁠כֹ֣ל ׀ זְנֵ֣י זְמָרָ֗⁠א תִּפְּל֣וּן וְ⁠תִסְגְּדוּן֮ לְ⁠צַלְמָ֣⁠א דִֽי־עַבְדֵת֒ וְ⁠הֵן֙ לָ֣א תִסְגְּד֔וּן בַּ⁠הּ־שַׁעֲתָ֣⁠ה תִתְרְמ֔וֹן לְ⁠גֽוֹא־אַתּ֥וּן נוּרָ֖⁠א יָקִֽדְתָּ֑⁠א וּ⁠מַן־ה֣וּא אֱלָ֔הּ דֵּ֥י יְשֵֽׁיזְבִנְ⁠כ֖וֹן מִן־יְדָֽ⁠י׃","kĕ̇ʻa֞n hé֧n ʼiֽyţéy⁠k֣wòn ʻàţiydi֗yn di֣̇y bĕ⁠ʻidá̇ná֡⁠ʼ diֽ̇y-ţişĕ̌mĕʻ֡ẇn qá֣l qarĕná֣⁠ʼ maşĕ̌rwòqiyţá֣⁠ʼ qyţrs şâbĕ̇ká֡ʼ pĕ̇sanĕţé̇riyn֩ wĕ⁠sẇmĕpò̇֨nĕyá֜h wĕ⁠kò֣l ׀ zĕné֣y zĕmárá֗⁠ʼ ţi̇pĕ̇l֣ẇn wĕ⁠ţisĕgĕ̇dẇn֮ lĕ⁠ẕalĕmá֣⁠ʼ diֽy-ʻabĕdéţ֒ wĕ⁠hén֙ lá֣ʼ ţisĕgĕ̇d֔ẇn bȧ⁠ḣ-şǎʻàţá֣⁠h ţiţĕrĕm֔wòn lĕ⁠gֽwòʼ-ʼaţ֥̇ẇn nẇrá֖⁠ʼ yáqiֽdĕţá֑̇⁠ʼ ẇ⁠man-h֣ẇʼ ʼèlá֔ḣ dé֥̇y yĕşéֽ̌yzĕbinĕ⁠k֖wòn min-yĕdáֽ⁠y׃"],[3,16,"עֲנ֗וֹ שַׁדְרַ֤ךְ מֵישַׁךְ֙ וַ⁠עֲבֵ֣ד נְג֔וֹ וְ⁠אָמְרִ֖ין לְ⁠מַלְכָּ֑⁠א נְבֽוּכַדְנֶצַּ֔ר לָֽא־חַשְׁחִ֨ין אֲנַ֧חְנָה עַל־דְּנָ֛ה פִּתְגָ֖ם לַ⁠הֲתָבוּתָֽ⁠ךְ׃","ʻàn֗wò şǎdĕra֤kĕ méyşǎkĕ֙ wa⁠ʻàbé֣d nĕg֔wò wĕ⁠ʼámĕri֖yn lĕ⁠malĕká֑̇⁠ʼ nĕbֽẇkadĕneẕȧ֔r láֽʼ-ẖaşĕ̌ẖi֨yn ʼàna֧ẖĕnáh ʻal-dĕ̇ná֛h pi̇ţĕgá֖m la⁠hàţábẇţáֽ⁠kĕ׃"],[3,17,"הֵ֣ן אִיתַ֗י אֱלָהַ֨⁠נָא֙ דִּֽי־אֲנַ֣חְנָא פָֽלְחִ֔ין יָכִ֖ל לְ⁠שֵׁיזָבוּתַ֑⁠נָא מִן־אַתּ֨וּן נוּרָ֧⁠א יָקִֽדְתָּ֛⁠א וּ⁠מִן־יְדָ֥⁠ךְ מַלְכָּ֖⁠א יְשֵׁיזִֽב׃","hé֣n ʼiyţa֗y ʼèláha֨⁠náʼ֙ diֽ̇y-ʼàna֣ẖĕnáʼ páֽlĕẖi֔yn yáki֖l lĕ⁠şé̌yzábẇţa֑⁠náʼ min-ʼaţ̇֨ẇn nẇrá֧⁠ʼ yáqiֽdĕţá֛̇⁠ʼ ẇ⁠min-yĕdá֥⁠kĕ malĕká֖̇⁠ʼ yĕşé̌yziֽb׃"],[3,18,"וְ⁠הֵ֣ן לָ֔א יְדִ֥יעַ לֶהֱוֵא־לָ֖⁠ךְ מַלְכָּ֑⁠א דִּ֤י ל⁠אלהי⁠ך לָא־איתי⁠נא פָֽלְחִ֔ין וּ⁠לְ⁠צֶ֧לֶם דַּהֲבָ֛⁠א דִּ֥י הֲקֵ֖ימְתָּ לָ֥א נִסְגֻּֽד׃ס","wĕ⁠hé֣n lá֔ʼ yĕdi֥yʻa lehèwéʼ-lá֖⁠kĕ malĕká֑̇⁠ʼ di֤̇y l⁠ʼlhy⁠k láʼ-ʼyţy⁠nʼ páֽlĕẖi֔yn ẇ⁠lĕ⁠ẕe֧lem dȧhàbá֛⁠ʼ di֥̇y hàqé֖ymĕţá̇ lá֥ʼ nisĕguֽ̇d׃s"],[3,19,"בֵּ⁠אדַ֨יִן נְבוּכַדְנֶצַּ֜ר הִתְמְלִ֣י חֱמָ֗א וּ⁠צְלֵ֤ם אַנְפּ֨וֹ⁠הִי֙ אשתנו עַל־שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ עָנֵ֤ה וְ⁠אָמַר֙ לְ⁠מֵזֵ֣א לְ⁠אַתּוּנָ֔⁠א חַ֨ד־שִׁבְעָ֔ה עַ֛ל דִּ֥י חֲזֵ֖ה לְ⁠מֵזְיֵֽ⁠הּ׃","bé̇⁠ʼda֨yin nĕbẇkadĕneẕȧ֜r hiţĕmĕli֣y ẖèmá֗ʼ ẇ⁠ẕĕlé֤m ʼanĕṗ֨wò⁠hiy֙ ʼşţnw ʻal-şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò ʻáné֤h wĕ⁠ʼámar֙ lĕ⁠mézé֣ʼ lĕ⁠ʼaţ̇ẇná֔⁠ʼ ẖa֨d-şǐbĕʻá֔h ʻa֛l di֥̇y ẖàzé֖h lĕ⁠mézĕyéֽ⁠ḣ׃"],[3,20,"וּ⁠לְ⁠גֻבְרִ֤ין גִּבָּֽרֵי־חַ֨יִל֙ דִּ֣י בְ⁠חַיְלֵ֔⁠הּ אֲמַר֙ לְ⁠כַפָּתָ֔ה לְ⁠שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ לְ⁠מִרְמֵ֕א לְ⁠אַתּ֥וּן נוּרָ֖⁠א יָקִֽדְתָּֽ⁠א׃","ẇ⁠lĕ⁠gubĕri֤yn gi̇báֽ̇réy-ẖa֨yil֙ di֣̇y bĕ⁠ẖayĕlé֔⁠ḣ ʼàmar֙ lĕ⁠kapá̇ţá֔h lĕ⁠şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò lĕ⁠mirĕmé֕ʼ lĕ⁠ʼaţ֥̇ẇn nẇrá֖⁠ʼ yáqiֽdĕţáֽ̇⁠ʼ׃"],[3,21,"בֵּ⁠אדַ֜יִן גֻּבְרַיָּ֣⁠א אִלֵּ֗ךְ כְּפִ֨תוּ֙ בְּ⁠סַרְבָּלֵי⁠הוֹן֙ פטישי⁠הון וְ⁠כַרְבְּלָתְ⁠ה֖וֹן וּ⁠לְבֻשֵׁי⁠ה֑וֹן וּ⁠רְמִ֕יו לְ⁠גֽוֹא־אַתּ֥וּן נוּרָ֖⁠א יָקִֽדְתָּֽ⁠א׃","bé̇⁠ʼda֜yin gu̇bĕrayá֣̇⁠ʼ ʼilé̇֗kĕ kĕ̇pi֨ţẇ֙ bĕ̇⁠sarĕbá̇léy⁠hwòn֙ ptyşy⁠hwn wĕ⁠karĕbĕ̇láţĕ⁠h֖wòn ẇ⁠lĕbuşé̌y⁠h֑wòn ẇ⁠rĕmi֕yw lĕ⁠gֽwòʼ-ʼaţ֥̇ẇn nẇrá֖⁠ʼ yáqiֽdĕţáֽ̇⁠ʼ׃"],[3,22,"כָּ⁠ל־קֳבֵ֣ל דְּנָ֗ה מִן־דִּ֞י מִלַּ֤ת מַלְכָּ⁠א֙ מַחְצְפָ֔ה וְ⁠אַתּוּנָ֖⁠א אֵזֵ֣ה יַתִּ֑ירָא גֻּבְרַיָּ֣⁠א אִלֵּ֗ךְ דִּ֤י הַסִּ֨קוּ֙ לְ⁠שַׁדְרַ֤ךְ מֵישַׁךְ֙ וַ⁠עֲבֵ֣ד נְג֔וֹ קַטִּ֣ל הִמּ֔וֹן שְׁבִיבָ֖⁠א דִּ֥י נוּרָֽ⁠א׃","ká̇⁠l-qobé֣l dĕ̇ná֗h min-di̇֞y milȧ֤ţ malĕká̇⁠ʼ֙ maẖĕẕĕpá֔h wĕ⁠ʼaţ̇ẇná֖⁠ʼ ʼézé֣h yaţi֑̇yráʼ gu̇bĕrayá֣̇⁠ʼ ʼilé̇֗kĕ di֤̇y hasi̇֨qẇ֙ lĕ⁠şǎdĕra֤kĕ méyşǎkĕ֙ wa⁠ʻàbé֣d nĕg֔wò qati֣̇l hiṁ֔wòn şĕ̌biybá֖⁠ʼ di֥̇y nẇráֽ⁠ʼ׃"],[3,23,"וְ⁠גֻבְרַיָּ֤⁠א אִלֵּךְ֙ תְּלָ֣תֵּ⁠ה֔וֹן שַׁדְרַ֥ךְ מֵישַׁ֖ךְ וַ⁠עֲבֵ֣ד נְג֑וֹ נְפַ֛לוּ לְ⁠גֽוֹא־אַתּוּן־נוּרָ֥⁠א יָֽקִדְתָּ֖⁠א מְכַפְּתִֽין׃פ","wĕ⁠gubĕrayá֤̇⁠ʼ ʼilé̇kĕ֙ ţĕ̇lá֣ţé̇⁠h֔wòn şǎdĕra֥kĕ méyşǎ֖kĕ wa⁠ʻàbé֣d nĕg֑wò nĕpa֛lẇ lĕ⁠gֽwòʼ-ʼaţ̇ẇn-nẇrá֥⁠ʼ yáֽqidĕţá֖̇⁠ʼ mĕkapĕ̇ţiֽyn׃p"],[3,24,"אֱדַ֨יִן֙ נְבוּכַדְנֶצַּ֣ר מַלְכָּ֔⁠א תְּוַ֖הּ וְ⁠קָ֣ם בְּ⁠הִתְבְּהָלָ֑ה עָנֵ֨ה וְ⁠אָמַ֜ר לְ⁠הַדָּֽבְר֗וֹ⁠הִי הֲ⁠לָא֩ גֻבְרִ֨ין תְּלָתָ֜א רְמֵ֤ינָא לְ⁠גוֹא־נוּרָ⁠א֙ מְכַפְּתִ֔ין עָנַ֤יִן וְ⁠אָמְרִין֙ לְ⁠מַלְכָּ֔⁠א יַצִּיבָ֖א מַלְכָּֽ⁠א׃","ʼèda֨yin֙ nĕbẇkadĕneẕȧ֣r malĕká̇֔⁠ʼ ţĕ̇wa֖ḣ wĕ⁠qá֣m bĕ̇⁠hiţĕbĕ̇hálá֑h ʻáné֨h wĕ⁠ʼáma֜r lĕ⁠hadáֽ̇bĕr֗wò⁠hiy hà⁠láʼ֩ gubĕri֨yn ţĕ̇láţá֜ʼ rĕmé֤ynáʼ lĕ⁠gwòʼ-nẇrá⁠ʼ֙ mĕkapĕ̇ţi֔yn ʻána֤yin wĕ⁠ʼámĕriyn֙ lĕ⁠malĕká̇֔⁠ʼ yaẕi̇ybá֖ʼ malĕkáֽ̇⁠ʼ׃"],[3,25,"עָנֵ֣ה וְ⁠אָמַ֗ר הָֽא־אֲנָ֨ה חָזֵ֜ה גֻּבְרִ֣ין אַרְבְּעָ֗ה שְׁרַ֨יִן֙ מַהְלְכִ֣ין בְּ⁠גֽוֹא־נוּרָ֔⁠א וַ⁠חֲבָ֖ל לָא־אִיתַ֣י בְּ⁠ה֑וֹן וְ⁠רֵוֵ⁠הּ֙ דִּ֣י רביעי⁠א דָּמֵ֖ה לְ⁠בַר־אֱלָהִֽין׃ס","ʻáné֣h wĕ⁠ʼáma֗r háֽʼ-ʼàná֨h ẖázé֜h gu̇bĕri֣yn ʼarĕbĕ̇ʻá֗h şĕ̌ra֨yin֙ mahĕlĕki֣yn bĕ̇⁠gֽwòʼ-nẇrá֔⁠ʼ wa⁠ẖàbá֖l láʼ-ʼiyţa֣y bĕ̇⁠h֑wòn wĕ⁠réwé⁠ḣ֙ di֣̇y rbyʻy⁠ʼ dá̇mé֖h lĕ⁠bar-ʼèláhiֽyn׃s"],[3,26,"בֵּ⁠אדַ֜יִן קְרֵ֣ב נְבוּכַדְנֶצַּ֗ר לִ⁠תְרַע֮ אַתּ֣וּן נוּרָ֣⁠א יָקִֽדְתָּ⁠א֒ עָנֵ֣ה וְ⁠אָמַ֗ר שַׁדְרַ֨ךְ מֵישַׁ֧ךְ וַ⁠עֲבֵד־נְג֛וֹ עַבְד֛וֹ⁠הִי דִּֽי־אֱלָהָ֥⁠א עלי⁠א פֻּ֣קוּ וֶ⁠אֱת֑וֹ בֵּ⁠אדַ֣יִן נָֽפְקִ֗ין שַׁדְרַ֥ךְ מֵישַׁ֛ךְ וַ⁠עֲבֵ֥ד נְג֖וֹ מִן־גּ֥וֹא נוּרָֽ⁠א׃","bé̇⁠ʼda֜yin qĕré֣b nĕbẇkadĕneẕȧ֗r li⁠ţĕraʻ֮ ʼaţ֣̇ẇn nẇrá֣⁠ʼ yáqiֽdĕţá̇⁠ʼ֒ ʻáné֣h wĕ⁠ʼáma֗r şǎdĕra֨kĕ méyşǎ֧kĕ wa⁠ʻàbéd-nĕg֛wò ʻabĕd֛wò⁠hiy diֽ̇y-ʼèláhá֥⁠ʼ ʻly⁠ʼ pu֣̇qẇ we⁠ʼèţ֑wò bé̇⁠ʼda֣yin náֽpĕqi֗yn şǎdĕra֥kĕ méyşǎ֛kĕ wa⁠ʻàbé֥d nĕg֖wò min-ġ֥wòʼ nẇráֽ⁠ʼ׃"],[3,27,"וּ֠⁠מִֽתְכַּנְּשִׁין אֲחַשְׁדַּרְפְּנַיָּ֞⁠א סִגְנַיָּ֣⁠א וּ⁠פַחֲוָתָ⁠א֮ וְ⁠הַדָּבְרֵ֣י מַלְכָּ⁠א֒ חָזַ֣יִן לְ⁠גֻבְרַיָּ֣⁠א אִלֵּ֡ךְ דִּי֩ לָֽא־שְׁלֵ֨ט נוּרָ֜⁠א בְּ⁠גֶשְׁמְ⁠ה֗וֹן וּ⁠שְׂעַ֤ר רֵֽאשְׁ⁠הוֹן֙ לָ֣א הִתְחָרַ֔ךְ וְ⁠סָרְבָּלֵי⁠ה֖וֹן לָ֣א שְׁנ֑וֹ וְ⁠רֵ֣יחַ נ֔וּר לָ֥א עֲדָ֖ת בְּ⁠הֽוֹן׃","ẇ֠⁠miֽţĕkȧnĕ̇şǐyn ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇֞⁠ʼ sigĕnayá֣̇⁠ʼ ẇ⁠paẖàwáţá⁠ʼ֮ wĕ⁠hadá̇bĕré֣y malĕká̇⁠ʼ֒ ẖáza֣yin lĕ⁠gubĕrayá֣̇⁠ʼ ʼilé̇֡kĕ di̇y֩ láֽʼ-şĕ̌lé֨t nẇrá֜⁠ʼ bĕ̇⁠geşĕ̌mĕ⁠h֗wòn ẇ⁠şĕ̂ʻa֤r réֽʼşĕ̌⁠hwòn֙ lá֣ʼ hiţĕẖára֔kĕ wĕ⁠sárĕbá̇léy⁠h֖wòn lá֣ʼ şĕ̌n֑wò wĕ⁠ré֣yẖa n֔ẇr lá֥ʼ ʻàdá֖ţ bĕ̇⁠hֽwòn׃"],[3,28,"עָנֵ֨ה נְבֽוּכַדְנֶצַּ֜ר וְ⁠אָמַ֗ר בְּרִ֤יךְ אֱלָהֲ⁠הוֹן֙ דִּֽי־שַׁדְרַ֤ךְ מֵישַׁךְ֙ וַ⁠עֲבֵ֣ד נְג֔וֹ דִּֽי־שְׁלַ֤ח מַלְאֲכֵ⁠הּ֙ וְ⁠שֵׁיזִ֣ב לְ⁠עַבְד֔וֹ⁠הִי דִּ֥י הִתְרְחִ֖צוּ עֲל֑וֹ⁠הִי וּ⁠מִלַּ֤ת מַלְכָּ⁠א֙ שַׁנִּ֔יו וִ⁠יהַ֣בוּ גשמי⁠הון דִּ֠י לָֽא־יִפְלְח֤וּן וְ⁠לָֽא־יִסְגְּדוּן֙ לְ⁠כָל־אֱלָ֔הּ לָהֵ֖ן לֵ⁠אלָֽהֲ⁠הֽוֹן׃","ʻáné֨h nĕbֽẇkadĕneẕȧ֜r wĕ⁠ʼáma֗r bĕ̇ri֤ykĕ ʼèláhà⁠hwòn֙ diֽ̇y-şǎdĕra֤kĕ méyşǎkĕ֙ wa⁠ʻàbé֣d nĕg֔wò diֽ̇y-şĕ̌la֤ẖ malĕʼàké⁠ḣ֙ wĕ⁠şé̌yzi֣b lĕ⁠ʻabĕd֔wò⁠hiy di֥̇y hiţĕrĕẖi֖ẕẇ ʻàl֑wò⁠hiy ẇ⁠milȧ֤ţ malĕká̇⁠ʼ֙ şǎni̇֔yw wi⁠yha֣bẇ gşmy⁠hwn di̇֠y láֽʼ-yipĕlĕẖ֤ẇn wĕ⁠láֽʼ-yisĕgĕ̇dẇn֙ lĕ⁠kál-ʼèlá֔ḣ láhé֖n lé⁠ʼláֽhà⁠hֽwòn׃"],[3,29,"וּ⁠מִ⁠נִּי֮ שִׂ֣ים טְעֵם֒ דִּי֩ כָל־עַ֨ם אֻמָּ֜ה וְ⁠לִשָּׁ֗ן דִּֽי־יֵאמַ֤ר שלה עַ֣ל אֱלָהֲ⁠ה֗וֹן דִּֽי־שַׁדְרַ֤ךְ מֵישַׁךְ֙ וַ⁠עֲבֵ֣ד נְג֔וֹא הַדָּמִ֣ין יִתְעֲבֵ֔ד וּ⁠בַיְתֵ֖⁠הּ נְוָלִ֣י יִשְׁתַּוֵּ֑ה כָּ⁠ל־קֳבֵ֗ל דִּ֣י לָ֤א אִיתַי֙ אֱלָ֣ה אָחֳרָ֔ן דִּֽי־יִכֻּ֥ל לְ⁠הַצָּלָ֖ה כִּ⁠דְנָֽה׃","ẇ⁠mi⁠ni̇y֮ şî֣ym tĕʻém֒ di̇y֩ kál-ʻa֨m ʼumá̇֜h wĕ⁠lişá̇̌֗n diֽ̇y-yéʼma֤r şlh ʻa֣l ʼèláhà⁠h֗wòn diֽ̇y-şǎdĕra֤kĕ méyşǎkĕ֙ wa⁠ʻàbé֣d nĕg֔wòʼ hadá̇mi֣yn yiţĕʻàbé֔d ẇ⁠bayĕţé֖⁠ḣ nĕwáli֣y yişĕ̌ţȧwé֑̇h ká̇⁠l-qobé֗l di֣̇y lá֤ʼ ʼiyţay֙ ʼèlá֣h ʼáẖorá֔n diֽ̇y-yiku֥̇l lĕ⁠haẕá̇lá֖h ki̇⁠dĕnáֽh׃"],[3,30,"בֵּ⁠אדַ֣יִן מַלְכָּ֗⁠א הַצְלַ֛ח לְ⁠שַׁדְרַ֥ךְ מֵישַׁ֛ךְ וַ⁠עֲבֵ֥ד נְג֖וֹ בִּ⁠מְדִינַ֥ת בָּבֶֽל׃פ","bé̇⁠ʼda֣yin malĕká̇֗⁠ʼ haẕĕla֛ẖ lĕ⁠şǎdĕra֥kĕ méyşǎ֛kĕ wa⁠ʻàbé֥d nĕg֖wò bi̇⁠mĕdiyna֥ţ bá̇beֽl׃p"],[4,1,"נְבוּכַדְנֶצַּ֣ר מַלְכָּ֗⁠א לְֽ⁠כָל־עַֽמְמַיָּ֞⁠א אֻמַיָּ֧⁠א וְ⁠לִשָּׁנַיָּ֛⁠א דִּֽי־דארין בְּ⁠כָל־אַרְעָ֖⁠א שְׁלָמְ⁠כ֥וֹן יִשְׂגֵּֽא׃","nĕbẇkadĕneẕȧ֣r malĕká̇֗⁠ʼ lĕֽ⁠kál-ʻaֽmĕmayá̇֞⁠ʼ ʼumayá֧̇⁠ʼ wĕ⁠lişá̇̌nayá֛̇⁠ʼ diֽ̇y-dʼryn bĕ̇⁠kál-ʼarĕʻá֖⁠ʼ şĕ̌lámĕ⁠k֥wòn yişĕ̂géֽ̇ʼ׃"],[4,2,"אָֽתַיָּ⁠א֙ וְ⁠תִמְהַיָּ֔⁠א דִּ֚י עֲבַ֣ד עִמִּ֔⁠י אֱלָהָ֖⁠א עלי⁠א שְׁפַ֥ר קָֽדָמַ֖⁠י לְ⁠הַחֲוָיָֽה׃","ʼáֽţayá̇⁠ʼ֙ wĕ⁠ţimĕhayá̇֔⁠ʼ di֚̇y ʻàba֣d ʻimi̇֔⁠y ʼèláhá֖⁠ʼ ʻly⁠ʼ şĕ̌pa֥r qֽádáma֖⁠y lĕ⁠haẖàwáyáֽh׃"],[4,3,"אָת֨וֹ⁠הִי֙ כְּ⁠מָ֣ה רַבְרְבִ֔ין וְ⁠תִמְה֖וֹ⁠הִי כְּ⁠מָ֣ה תַקִּיפִ֑ין מַלְכוּתֵ⁠הּ֙ מַלְכ֣וּת עָלַ֔ם וְ⁠שָׁלְטָנֵ֖⁠הּ עִם־דָּ֥ר וְ⁠דָֽר׃","ʼáţ֨wò⁠hiy֙ kĕ̇⁠má֣h rabĕrĕbi֔yn wĕ⁠ţimĕh֖wò⁠hiy kĕ̇⁠má֣h ţaqi̇ypi֑yn malĕkẇţé⁠ḣ֙ malĕk֣ẇţ ʻála֔m wĕ⁠şá̌lĕtáné֖⁠ḣ ʻim-dá֥̇r wĕ⁠dáֽr׃"],[4,4,"אֲנָ֣ה נְבוּכַדְנֶצַּ֗ר שְׁלֵ֤ה הֲוֵית֙ בְּ⁠בֵיתִ֔⁠י וְ⁠רַעְנַ֖ן בְּ⁠הֵיכְלִֽ⁠י׃","ʼàná֣h nĕbẇkadĕneẕȧ֗r şĕ̌lé֤h hàwéyţ֙ bĕ̇⁠béyţi֔⁠y wĕ⁠raʻĕna֖n bĕ̇⁠héykĕliֽ⁠y׃"],[4,5,"חֵ֥לֶם חֲזֵ֖ית וִֽ⁠ידַחֲלִנַּ֑⁠נִי וְ⁠הַרְהֹרִין֙ עַֽל־מִשְׁכְּבִ֔⁠י וְ⁠חֶזְוֵ֥י רֵאשִׁ֖⁠י יְבַהֲלֻנַּֽ⁠נִי׃","ẖé֥lem ẖàzé֖yţ wiֽ⁠ydaẖàlinȧ֑⁠niy wĕ⁠harĕhòriyn֙ ʻaֽl-mişĕ̌kĕ̇bi֔⁠y wĕ⁠ẖezĕwé֥y réʼşǐ֖⁠y yĕbahàlunȧֽ⁠niy׃"],[4,6,"וּ⁠מִנִּ⁠י֙ שִׂ֣ים טְעֵ֔ם לְ⁠הַנְעָלָ֣ה קָֽדָמַ֔⁠י לְ⁠כֹ֖ל חַכִּימֵ֣י בָבֶ֑ל דִּֽי־פְשַׁ֥ר חֶלְמָ֖⁠א יְהֽוֹדְעֻנַּֽ⁠נִי׃","ẇ⁠mini̇⁠y֙ şî֣ym tĕʻé֔m lĕ⁠hanĕʻálá֣h qáֽdáma֔⁠y lĕ⁠kò֖l ẖaki̇ymé֣y bábe֑l diֽ̇y-pĕşǎ֥r ẖelĕmá֖⁠ʼ yĕhֽwòdĕʻunȧֽ⁠niy׃"],[4,7,"בֵּ⁠אדַ֣יִן עללין חַרְטֻמַיָּ⁠א֙ אָֽשְׁפַיָּ֔⁠א כשדי⁠א וְ⁠גָזְרַיָּ֑⁠א וְ⁠חֶלְמָ֗⁠א אָמַ֤ר אֲנָה֙ קֳדָ֣מֵי⁠ה֔וֹן וּ⁠פִשְׁרֵ֖⁠הּ לָא־מְהוֹדְעִ֥ין לִֽ⁠י׃","bé̇⁠ʼda֣yin ʻllyn ẖarĕtumayá̇⁠ʼ֙ ʼáֽşĕ̌payá̇֔⁠ʼ kşdy⁠ʼ wĕ⁠gázĕrayá֑̇⁠ʼ wĕ⁠ẖelĕmá֗⁠ʼ ʼáma֤r ʼànáh֙ qodá֣méy⁠h֔wòn ẇ⁠pişĕ̌ré֖⁠ḣ láʼ-mĕhwòdĕʻi֥yn liֽ⁠y׃"],[4,8,"וְ⁠עַ֣ד אָחֳרֵ֡ין עַל֩ קָֽדָמַ֨⁠י דָּנִיֵּ֜אל דִּֽי־שְׁמֵ֤⁠הּ בֵּלְטְשַׁאצַּר֙ כְּ⁠שֻׁ֣ם אֱלָהִ֔⁠י וְ⁠דִ֛י רֽוּחַ־אֱלָהִ֥ין קַדִּישִׁ֖ין בֵּ֑⁠הּ וְ⁠חֶלְמָ֖⁠א קָֽדָמ֥וֹ⁠הִי אַמְרֵֽת׃","wĕ⁠ʻa֣d ʼáẖoré֡yn ʻal֩ qáֽdáma֨⁠y dá̇niyé̇֜ʼl diֽ̇y-şĕ̌mé֤⁠ḣ bé̇lĕtĕşǎʼẕȧr֙ kĕ̇⁠şǔ֣m ʼèláhi֔⁠y wĕ⁠di֛y rֽẇẖa-ʼèláhi֥yn qadi̇yşǐ֖yn bé֑̇⁠ḣ wĕ⁠ẖelĕmá֖⁠ʼ qáֽdám֥wò⁠hiy ʼamĕréֽţ׃"],[4,9,"בֵּלְטְשַׁאצַּר֮ רַ֣ב חַרְטֻמַיָּ⁠א֒ דִּ֣י ׀ אֲנָ֣ה יִדְעֵ֗ת דִּ֠י ר֣וּחַ אֱלָהִ֤ין קַדִּישִׁין֙ בָּ֔⁠ךְ וְ⁠כָל־רָ֖ז לָא־אָנֵ֣ס לָ֑⁠ךְ חֶזְוֵ֨י חֶלְמִ֧⁠י דִֽי־חֲזֵ֛ית וּ⁠פִשְׁרֵ֖⁠הּ אֱמַֽר׃","bé̇lĕtĕşǎʼẕȧr֮ ra֣b ẖarĕtumayá̇⁠ʼ֒ di֣̇y ׀ ʼàná֣h yidĕʻé֗ţ di̇֠y r֣ẇẖa ʼèláhi֤yn qadi̇yşǐyn֙ bá̇֔⁠kĕ wĕ⁠kál-rá֖z láʼ-ʼáné֣s lá֑⁠kĕ ẖezĕwé֨y ẖelĕmi֧⁠y diֽy-ẖàzé֛yţ ẇ⁠pişĕ̌ré֖⁠ḣ ʼèmaֽr׃"],[4,10,"וְ⁠חֶזְוֵ֥י רֵאשִׁ֖⁠י עַֽל־מִשְׁכְּבִ֑⁠י חָזֵ֣ה הֲוֵ֔ית וַ⁠אֲל֥וּ אִילָ֛ן בְּ⁠ג֥וֹא אַרְעָ֖⁠א וְ⁠רוּמֵ֥⁠הּ שַׂגִּֽיא׃","wĕ⁠ẖezĕwé֥y réʼşǐ֖⁠y ʻaֽl-mişĕ̌kĕ̇bi֑⁠y ẖázé֣h hàwé֔yţ wa⁠ʼàl֥ẇ ʼiylá֛n bĕ̇⁠g֥wòʼ ʼarĕʻá֖⁠ʼ wĕ⁠rẇmé֥⁠ḣ şâgiֽ̇yʼ׃"],[4,11,"רְבָ֥ה אִֽילָנָ֖⁠א וּ⁠תְקִ֑ף וְ⁠רוּמֵ⁠הּ֙ יִמְטֵ֣א לִ⁠שְׁמַיָּ֔⁠א וַ⁠חֲזוֹתֵ֖⁠הּ לְ⁠ס֥וֹף כָּל־אַרְעָֽ⁠א׃","rĕbá֥h ʼiֽyláná֖⁠ʼ ẇ⁠ţĕqi֑p wĕ⁠rẇmé⁠ḣ֙ yimĕté֣ʼ li⁠şĕ̌mayá̇֔⁠ʼ wa⁠ẖàzwòţé֖⁠ḣ lĕ⁠s֥wòp ká̇l-ʼarĕʻáֽ⁠ʼ׃"],[4,12,"עָפְיֵ֤⁠הּ שַׁפִּיר֙ וְ⁠אִנְבֵּ֣⁠הּ שַׂגִּ֔יא וּ⁠מָז֨וֹן לְ⁠כֹ֖לָּ⁠א־בֵ֑⁠הּ תְּחֹת֜וֹ⁠הִי תַּטְלֵ֣ל ׀ חֵיוַ֣ת בָּרָ֗⁠א וּ⁠בְ⁠עַנְפ֨וֹ⁠הִי֙ ידרון צִפֲּרֵ֣י שְׁמַיָּ֔⁠א וּ⁠מִנֵּ֖⁠הּ יִתְּזִ֥ין כָּל־בִּשְׂרָֽ⁠א׃","ʻápĕyé֤⁠ḣ şǎpi̇yr֙ wĕ⁠ʼinĕbé֣̇⁠ḣ şâgi̇֔yʼ ẇ⁠máz֨wòn lĕ⁠kò֖lá̇⁠ʼ-bé֑⁠ḣ ţĕ̇ẖòţ֜wò⁠hiy ţȧtĕlé֣l ׀ ẖéywa֣ţ bá̇rá֗⁠ʼ ẇ⁠bĕ⁠ʻanĕp֨wò⁠hiy֙ ydrwn ẕipà̇ré֣y şĕ̌mayá̇֔⁠ʼ ẇ⁠miné֖̇⁠ḣ yiţĕ̇zi֥yn ká̇l-bi̇şĕ̂ráֽ⁠ʼ׃"],[4,13,"חָזֵ֥ה הֲוֵ֛ית בְּ⁠חֶזְוֵ֥י רֵאשִׁ֖⁠י עַֽל־מִשְׁכְּבִ֑⁠י וַ⁠אֲלוּ֙ עִ֣יר וְ⁠קַדִּ֔ישׁ מִן־שְׁמַיָּ֖⁠א נָחִֽת׃","ẖázé֥h hàwé֛yţ bĕ̇⁠ẖezĕwé֥y réʼşǐ֖⁠y ʻaֽl-mişĕ̌kĕ̇bi֑⁠y wa⁠ʼàlẇ֙ ʻi֣yr wĕ⁠qadi̇֔yş̌ min-şĕ̌mayá֖̇⁠ʼ náẖiֽţ׃"],[4,14,"קָרֵ֨א בְ⁠חַ֜יִל וְ⁠כֵ֣ן אָמַ֗ר גֹּ֤דּוּ אִֽילָנָ⁠א֙ וְ⁠קַצִּ֣צוּ עַנְפ֔וֹ⁠הִי אַתַּ֥רוּ עָפְיֵ֖⁠הּ וּ⁠בַדַּ֣רוּ אִנְבֵּ֑⁠הּ תְּנֻ֤ד חֵֽיוְתָ⁠א֙ מִן־תַּחְתּ֔וֹ⁠הִי וְ⁠צִפְּרַיָּ֖⁠א מִן־עַנְפֽוֹ⁠הִי׃","qáré֨ʼ bĕ⁠ẖa֜yil wĕ⁠ké֣n ʼáma֗r gò֤̇ḋẇ ʼiֽyláná⁠ʼ֙ wĕ⁠qaẕi֣̇ẕẇ ʻanĕp֔wò⁠hiy ʼaţȧ֥rẇ ʻápĕyé֖⁠ḣ ẇ⁠badȧ֣rẇ ʼinĕbé֑̇⁠ḣ ţĕ̇nu֤d ẖéֽywĕţá⁠ʼ֙ min-ţȧẖĕţ̇֔wò⁠hiy wĕ⁠ẕipĕ̇rayá֖̇⁠ʼ min-ʻanĕpֽwò⁠hiy׃"],[4,15,"בְּרַ֨ם עִקַּ֤ר שָׁרְשׁ֨וֹ⁠הִי֙ בְּ⁠אַרְעָ֣⁠א שְׁבֻ֔קוּ וּ⁠בֶֽ⁠אֱסוּר֙ דִּֽי־פַרְזֶ֣ל וּ⁠נְחָ֔שׁ בְּ⁠דִתְאָ֖⁠א דִּ֣י בָרָ֑⁠א וּ⁠בְ⁠טַ֤ל שְׁמַיָּ⁠א֙ יִצְטַבַּ֔ע וְ⁠עִם־חֵיוְתָ֥⁠א חֲלָקֵ֖⁠הּ בַּ⁠עֲשַׂ֥ב אַרְעָֽ⁠א׃","bĕ̇ra֨m ʻiqȧ֤r şá̌rĕş̌֨wò⁠hiy֙ bĕ̇⁠ʼarĕʻá֣⁠ʼ şĕ̌bu֔qẇ ẇ⁠beֽ⁠ʼèsẇr֙ diֽ̇y-parĕze֣l ẇ⁠nĕẖá֔ş̌ bĕ̇⁠diţĕʼá֖⁠ʼ di֣̇y bárá֑⁠ʼ ẇ⁠bĕ⁠ta֤l şĕ̌mayá̇⁠ʼ֙ yiẕĕtabȧ֔ʻ wĕ⁠ʻim-ẖéywĕţá֥⁠ʼ ẖàláqé֖⁠ḣ bȧ⁠ʻàşâ֥b ʼarĕʻáֽ⁠ʼ׃"],[4,16,"לִבְבֵ⁠הּ֙ מִן־אנוש⁠א יְשַׁנּ֔וֹן וּ⁠לְבַ֥ב חֵיוָ֖ה יִתְיְהִ֣ב לֵ֑⁠הּ וְ⁠שִׁבְעָ֥ה עִדָּנִ֖ין יַחְלְפ֥וּן עֲלֽוֹ⁠הִי׃","libĕbé⁠ḣ֙ min-ʼnwş⁠ʼ yĕşǎṅ֔wòn ẇ⁠lĕba֥b ẖéywá֖h yiţĕyĕhi֣b lé֑⁠ḣ wĕ⁠şǐbĕʻá֥h ʻidá̇ni֖yn yaẖĕlĕp֥ẇn ʻàlֽwò⁠hiy׃"],[4,17,"בִּ⁠גְזֵרַ֤ת עִירִין֙ פִּתְגָמָ֔⁠א וּ⁠מֵאמַ֥ר קַדִּישִׁ֖ין שְׁאֵֽלְתָ֑⁠א עַד־דִּבְרַ֡ת דִּ֣י יִנְדְּע֣וּן חַ֠יַּיָּ⁠א דִּֽי־שַׁלִּ֨יט עלי⁠א בְּ⁠מַלְכ֣וּת אנוש⁠א וּ⁠לְ⁠מַן־דִּ֤י יִצְבֵּא֙ יִתְּנִנַּ֔⁠הּ וּ⁠שְׁפַ֥ל אֲנָשִׁ֖ים יְקִ֥ים עלי⁠ה׃","bi̇⁠gĕzéra֤ţ ʻiyriyn֙ pi̇ţĕgámá֔⁠ʼ ẇ⁠méʼma֥r qadi̇yşǐ֖yn şĕ̌ʼéֽlĕţá֑⁠ʼ ʻad-di̇bĕra֡ţ di֣̇y yinĕdĕ̇ʻ֣ẇn ẖa֠yȧyá̇⁠ʼ diֽ̇y-şǎli̇֨yt ʻly⁠ʼ bĕ̇⁠malĕk֣ẇţ ʼnwş⁠ʼ ẇ⁠lĕ⁠man-di֤̇y yiẕĕbé̇ʼ֙ yiţĕ̇ninȧ֔⁠ḣ ẇ⁠şĕ̌pa֥l ʼànáşǐ֖ym yĕqi֥ym ʻly⁠h׃"],[4,18,"דְּנָה֙ חֶלְמָ֣⁠א חֲזֵ֔ית אֲנָ֖ה מַלְכָּ֣⁠א נְבוּכַדְנֶצַּ֑ר ו⁠אנתה בֵּלְטְשַׁאצַּ֜ר פִּשְׁרֵ֣⁠א ׀ אֱמַ֗ר כָּ⁠ל־קֳבֵל֙ דִּ֣י ׀ כָּל־חַכִּימֵ֣י מַלְכוּתִ֗⁠י לָֽא־יָכְלִ֤ין פִּשְׁרָ⁠א֙ לְ⁠הוֹדָ֣עֻתַ֔⁠נִי ו⁠אנתה כָּהֵ֔ל דִּ֛י רֽוּחַ־אֱלָהִ֥ין קַדִּישִׁ֖ין בָּֽ⁠ךְ׃","dĕ̇náh֙ ẖelĕmá֣⁠ʼ ẖàzé֔yţ ʼàná֖h malĕká֣̇⁠ʼ nĕbẇkadĕneẕȧ֑r w⁠ʼnţh bé̇lĕtĕşǎʼẕȧ֜r pi̇şĕ̌ré֣⁠ʼ ׀ ʼèma֗r ká̇⁠l-qobél֙ di֣̇y ׀ ká̇l-ẖaki̇ymé֣y malĕkẇţi֗⁠y láֽʼ-yákĕli֤yn pi̇şĕ̌rá⁠ʼ֙ lĕ⁠hwòdá֣ʻuţa֔⁠niy w⁠ʼnţh ká̇hé֔l di֛̇y rֽẇẖa-ʼèláhi֥yn qadi̇yşǐ֖yn báֽ̇⁠kĕ׃"],[4,19,"אֱדַ֨יִן דָּֽנִיֵּ֜אל דִּֽי־שְׁמֵ֣⁠הּ בֵּלְטְשַׁאצַּ֗ר אֶשְׁתּוֹמַם֙ כְּ⁠שָׁעָ֣ה חֲדָ֔ה וְ⁠רַעְיֹנֹ֖⁠הִי יְבַהֲלֻנֵּ֑⁠הּ עָנֵ֨ה מַלְכָּ֜⁠א וְ⁠אָמַ֗ר בֵּלְטְשַׁאצַּר֙ חֶלְמָ֤⁠א וּ⁠פִשְׁרֵ⁠א֙ אַֽל־יְבַהֲלָ֔⁠ךְ עָנֵ֤ה בֵלְטְשַׁאצַּר֙ וְ⁠אָמַ֔ר מרא⁠י חֶלְמָ֥⁠א ל⁠שנאי⁠ך וּ⁠פִשְׁרֵ֥⁠הּ ל⁠ערי⁠ך׃","ʼèda֨yin dáֽ̇niyé̇֜ʼl diֽ̇y-şĕ̌mé֣⁠ḣ bé̇lĕtĕşǎʼẕȧ֗r ʼeşĕ̌ţ̇wòmam֙ kĕ̇⁠şá̌ʻá֣h ẖàdá֔h wĕ⁠raʻĕyònò֖⁠hiy yĕbahàluné֑̇⁠ḣ ʻáné֨h malĕká̇֜⁠ʼ wĕ⁠ʼáma֗r bé̇lĕtĕşǎʼẕȧr֙ ẖelĕmá֤⁠ʼ ẇ⁠pişĕ̌ré⁠ʼ֙ ʼaֽl-yĕbahàlá֔⁠kĕ ʻáné֤h bélĕtĕşǎʼẕȧr֙ wĕ⁠ʼáma֔r mrʼ⁠y ẖelĕmá֥⁠ʼ l⁠şnʼy⁠k ẇ⁠pişĕ̌ré֥⁠ḣ l⁠ʻry⁠k׃"],[4,20,"אִֽילָנָ⁠א֙ דִּ֣י חֲזַ֔יְתָ דִּ֥י רְבָ֖ה וּ⁠תְקִ֑ף וְ⁠רוּמֵ⁠הּ֙ יִמְטֵ֣א לִ⁠שְׁמַיָּ֔⁠א וַ⁠חֲזוֹתֵ֖⁠הּ לְ⁠כָל־אַרְעָֽ⁠א׃","ʼiֽyláná⁠ʼ֙ di֣̇y ẖàza֔yĕţá di֥̇y rĕbá֖h ẇ⁠ţĕqi֑p wĕ⁠rẇmé⁠ḣ֙ yimĕté֣ʼ li⁠şĕ̌mayá̇֔⁠ʼ wa⁠ẖàzwòţé֖⁠ḣ lĕ⁠kál-ʼarĕʻáֽ⁠ʼ׃"],[4,21,"וְ⁠עָפְיֵ֤⁠הּ שַׁפִּיר֙ וְ⁠אִנְבֵּ֣⁠הּ שַׂגִּ֔יא וּ⁠מָז֨וֹן לְ⁠כֹ֖לָּ⁠א־בֵ֑⁠הּ תְּחֹת֗וֹ⁠הִי תְּדוּר֙ חֵיוַ֣ת בָּרָ֔⁠א וּ⁠בְ⁠עַנְפ֕וֹ⁠הִי יִשְׁכְּנָ֖ן צִפֲּרֵ֥י שְׁמַיָּֽ⁠א׃","wĕ⁠ʻápĕyé֤⁠ḣ şǎpi̇yr֙ wĕ⁠ʼinĕbé֣̇⁠ḣ şâgi̇֔yʼ ẇ⁠máz֨wòn lĕ⁠kò֖lá̇⁠ʼ-bé֑⁠ḣ ţĕ̇ẖòţ֗wò⁠hiy ţĕ̇dẇr֙ ẖéywa֣ţ bá̇rá֔⁠ʼ ẇ⁠bĕ⁠ʻanĕp֕wò⁠hiy yişĕ̌kĕ̇ná֖n ẕipà̇ré֥y şĕ̌mayáֽ̇⁠ʼ׃"],[4,22,"אנתה־ה֣וּא מַלְכָּ֔⁠א דִּ֥י רְבַ֖ית וּ⁠תְקֵ֑פְתְּ וּ⁠רְבוּתָ֤⁠ךְ רְבָת֙ וּ⁠מְטָ֣ת לִ⁠שְׁמַיָּ֔⁠א וְ⁠שָׁלְטָנָ֖⁠ךְ לְ⁠ס֥וֹף אַרְעָֽ⁠א׃","ʼnţh-h֣ẇʼ malĕká̇֔⁠ʼ di֥̇y rĕba֖yţ ẇ⁠ţĕqé֑pĕţĕ̇ ẇ⁠rĕbẇţá֤⁠kĕ rĕbáţ֙ ẇ⁠mĕtá֣ţ li⁠şĕ̌mayá̇֔⁠ʼ wĕ⁠şá̌lĕtáná֖⁠kĕ lĕ⁠s֥wòp ʼarĕʻáֽ⁠ʼ׃"],[4,23,"וְ⁠דִ֣י חֲזָ֣ה מַלְכָּ֡⁠א עִ֣יר וְ⁠קַדִּ֣ישׁ נָחִ֣ת ׀ מִן־שְׁמַיָּ֡⁠א וְ⁠אָמַר֩ גֹּ֨דּוּ אִֽילָנָ֜⁠א וְ⁠חַבְּל֗וּ⁠הִי בְּרַ֨ם עִקַּ֤ר שָׁרְשׁ֨וֹ⁠הִי֙ בְּ⁠אַרְעָ֣⁠א שְׁבֻ֔קוּ וּ⁠בֶ⁠אֱסוּר֙ דִּֽי־פַרְזֶ֣ל וּ⁠נְחָ֔שׁ בְּ⁠דִתְאָ֖⁠א דִּ֣י בָרָ֑⁠א וּ⁠בְ⁠טַ֧ל שְׁמַיָּ֣⁠א יִצְטַבַּ֗ע וְ⁠עִם־חֵיוַ֤ת בָּרָ⁠א֙ חֲלָקֵ֔⁠הּ עַ֛ד דִּֽי־שִׁבְעָ֥ה עִדָּנִ֖ין יַחְלְפ֥וּן עֲלֽוֹ⁠הִי׃","wĕ⁠di֣y ẖàzá֣h malĕká̇֡⁠ʼ ʻi֣yr wĕ⁠qadi֣̇yş̌ náẖi֣ţ ׀ min-şĕ̌mayá̇֡⁠ʼ wĕ⁠ʼámar֩ gò̇֨ḋẇ ʼiֽyláná֜⁠ʼ wĕ⁠ẖabĕ̇l֗ẇ⁠hiy bĕ̇ra֨m ʻiqȧ֤r şá̌rĕş̌֨wò⁠hiy֙ bĕ̇⁠ʼarĕʻá֣⁠ʼ şĕ̌bu֔qẇ ẇ⁠be⁠ʼèsẇr֙ diֽ̇y-parĕze֣l ẇ⁠nĕẖá֔ş̌ bĕ̇⁠diţĕʼá֖⁠ʼ di֣̇y bárá֑⁠ʼ ẇ⁠bĕ⁠ta֧l şĕ̌mayá֣̇⁠ʼ yiẕĕtabȧ֗ʻ wĕ⁠ʻim-ẖéywa֤ţ bá̇rá⁠ʼ֙ ẖàláqé֔⁠ḣ ʻa֛d diֽ̇y-şǐbĕʻá֥h ʻidá̇ni֖yn yaẖĕlĕp֥ẇn ʻàlֽwò⁠hiy׃"],[4,24,"דְּנָ֥ה פִשְׁרָ֖⁠א מַלְכָּ֑⁠א וּ⁠גְזֵרַ֤ת עלי⁠א הִ֔יא דִּ֥י מְטָ֖ת עַל־מרא⁠י מַלְכָּֽ⁠א׃","dĕ̇ná֥h pişĕ̌rá֖⁠ʼ malĕká֑̇⁠ʼ ẇ⁠gĕzéra֤ţ ʻly⁠ʼ hi֔yʼ di֥̇y mĕtá֖ţ ʻal-mrʼ⁠y malĕkáֽ̇⁠ʼ׃"],[4,25,"וְ⁠לָ֣⁠ךְ טָֽרְדִ֣ין מִן־אֲנָשָׁ֡⁠א וְ⁠עִם־חֵיוַ֣ת בָּרָ⁠א֩ לֶהֱוֵ֨ה מְדֹרָ֜⁠ךְ וְ⁠עִשְׂבָּ֥⁠א כְ⁠תוֹרִ֣ין ׀ לָ֣⁠ךְ יְטַֽעֲמ֗וּן וּ⁠מִ⁠טַּ֤ל שְׁמַיָּ⁠א֙ לָ֣⁠ךְ מְצַבְּעִ֔ין וְ⁠שִׁבְעָ֥ה עִדָּנִ֖ין יַחְלְפ֣וּן עֲלָ֑⁠יךְ עַ֣ד דִּֽי־תִנְדַּ֗ע דִּֽי־שַׁלִּ֤יט עִלָּיָ⁠א֙ בְּ⁠מַלְכ֣וּת אֲנָשָׁ֔⁠א וּ⁠לְ⁠מַן־דִּ֥י יִצְבֵּ֖א יִתְּנִנַּֽ⁠הּ׃","wĕ⁠lá֣⁠kĕ táֽrĕdi֣yn min-ʼànáşá̌֡⁠ʼ wĕ⁠ʻim-ẖéywa֣ţ bá̇rá⁠ʼ֩ lehèwé֨h mĕdòrá֜⁠kĕ wĕ⁠ʻişĕ̂bá֥̇⁠ʼ kĕ⁠ţwòri֣yn ׀ lá֣⁠kĕ yĕtaֽʻàm֗ẇn ẇ⁠mi⁠tȧ֤l şĕ̌mayá̇⁠ʼ֙ lá֣⁠kĕ mĕẕabĕ̇ʻi֔yn wĕ⁠şǐbĕʻá֥h ʻidá̇ni֖yn yaẖĕlĕp֣ẇn ʻàlá֑⁠ykĕ ʻa֣d diֽ̇y-ţinĕdȧ֗ʻ diֽ̇y-şǎli֤̇yt ʻilá̇yá⁠ʼ֙ bĕ̇⁠malĕk֣ẇţ ʼànáşá̌֔⁠ʼ ẇ⁠lĕ⁠man-di֥̇y yiẕĕbé֖̇ʼ yiţĕ̇ninȧֽ⁠ḣ׃"],[4,26,"וְ⁠דִ֣י אֲמַ֗רוּ לְ⁠מִשְׁבַּ֞ק עִקַּ֤ר שָׁרְשׁ֨וֹ⁠הִי֙ דִּ֣י אִֽילָנָ֔⁠א מַלְכוּתָ֖⁠ךְ לָ֣⁠ךְ קַיָּמָ֑ה מִן־דִּ֣י תִנְדַּ֔ע דִּ֥י שַׁלִּטִ֖ן שְׁמַיָּֽ⁠א׃","wĕ⁠di֣y ʼàma֗rẇ lĕ⁠mişĕ̌bȧ֞q ʻiqȧ֤r şá̌rĕş̌֨wò⁠hiy֙ di֣̇y ʼiֽyláná֔⁠ʼ malĕkẇţá֖⁠kĕ lá֣⁠kĕ qayá̇má֑h min-di֣̇y ţinĕdȧ֔ʻ di֥̇y şǎli̇ti֖n şĕ̌mayáֽ̇⁠ʼ׃"],[4,27,"לָהֵ֣ן מַלְכָּ֗⁠א מִלְכִּ⁠י֙ יִשְׁפַּ֣ר עלי⁠ך ו⁠חטי⁠ך בְּ⁠צִדְקָ֣ה פְרֻ֔ק וַ⁠עֲוָיָתָ֖⁠ךְ בְּ⁠מִחַ֣ן עֲנָ֑יִן הֵ֛ן תֶּהֱוֵ֥א אַרְכָ֖ה לִ⁠שְׁלֵוְתָֽ⁠ךְ׃","láhé֣n malĕká̇֗⁠ʼ milĕki̇⁠y֙ yişĕ̌pȧ֣r ʻly⁠k w⁠ẖty⁠k bĕ̇⁠ẕidĕqá֣h pĕru֔q wa⁠ʻàwáyáţá֖⁠kĕ bĕ̇⁠miẖa֣n ʻàná֑yin hé֛n ţėhèwé֥ʼ ʼarĕká֖h li⁠şĕ̌léwĕţáֽ⁠kĕ׃"],[4,28,"כֹּ֣לָּ⁠א מְּטָ֔א עַל־נְבוּכַדְנֶצַּ֖ר מַלְכָּֽ⁠א׃פ","kò֣̇lá̇⁠ʼ mĕ̇tá֔ʼ ʻal-nĕbẇkadĕneẕȧ֖r malĕkáֽ̇⁠ʼ׃p"],[4,29,"לִ⁠קְצָ֥ת יַרְחִ֖ין תְּרֵֽי־עֲשַׂ֑ר עַל־הֵיכַ֧ל מַלְכוּתָ֛⁠א דִּ֥י בָבֶ֖ל מְהַלֵּ֥ךְ הֲוָֽה׃","li⁠qĕẕá֥ţ yarĕẖi֖yn ţĕ̇réֽy-ʻàşâ֑r ʻal-héyka֧l malĕkẇţá֛⁠ʼ di֥̇y bábe֖l mĕhalé֥̇kĕ hàwáֽh׃"],[4,30,"עָנֵ֤ה מַלְכָּ⁠א֙ וְ⁠אָמַ֔ר הֲ⁠לָ֥א דָא־הִ֖יא בָּבֶ֣ל רַבְּתָ֑⁠א דִּֽי־אֲנָ֤ה בֱנַיְתַ⁠הּ֙ לְ⁠בֵ֣ית מַלְכ֔וּ בִּ⁠תְקַ֥ף חִסְנִ֖⁠י וְ⁠לִ⁠יקָ֥ר הַדְרִֽ⁠י׃","ʻáné֤h malĕká̇⁠ʼ֙ wĕ⁠ʼáma֔r hà⁠lá֥ʼ dáʼ-hi֖yʼ bá̇be֣l rabĕ̇ţá֑⁠ʼ diֽ̇y-ʼàná֤h bènayĕţa⁠ḣ֙ lĕ⁠bé֣yţ malĕk֔ẇ bi̇⁠ţĕqa֥p ẖisĕni֖⁠y wĕ⁠li⁠yqá֥r hadĕriֽ⁠y׃"],[4,31,"ע֗וֹד מִלְּתָ⁠א֙ בְּ⁠פֻ֣ם מַלְכָּ֔⁠א קָ֖ל מִן־שְׁמַיָּ֣⁠א נְפַ֑ל לָ֤⁠ךְ אָֽמְרִין֙ נְבוּכַדְנֶצַּ֣ר מַלְכָּ֔⁠א מַלְכוּתָ֖⁠ה עֲדָ֥ת מִנָּֽ⁠ךְ׃","ʻ֗wòd milĕ̇ţá⁠ʼ֙ bĕ̇⁠pu֣m malĕká̇֔⁠ʼ qá֖l min-şĕ̌mayá֣̇⁠ʼ nĕpa֑l lá֤⁠kĕ ʼáֽmĕriyn֙ nĕbẇkadĕneẕȧ֣r malĕká̇֔⁠ʼ malĕkẇţá֖⁠h ʻàdá֥ţ mináֽ̇⁠kĕ׃"],[4,32,"וּ⁠מִן־אֲנָשָׁ⁠א֩ לָ֨⁠ךְ טָֽרְדִ֜ין וְֽ⁠עִם־חֵיוַ֧ת בָּרָ֣⁠א מְדֹרָ֗⁠ךְ עִשְׂבָּ֤⁠א כְ⁠תוֹרִין֙ לָ֣⁠ךְ יְטַעֲמ֔וּן וְ⁠שִׁבְעָ֥ה עִדָּנִ֖ין יַחְלְפ֣וּן עלי⁠ך עַ֣ד דִּֽי־תִנְדַּ֗ע דִּֽי־שַׁלִּ֤יט עִלָּיָ⁠א֙ בְּ⁠מַלְכ֣וּת אֲנָשָׁ֔⁠א וּ⁠לְ⁠מַן־דִּ֥י יִצְבֵּ֖א יִתְּנִנַּֽ⁠הּ׃","ẇ⁠min-ʼànáşá̌⁠ʼ֩ lá֨⁠kĕ táֽrĕdi֜yn wĕֽ⁠ʻim-ẖéywa֧ţ bá̇rá֣⁠ʼ mĕdòrá֗⁠kĕ ʻişĕ̂bá֤̇⁠ʼ kĕ⁠ţwòriyn֙ lá֣⁠kĕ yĕtaʻàm֔ẇn wĕ⁠şǐbĕʻá֥h ʻidá̇ni֖yn yaẖĕlĕp֣ẇn ʻly⁠k ʻa֣d diֽ̇y-ţinĕdȧ֗ʻ diֽ̇y-şǎli֤̇yt ʻilá̇yá⁠ʼ֙ bĕ̇⁠malĕk֣ẇţ ʼànáşá̌֔⁠ʼ ẇ⁠lĕ⁠man-di֥̇y yiẕĕbé֖̇ʼ yiţĕ̇ninȧֽ⁠ḣ׃"],[4,33,"בַּ⁠הּ־שַׁעֲתָ֗⁠א מִלְּתָ⁠א֮ סָ֣פַת עַל־נְבוּכַדְנֶצַּר֒ וּ⁠מִן־אֲנָשָׁ֣⁠א טְרִ֔יד וְ⁠עִשְׂבָּ֤⁠א כְ⁠תוֹרִין֙ יֵאכֻ֔ל וּ⁠מִ⁠טַּ֥ל שְׁמַיָּ֖⁠א גִּשְׁמֵ֣⁠הּ יִצְטַבַּ֑ע עַ֣ד דִּ֥י שַׂעְרֵ֛⁠הּ כְּ⁠נִשְׁרִ֥ין רְבָ֖ה וְ⁠טִפְר֥וֹ⁠הִי כְ⁠צִפְּרִֽין׃","bȧ⁠ḣ-şǎʻàţá֗⁠ʼ milĕ̇ţá⁠ʼ֮ sá֣paţ ʻal-nĕbẇkadĕneẕȧr֒ ẇ⁠min-ʼànáşá֣̌⁠ʼ tĕri֔yd wĕ⁠ʻişĕ̂bá֤̇⁠ʼ kĕ⁠ţwòriyn֙ yéʼku֔l ẇ⁠mi⁠tȧ֥l şĕ̌mayá֖̇⁠ʼ gi̇şĕ̌mé֣⁠ḣ yiẕĕtabȧ֑ʻ ʻa֣d di֥̇y şâʻĕré֛⁠ḣ kĕ̇⁠nişĕ̌ri֥yn rĕbá֖h wĕ⁠tipĕr֥wò⁠hiy kĕ⁠ẕipĕ̇riֽyn׃"],[4,34,"וְ⁠לִ⁠קְצָ֣ת יֽוֹמַיָּ⁠ה֩ אֲנָ֨ה נְבוּכַדְנֶצַּ֜ר עַיְנַ֣⁠י ׀ לִ⁠שְׁמַיָּ֣⁠א נִטְלֵ֗ת וּ⁠מַנְדְּעִ⁠י֙ עֲלַ֣⁠י יְת֔וּב ו⁠ל⁠עלי⁠א בָּרְכֵ֔ת וּ⁠לְ⁠חַ֥י עָלְמָ֖⁠א שַׁבְּחֵ֣ת וְ⁠הַדְּרֵ֑ת דִּ֤י שָׁלְטָנֵ⁠הּ֙ שָׁלְטָ֣ן עָלַ֔ם וּ⁠מַלְכוּתֵ֖⁠הּ עִם־דָּ֥ר וְ⁠דָֽר׃","wĕ⁠li⁠qĕẕá֣ţ yֽwòmayá̇⁠h֩ ʼàná֨h nĕbẇkadĕneẕȧ֜r ʻayĕna֣⁠y ׀ li⁠şĕ̌mayá֣̇⁠ʼ nitĕlé֗ţ ẇ⁠manĕdĕ̇ʻi⁠y֙ ʻàla֣⁠y yĕţ֔ẇb w⁠l⁠ʻly⁠ʼ bá̇rĕké֔ţ ẇ⁠lĕ⁠ẖa֥y ʻálĕmá֖⁠ʼ şǎbĕ̇ẖé֣ţ wĕ⁠hadĕ̇ré֑ţ di֤̇y şá̌lĕtáné⁠ḣ֙ şá̌lĕtá֣n ʻála֔m ẇ⁠malĕkẇţé֖⁠ḣ ʻim-dá֥̇r wĕ⁠dáֽr׃"],[4,35,"וְ⁠כָל־דארי אַרְעָ⁠א֙ כְּ⁠לָ֣ה חֲשִׁיבִ֔ין וּֽ⁠כְ⁠מִצְבְּיֵ֗⁠הּ עָבֵד֙ בְּ⁠חֵ֣יל שְׁמַיָּ֔⁠א ו⁠דארי אַרְעָ֑⁠א וְ⁠לָ֤א אִיתַי֙ דִּֽי־יְמַחֵ֣א בִ⁠ידֵ֔⁠הּ וְ⁠יֵ֥אמַר לֵ֖⁠הּ מָ֥ה עֲבַֽדְתְּ׃","wĕ⁠kál-dʼry ʼarĕʻá⁠ʼ֙ kĕ̇⁠lá֣h ẖàşǐybi֔yn ẇֽ⁠kĕ⁠miẕĕbĕ̇yé֗⁠ḣ ʻábéd֙ bĕ̇⁠ẖé֣yl şĕ̌mayá̇֔⁠ʼ w⁠dʼry ʼarĕʻá֑⁠ʼ wĕ⁠lá֤ʼ ʼiyţay֙ diֽ̇y-yĕmaẖé֣ʼ bi⁠ydé֔⁠ḣ wĕ⁠yé֥ʼmar lé֖⁠ḣ má֥h ʻàbaֽdĕţĕ̇׃"],[4,36,"בֵּ⁠הּ־זִמְנָ֞⁠א מַנְדְּעִ֣⁠י ׀ יְת֣וּב עֲלַ֗⁠י וְ⁠לִ⁠יקַ֨ר מַלְכוּתִ֜⁠י הַדְרִ֤⁠י וְ⁠זִוִ⁠י֙ יְת֣וּב עֲלַ֔⁠י וְ⁠לִ֕⁠י הַדָּֽבְרַ֥⁠י וְ⁠רַבְרְבָנַ֖⁠י יְבַע֑וֹן וְ⁠עַל־מַלְכוּתִ֣⁠י הָתְקְנַ֔ת וּ⁠רְב֥וּ יַתִּירָ֖ה ה֥וּסְפַת לִֽ⁠י׃","bé̇⁠ḣ-zimĕná֞⁠ʼ manĕdĕ̇ʻi֣⁠y ׀ yĕţ֣ẇb ʻàla֗⁠y wĕ⁠li⁠yqa֨r malĕkẇţi֜⁠y hadĕri֤⁠y wĕ⁠ziwi⁠y֙ yĕţ֣ẇb ʻàla֔⁠y wĕ⁠li֕⁠y hadáֽ̇bĕra֥⁠y wĕ⁠rabĕrĕbána֖⁠y yĕbaʻ֑wòn wĕ⁠ʻal-malĕkẇţi֣⁠y háţĕqĕna֔ţ ẇ⁠rĕb֥ẇ yaţi̇yrá֖h h֥ẇsĕpaţ liֽ⁠y׃"],[4,37,"כְּעַ֞ן אֲנָ֣ה נְבוּכַדְנֶצַּ֗ר מְשַׁבַּ֨ח וּ⁠מְרוֹמֵ֤ם וּ⁠מְהַדַּר֙ לְ⁠מֶ֣לֶךְ שְׁמַיָּ֔⁠א דִּ֤י כָל־מַעֲבָד֨וֹ⁠הִי֙ קְשֹׁ֔ט וְ⁠אֹרְחָתֵ֖⁠הּ דִּ֑ין וְ⁠דִי֙ מַהְלְכִ֣ין בְּ⁠גֵוָ֔ה יָכִ֖ל לְ⁠הַשְׁפָּלָֽה׃פ","kĕ̇ʻa֞n ʼàná֣h nĕbẇkadĕneẕȧ֗r mĕşǎbȧ֨ẖ ẇ⁠mĕrwòmé֤m ẇ⁠mĕhadȧr֙ lĕ⁠me֣lekĕ şĕ̌mayá̇֔⁠ʼ di֤̇y kál-maʻàbád֨wò⁠hiy֙ qĕşò̌֔t wĕ⁠ʼòrĕẖáţé֖⁠ḣ di֑̇yn wĕ⁠diy֙ mahĕlĕki֣yn bĕ̇⁠géwá֔h yáki֖l lĕ⁠haşĕ̌pá̇láֽh׃p"],[5,1,"בֵּלְשַׁאצַּ֣ר מַלְכָּ֗⁠א עֲבַד֙ לְחֶ֣ם רַ֔ב לְ⁠רַבְרְבָנ֖וֹ⁠הִי אֲלַ֑ף וְ⁠לָ⁠קֳבֵ֥ל אַלְפָּ֖⁠א חַמְרָ֥⁠א שָׁתֵֽה׃","bé̇lĕşǎʼẕȧ֣r malĕká̇֗⁠ʼ ʻàbad֙ lĕẖe֣m ra֔b lĕ⁠rabĕrĕbán֖wò⁠hiy ʼàla֑p wĕ⁠lá⁠qobé֥l ʼalĕpá֖̇⁠ʼ ẖamĕrá֥⁠ʼ şá̌ţéֽh׃"],[5,2,"בֵּלְשַׁאצַּ֞ר אֲמַ֣ר ׀ בִּ⁠טְעֵ֣ם חַמְרָ֗⁠א לְ⁠הַיְתָיָה֙ לְ⁠מָאנֵי֙ דַּהֲבָ֣⁠א וְ⁠כַסְפָּ֔⁠א דִּ֤י הַנְפֵּק֙ נְבוּכַדְנֶצַּ֣ר אֲב֔⁠וּהִי מִן־הֵיכְלָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם וְ⁠יִשְׁתּ֣וֹן בְּ⁠ה֗וֹן מַלְכָּ⁠א֙ וְ⁠רַבְרְבָנ֔וֹ⁠הִי שֵׁגְלָתֵ֖⁠הּ וּ⁠לְחֵנָתֵֽ⁠הּ׃","bé̇lĕşǎʼẕȧ֞r ʼàma֣r ׀ bi̇⁠tĕʻé֣m ẖamĕrá֗⁠ʼ lĕ⁠hayĕţáyáh֙ lĕ⁠máʼnéy֙ dȧhàbá֣⁠ʼ wĕ⁠kasĕpá̇֔⁠ʼ di֤̇y hanĕpé̇q֙ nĕbẇkadĕneẕȧ֣r ʼàb֔⁠ẇhiy min-héykĕlá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m wĕ⁠yişĕ̌ţ֣̇wòn bĕ̇⁠h֗wòn malĕká̇⁠ʼ֙ wĕ⁠rabĕrĕbán֔wò⁠hiy şé̌gĕláţé֖⁠ḣ ẇ⁠lĕẖénáţéֽ⁠ḣ׃"],[5,3,"בֵּ⁠אדַ֗יִן הַיְתִיו֙ מָאנֵ֣י דַהֲבָ֔⁠א דִּ֣י הַנְפִּ֗קוּ מִן־הֵֽיכְלָ֛⁠א דִּֽי־בֵ֥ית אֱלָהָ֖⁠א דִּ֣י בִ⁠ירֽוּשְׁלֶ֑ם וְ⁠אִשְׁתִּ֣יו בְּ⁠ה֗וֹן מַלְכָּ⁠א֙ וְ⁠רַבְרְבָנ֔וֹ⁠הִי שֵׁגְלָתֵ֖⁠הּ וּ⁠לְחֵנָתֵֽ⁠הּ׃","bé̇⁠ʼda֗yin hayĕţiyw֙ máʼné֣y dahàbá֔⁠ʼ di֣̇y hanĕpi̇֗qẇ min-héֽykĕlá֛⁠ʼ diֽ̇y-bé֥yţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrֽẇşĕ̌le֑m wĕ⁠ʼişĕ̌ţi֣̇yw bĕ̇⁠h֗wòn malĕká̇⁠ʼ֙ wĕ⁠rabĕrĕbán֔wò⁠hiy şé̌gĕláţé֖⁠ḣ ẇ⁠lĕẖénáţéֽ⁠ḣ׃"],[5,4,"אִשְׁתִּ֖יו חַמְרָ֑⁠א וְ֠⁠שַׁבַּחוּ לֵֽ⁠אלָהֵ֞י דַּהֲבָ֧⁠א וְ⁠כַסְפָּ֛⁠א נְחָשָׁ֥⁠א פַרְזְלָ֖⁠א אָעָ֥⁠א וְ⁠אַבְנָֽ⁠א׃","ʼişĕ̌ţi֖̇yw ẖamĕrá֑⁠ʼ wĕ֠⁠şǎbȧẖẇ léֽ⁠ʼláhé֞y dȧhàbá֧⁠ʼ wĕ⁠kasĕpá֛̇⁠ʼ nĕẖáşá֥̌⁠ʼ parĕzĕlá֖⁠ʼ ʼáʻá֥⁠ʼ wĕ⁠ʼabĕnáֽ⁠ʼ׃"],[5,5,"בַּ⁠הּ־שַׁעֲתָ֗⁠ה נפקו אֶצְבְּעָן֙ דִּ֣י יַד־אֱנָ֔שׁ וְ⁠כָֽתְבָן֙ לָ⁠קֳבֵ֣ל נֶבְרַשְׁתָּ֔⁠א עַל־גִּירָ֕⁠א דִּֽי־כְתַ֥ל הֵיכְלָ֖⁠א דִּ֣י מַלְכָּ֑⁠א וּ⁠מַלְכָּ֣⁠א חָזֵ֔ה פַּ֥ס יְדָ֖⁠ה דִּ֥י כָתְבָֽה׃","bȧ⁠ḣ-şǎʻàţá֗⁠h npqw ʼeẕĕbĕ̇ʻán֙ di֣̇y yad-ʼèná֔ş̌ wĕ⁠káֽţĕbán֙ lá⁠qobé֣l nebĕraşĕ̌ţá̇֔⁠ʼ ʻal-gi̇yrá֕⁠ʼ diֽ̇y-kĕţa֥l héykĕlá֖⁠ʼ di֣̇y malĕká֑̇⁠ʼ ẇ⁠malĕká֣̇⁠ʼ ẖázé֔h pȧ֥s yĕdá֖⁠h di֥̇y káţĕbáֽh׃"],[5,6,"אֱדַ֤יִן מַלְכָּ⁠א֙ זִיוֺ֣⁠הִי שְׁנ֔וֹ⁠הִי וְ⁠רַעיֹנֹ֖⁠הִי יְבַהֲלוּנֵּ֑⁠הּ וְ⁠קִטְרֵ֤י חַרְצֵ⁠הּ֙ מִשְׁתָּרַ֔יִן וְ⁠אַ֨רְכֻבָּתֵ֔⁠הּ דָּ֥א לְ⁠דָ֖א נָֽקְשָֽׁן׃","ʼèda֤yin malĕká̇⁠ʼ֙ ziywֺ֣⁠hiy şĕ̌n֔wò⁠hiy wĕ⁠raʻyònò֖⁠hiy yĕbahàlẇné֑̇⁠ḣ wĕ⁠qitĕré֤y ẖarĕẕé⁠ḣ֙ mişĕ̌ţá̇ra֔yin wĕ⁠ʼa֨rĕkubá̇ţé֔⁠ḣ dá֥̇ʼ lĕ⁠dá֖ʼ náֽqĕşáֽ̌n׃"],[5,7,"קָרֵ֤א מַלְכָּ⁠א֙ בְּ⁠חַ֔יִל לְ⁠הֶֽעָלָה֙ לְ⁠אָ֣שְׁפַיָּ֔⁠א כשדי⁠א וְ⁠גָזְרַיָּ֑⁠א עָנֵ֨ה מַלְכָּ֜⁠א וְ⁠אָמַ֣ר ׀ לְ⁠חַכִּימֵ֣י בָבֶ֗ל דִּ֣י כָל־אֱ֠נָשׁ דִּֽי־יִקְרֵ֞ה כְּתָבָ֣⁠ה דְנָ֗ה וּ⁠פִשְׁרֵ⁠הּ֙ יְחַוִּנַּ֔⁠נִי אַרְגְּוָנָ֣⁠א יִלְבַּ֗שׁ ו⁠המונכ⁠א דִֽי־דַהֲבָ⁠א֙ עַֽל־צַוְּארֵ֔⁠הּ וְ⁠תַלְתִּ֥י בְ⁠מַלְכוּתָ֖⁠א יִשְׁלַֽט׃ס","qáré֤ʼ malĕká̇⁠ʼ֙ bĕ̇⁠ẖa֔yil lĕ⁠heֽʻáláh֙ lĕ⁠ʼá֣şĕ̌payá̇֔⁠ʼ kşdy⁠ʼ wĕ⁠gázĕrayá֑̇⁠ʼ ʻáné֨h malĕká̇֜⁠ʼ wĕ⁠ʼáma֣r ׀ lĕ⁠ẖaki̇ymé֣y bábe֗l di֣̇y kál-ʼè֠náş̌ diֽ̇y-yiqĕré֞h kĕ̇ţábá֣⁠h dĕná֗h ẇ⁠pişĕ̌ré⁠ḣ֙ yĕẖawi̇nȧ֔⁠niy ʼarĕgĕ̇wáná֣⁠ʼ yilĕbȧ֗ş̌ w⁠hmwnk⁠ʼ diֽy-dahàbá⁠ʼ֙ ʻaֽl-ẕawĕ̇ʼré֔⁠ḣ wĕ⁠ţalĕţi֥̇y bĕ⁠malĕkẇţá֖⁠ʼ yişĕ̌laֽt׃s"],[5,8,"אֱדַ֨יִן֙ עללין כֹּ֖ל חַכִּימֵ֣י מַלְכָּ֑⁠א וְ⁠לָֽא־כָהֲלִ֤ין כְּתָבָ⁠א֙ לְ⁠מִקְרֵ֔א ו⁠פשר⁠א לְ⁠הוֹדָעָ֥ה לְ⁠מַלְכָּֽ⁠א׃","ʼèda֨yin֙ ʻllyn kò֖̇l ẖaki̇ymé֣y malĕká֑̇⁠ʼ wĕ⁠láֽʼ-káhàli֤yn kĕ̇ţábá⁠ʼ֙ lĕ⁠miqĕré֔ʼ w⁠pşr⁠ʼ lĕ⁠hwòdáʻá֥h lĕ⁠malĕkáֽ̇⁠ʼ׃"],[5,9,"אֱ֠דַיִן מַלְכָּ֤⁠א בֵלְשַׁאצַּר֙ שַׂגִּ֣יא מִתְבָּהַ֔ל וְ⁠זִיוֺ֖⁠הִי שָׁנַ֣יִן עֲל֑וֹ⁠הִי וְ⁠רַבְרְבָנ֖וֹ⁠הִי מִֽשְׁתַּבְּשִֽׁין׃","ʼè֠dayin malĕká֤̇⁠ʼ bélĕşǎʼẕȧr֙ şâgi֣̇yʼ miţĕbá̇ha֔l wĕ⁠ziywֺ֖⁠hiy şá̌na֣yin ʻàl֑wò⁠hiy wĕ⁠rabĕrĕbán֖wò⁠hiy miֽşĕ̌ţȧbĕ̇şǐֽyn׃"],[5,10,"מַלְכְּתָ֕⁠א לָ⁠קֳבֵ֨ל מִלֵּ֤י מַלְכָּ⁠א֙ וְ⁠רַבְרְבָנ֔וֹ⁠הִי לְ⁠בֵ֥ית מִשְׁתְּיָ֖⁠א עללת עֲנָ֨ת מַלְכְּתָ֜⁠א וַ⁠אֲמֶ֗רֶת מַלְכָּ⁠א֙ לְ⁠עָלְמִ֣ין חֱיִ֔י אַֽל־יְבַהֲלוּ⁠ךְ֙ רַעְיוֹנָ֔⁠ךְ וְ⁠זִיוָ֖י⁠ךְ אַל־יִשְׁתַּנּֽוֹ׃","malĕkĕ̇ţá֕⁠ʼ lá⁠qobé֨l milé֤̇y malĕká̇⁠ʼ֙ wĕ⁠rabĕrĕbán֔wò⁠hiy lĕ⁠bé֥yţ mişĕ̌ţĕ̇yá֖⁠ʼ ʻllţ ʻàná֨ţ malĕkĕ̇ţá֜⁠ʼ wa⁠ʼàme֗reţ malĕká̇⁠ʼ֙ lĕ⁠ʻálĕmi֣yn ẖèyi֔y ʼaֽl-yĕbahàlẇ⁠kĕ֙ raʻĕywòná֔⁠kĕ wĕ⁠ziywá֖y⁠kĕ ʼal-yişĕ̌ţȧṅֽwò׃"],[5,11,"אִיתַ֨י גְּבַ֜ר בְּ⁠מַלְכוּתָ֗⁠ךְ דִּ֠י ר֣וּחַ אֱלָהִ֣ין קַדִּישִׁין֮ בֵּ⁠הּ֒ וּ⁠בְ⁠יוֹמֵ֣י אֲב֗⁠וּךְ נַהִיר֧וּ וְ⁠שָׂכְלְתָנ֛וּ וְ⁠חָכְמָ֥ה כְּ⁠חָכְמַת־אֱלָהִ֖ין הִשְׁתְּכַ֣חַת בֵּ֑⁠הּ וּ⁠מַלְכָּ֤⁠א נְבֻֽכַדְנֶצַּר֙ אֲב֔⁠וּךְ רַ֧ב חַרְטֻמִּ֣ין אָֽשְׁפִ֗ין כַּשְׂדָּאִין֙ גָּזְרִ֔ין הֲקִימֵ֖⁠הּ אֲב֥⁠וּךְ מַלְכָּֽ⁠א׃","ʼiyţa֨y gĕ̇ba֜r bĕ̇⁠malĕkẇţá֗⁠kĕ di̇֠y r֣ẇẖa ʼèláhi֣yn qadi̇yşǐyn֮ bé̇⁠ḣ֒ ẇ⁠bĕ⁠ywòmé֣y ʼàb֗⁠ẇkĕ nahiyr֧ẇ wĕ⁠şá̂kĕlĕţán֛ẇ wĕ⁠ẖákĕmá֥h kĕ̇⁠ẖákĕmaţ-ʼèláhi֖yn hişĕ̌ţĕ̇ka֣ẖaţ bé֑̇⁠ḣ ẇ⁠malĕká֤̇⁠ʼ nĕbuֽkadĕneẕȧr֙ ʼàb֔⁠ẇkĕ ra֧b ẖarĕtumi֣̇yn ʼáֽşĕ̌pi֗yn kȧşĕ̂dá̇ʼiyn֙ gá̇zĕri֔yn hàqiymé֖⁠ḣ ʼàb֥⁠ẇkĕ malĕkáֽ̇⁠ʼ׃"],[5,12,"כָּ⁠ל־קֳבֵ֡ל דִּ֣י ר֣וּחַ ׀ יַתִּירָ֡ה וּ⁠מַנְדַּ֡ע וְ⁠שָׂכְלְתָנ֡וּ מְפַשַּׁ֣ר חֶלְמִין֩ וַֽ⁠אַֽחֲוָיַ֨ת אֲחִידָ֜ן וּ⁠מְשָׁרֵ֣א קִטְרִ֗ין הִשְׁתְּכַ֤חַת בֵּ⁠הּ֙ בְּ⁠דָ֣נִיֵּ֔אל דִּֽי־מַלְכָּ֥⁠א שָׂם־שְׁמֵ֖⁠הּ בֵּלְטְשַׁאצַּ֑ר כְּעַ֛ן דָּנִיֵּ֥אל יִתְקְרֵ֖י וּ⁠פִשְׁרָ֥⁠ה יְהַֽחֲוֵֽה׃פ","ká̇⁠l-qobé֡l di֣̇y r֣ẇẖa ׀ yaţi̇yrá֡h ẇ⁠manĕdȧ֡ʻ wĕ⁠şá̂kĕlĕţán֡ẇ mĕpaşȧ֣̌r ẖelĕmiyn֩ waֽ⁠ʼaֽẖàwáya֨ţ ʼàẖiydá֜n ẇ⁠mĕşá̌ré֣ʼ qitĕri֗yn hişĕ̌ţĕ̇ka֤ẖaţ bé̇⁠ḣ֙ bĕ̇⁠dá֣niyé̇֔ʼl diֽ̇y-malĕká֥̇⁠ʼ şá̂m-şĕ̌mé֖⁠ḣ bé̇lĕtĕşǎʼẕȧ֑r kĕ̇ʻa֛n dá̇niyé֥̇ʼl yiţĕqĕré֖y ẇ⁠pişĕ̌rá֥⁠h yĕhaֽẖàwéֽh׃p"],[5,13,"בֵּ⁠אדַ֨יִן֙ דָּֽנִיֵּ֔אל הֻעַ֖ל קֳדָ֣ם מַלְכָּ֑⁠א עָנֵ֨ה מַלְכָּ֜⁠א וְ⁠אָמַ֣ר לְ⁠דָנִיֵּ֗אל אנתה־ה֤וּא דָנִיֵּאל֙ דִּֽי־מִן־בְּנֵ֤י גָלוּתָ⁠א֙ דִּ֣י יְה֔וּד דִּ֥י הַיְתִ֛י מַלְכָּ֥⁠א אַ֖בִ⁠י מִן־יְהֽוּד׃","bé̇⁠ʼda֨yin֙ dáֽ̇niyé̇֔ʼl huʻa֖l qodá֣m malĕká֑̇⁠ʼ ʻáné֨h malĕká̇֜⁠ʼ wĕ⁠ʼáma֣r lĕ⁠dániyé̇֗ʼl ʼnţh-h֤ẇʼ dániyé̇ʼl֙ diֽ̇y-min-bĕ̇né֤y gálẇţá⁠ʼ֙ di֣̇y yĕh֔ẇd di֥̇y hayĕţi֛y malĕká֥̇⁠ʼ ʼa֖bi⁠y min-yĕhֽẇd׃"],[5,14,"וְ⁠שִׁמְעֵ֣ת עלי⁠ך דִּ֛י ר֥וּחַ אֱלָהִ֖ין בָּ֑⁠ךְ וְ⁠נַהִיר֧וּ וְ⁠שָׂכְלְתָנ֛וּ וְ⁠חָכְמָ֥ה יַתִּירָ֖ה הִשְׁתְּכַ֥חַת בָּֽ⁠ךְ׃","wĕ⁠şǐmĕʻé֣ţ ʻly⁠k di֛̇y r֥ẇẖa ʼèláhi֖yn bá֑̇⁠kĕ wĕ⁠nahiyr֧ẇ wĕ⁠şá̂kĕlĕţán֛ẇ wĕ⁠ẖákĕmá֥h yaţi̇yrá֖h hişĕ̌ţĕ̇ka֥ẖaţ báֽ̇⁠kĕ׃"],[5,15,"וּ⁠כְעַ֞ן הֻעַ֣לּוּ קָֽדָמַ֗⁠י חַכִּֽימַיָּ⁠א֙ אָֽשְׁפַיָּ֔⁠א דִּֽי־כְתָבָ֤⁠ה דְנָה֙ יִקְר֔וֹן וּ⁠פִשְׁרֵ֖⁠הּ לְ⁠הוֹדָעֻתַ֑⁠נִי וְ⁠לָֽא־כָהֲלִ֥ין פְּשַֽׁר־מִלְּתָ֖⁠א לְ⁠הַחֲוָיָֽה׃","ẇ⁠kĕʻa֞n huʻa֣l̇ẇ qáֽdáma֗⁠y ẖakiֽ̇ymayá̇⁠ʼ֙ ʼáֽşĕ̌payá̇֔⁠ʼ diֽ̇y-kĕţábá֤⁠h dĕnáh֙ yiqĕr֔wòn ẇ⁠pişĕ̌ré֖⁠ḣ lĕ⁠hwòdáʻuţa֑⁠niy wĕ⁠láֽʼ-káhàli֥yn pĕ̇şǎֽr-milĕ̇ţá֖⁠ʼ lĕ⁠haẖàwáyáֽh׃"],[5,16,"וַ⁠אֲנָה֙ שִׁמְעֵ֣ת עלי⁠ך דִּֽי־תוכל פִּשְׁרִ֛ין לְ⁠מִפְשַׁ֖ר וְ⁠קִטְרִ֣ין לְ⁠מִשְׁרֵ֑א כְּעַ֡ן הֵן֩ תוכל כְּתָבָ֜⁠א לְ⁠מִקְרֵ֗א וּ⁠פִשְׁרֵ⁠הּ֙ לְ⁠הוֹדָ֣עֻתַ֔⁠נִי אַרְגְּוָנָ֣⁠א תִלְבַּ֗שׁ ו⁠המונכ⁠א דִֽי־דַהֲבָ⁠א֙ עַֽל־צַוְּארָ֔⁠ךְ וְ⁠תַלְתָּ֥א בְ⁠מַלְכוּתָ֖⁠א תִּשְׁלַֽט׃פ","wa⁠ʼànáh֙ şǐmĕʻé֣ţ ʻly⁠k diֽ̇y-ţwkl pi̇şĕ̌ri֛yn lĕ⁠mipĕşǎ֖r wĕ⁠qitĕri֣yn lĕ⁠mişĕ̌ré֑ʼ kĕ̇ʻa֡n hén֩ ţwkl kĕ̇ţábá֜⁠ʼ lĕ⁠miqĕré֗ʼ ẇ⁠pişĕ̌ré⁠ḣ֙ lĕ⁠hwòdá֣ʻuţa֔⁠niy ʼarĕgĕ̇wáná֣⁠ʼ ţilĕbȧ֗ş̌ w⁠hmwnk⁠ʼ diֽy-dahàbá⁠ʼ֙ ʻaֽl-ẕawĕ̇ʼrá֔⁠kĕ wĕ⁠ţalĕţá֥̇ʼ bĕ⁠malĕkẇţá֖⁠ʼ ţi̇şĕ̌laֽt׃p"],[5,17,"בֵּ⁠אדַ֜יִן עָנֵ֣ה דָנִיֵּ֗אל וְ⁠אָמַר֙ קֳדָ֣ם מַלְכָּ֔⁠א מַתְּנָתָ⁠ךְ֙ לָ֣⁠ךְ לֶֽהֶוְיָ֔ן וּ⁠נְבָ֥זְבְּיָתָ֖⁠ךְ לְ⁠אָחֳרָ֣ן הַ֑ב בְּרַ֗ם כְּתָבָ⁠א֙ אֶקְרֵ֣א לְ⁠מַלְכָּ֔⁠א וּ⁠פִשְׁרָ֖⁠א אֲהוֹדְעִנֵּֽ⁠הּ׃","bé̇⁠ʼda֜yin ʻáné֣h dániyé̇֗ʼl wĕ⁠ʼámar֙ qodá֣m malĕká̇֔⁠ʼ maţĕ̇náţá⁠kĕ֙ lá֣⁠kĕ leֽhewĕyá֔n ẇ⁠nĕbá֥zĕbĕ̇yáţá֖⁠kĕ lĕ⁠ʼáẖorá֣n ha֑b bĕ̇ra֗m kĕ̇ţábá⁠ʼ֙ ʼeqĕré֣ʼ lĕ⁠malĕká̇֔⁠ʼ ẇ⁠pişĕ̌rá֖⁠ʼ ʼàhwòdĕʻinéֽ̇⁠ḣ׃"],[5,18,"אנתה מַלְכָּ֑⁠א אֱלָהָ⁠א֙ עלי⁠א מַלְכוּתָ֤⁠א וּ⁠רְבוּתָ⁠א֙ וִ⁠יקָרָ֣⁠א וְ⁠הַדְרָ֔⁠ה יְהַ֖ב לִ⁠נְבֻכַדְנֶצַּ֥ר אֲבֽ⁠וּךְ׃","ʼnţh malĕká֑̇⁠ʼ ʼèláhá⁠ʼ֙ ʻly⁠ʼ malĕkẇţá֤⁠ʼ ẇ⁠rĕbẇţá⁠ʼ֙ wi⁠yqárá֣⁠ʼ wĕ⁠hadĕrá֔⁠h yĕha֖b li⁠nĕbukadĕneẕȧ֥r ʼàbֽ⁠ẇkĕ׃"],[5,19,"וּ⁠מִן־רְבוּתָ⁠א֙ דִּ֣י יְהַב־לֵ֔⁠הּ כֹּ֣ל עַֽמְמַיָּ֗⁠א אֻמַיָּ⁠א֙ וְ⁠לִשָּׁ֣נַיָּ֔⁠א הֲו֛וֹ זאעין וְ⁠דָחֲלִ֖ין מִן־קֳדָמ֑וֹ⁠הִי דִּֽי־הֲוָ֨ה צָבֵ֜א הֲוָ֣א קָטֵ֗ל וְ⁠דִֽי־הֲוָ֤ה צָבֵא֙ הֲוָ֣ה מַחֵ֔א וְ⁠דִֽי־הֲוָ֤ה צָבֵא֙ הֲוָ֣ה מָרִ֔ים וְ⁠דִֽי־הֲוָ֥ה צָבֵ֖א הֲוָ֥ה מַשְׁפִּֽיל׃","ẇ⁠min-rĕbẇţá⁠ʼ֙ di֣̇y yĕhab-lé֔⁠ḣ kò֣̇l ʻaֽmĕmayá̇֗⁠ʼ ʼumayá̇⁠ʼ֙ wĕ⁠lişá֣̇̌nayá̇֔⁠ʼ hàw֛wò zʼʻyn wĕ⁠dáẖàli֖yn min-qodám֑wò⁠hiy diֽ̇y-hàwá֨h ẕábé֜ʼ hàwá֣ʼ qáté֗l wĕ⁠diֽy-hàwá֤h ẕábéʼ֙ hàwá֣h maẖé֔ʼ wĕ⁠diֽy-hàwá֤h ẕábéʼ֙ hàwá֣h mári֔ym wĕ⁠diֽy-hàwá֥h ẕábé֖ʼ hàwá֥h maşĕ̌piֽ̇yl׃"],[5,20,"וּ⁠כְ⁠דִי֙ רִ֣ם לִבְבֵ֔⁠הּ וְ⁠רוּחֵ֖⁠הּ תִּֽקְפַ֣ת לַ⁠הֲזָדָ֑ה הָנְחַת֙ מִן־כָּרְסֵ֣א מַלְכוּתֵ֔⁠הּ וִֽ⁠יקָרָ֖⁠ה הֶעְדִּ֥יוּ מִנֵּֽ⁠הּ׃","ẇ⁠kĕ⁠diy֙ ri֣m libĕbé֔⁠ḣ wĕ⁠rẇẖé֖⁠ḣ ţiֽ̇qĕpa֣ţ la⁠hàzádá֑h hánĕẖaţ֙ min-ká̇rĕsé֣ʼ malĕkẇţé֔⁠ḣ wiֽ⁠yqárá֖⁠h heʻĕdi֥̇yẇ minéֽ̇⁠ḣ׃"],[5,21,"וּ⁠מִן־בְּנֵי֩ אֲנָשָׁ֨⁠א טְרִ֜יד וְ⁠לִבְבֵ֣⁠הּ ׀ עִם־חֵיוְתָ֣⁠א שוי וְ⁠עִם־עֲרָֽדַיָּ⁠א֙ מְדוֹרֵ֔⁠הּ עִשְׂבָּ֤⁠א כְ⁠תוֹרִין֙ יְטַ֣עֲמוּנֵּ֔⁠הּ וּ⁠מִ⁠טַּ֥ל שְׁמַיָּ֖⁠א גִּשְׁמֵ֣⁠הּ יִצְטַבַּ֑ע עַ֣ד דִּֽי־יְדַ֗ע דִּֽי־שַׁלִּ֞יט אֱלָהָ֤⁠א עלי⁠א בְּ⁠מַלְכ֣וּת אֲנָשָׁ֔⁠א וּ⁠לְ⁠מַן־דִּ֥י יִצְבֵּ֖ה יְהָקֵ֥ים עלי⁠ה׃","ẇ⁠min-bĕ̇néy֩ ʼànáşá̌֨⁠ʼ tĕri֜yd wĕ⁠libĕbé֣⁠ḣ ׀ ʻim-ẖéywĕţá֣⁠ʼ şwy wĕ⁠ʻim-ʻàráֽdayá̇⁠ʼ֙ mĕdwòré֔⁠ḣ ʻişĕ̂bá֤̇⁠ʼ kĕ⁠ţwòriyn֙ yĕta֣ʻàmẇné̇֔⁠ḣ ẇ⁠mi⁠tȧ֥l şĕ̌mayá֖̇⁠ʼ gi̇şĕ̌mé֣⁠ḣ yiẕĕtabȧ֑ʻ ʻa֣d diֽ̇y-yĕda֗ʻ diֽ̇y-şǎli̇֞yt ʼèláhá֤⁠ʼ ʻly⁠ʼ bĕ̇⁠malĕk֣ẇţ ʼànáşá̌֔⁠ʼ ẇ⁠lĕ⁠man-di֥̇y yiẕĕbé֖̇h yĕháqé֥ym ʻly⁠h׃"],[5,22,"ו⁠אנתה בְּרֵ⁠הּ֙ בֵּלְשַׁאצַּ֔ר לָ֥א הַשְׁפֵּ֖לְתְּ לִבְבָ֑⁠ךְ כָּ⁠ל־קֳבֵ֕ל דִּ֥י כָל־דְּנָ֖ה יְדַֽעְתָּ׃","w⁠ʼnţh bĕ̇ré⁠ḣ֙ bé̇lĕşǎʼẕȧ֔r lá֥ʼ haşĕ̌pé֖̇lĕţĕ̇ libĕbá֑⁠kĕ ká̇⁠l-qobé֕l di֥̇y kál-dĕ̇ná֖h yĕdaֽʻĕţá̇׃"],[5,23,"וְ⁠עַ֣ל מָרֵֽא־שְׁמַיָּ֣⁠א ׀ הִתְרוֹמַ֡מְתָּ וּ⁠לְ⁠מָֽאנַיָּ֨⁠א דִֽי־בַיְתֵ֜⁠הּ הַיְתִ֣יו קדמי⁠ך ו⁠אנתה ו⁠רברבני⁠ך שֵֽׁגְלָתָ֣⁠ךְ וּ⁠לְחֵנָתָ⁠ךְ֮ חַמְרָ⁠א֮ שָׁתַ֣יִן בְּ⁠הוֹן֒ וְ⁠לֵֽ⁠אלָהֵ֣י כַסְפָּֽ⁠א־וְ֠⁠דַהֲבָ⁠א נְחָשָׁ֨⁠א פַרְזְלָ֜⁠א אָעָ֣⁠א וְ⁠אַבְנָ֗⁠א דִּ֠י לָֽא־חָזַ֧יִן וְ⁠לָא־שָׁמְעִ֛ין וְ⁠לָ֥א יָדְעִ֖ין שַׁבַּ֑חְתָּ וְ⁠לֵֽ⁠אלָהָ֞⁠א דִּֽי־נִשְׁמְתָ֥⁠ךְ בִּ⁠ידֵ֛⁠הּ וְ⁠כָל־אֹרְחָתָ֥⁠ךְ לֵ֖⁠הּ לָ֥א הַדַּֽרְתָּ׃","wĕ⁠ʻa֣l máréֽʼ-şĕ̌mayá֣̇⁠ʼ ׀ hiţĕrwòma֡mĕţá̇ ẇ⁠lĕ⁠máֽʼnayá̇֨⁠ʼ diֽy-bayĕţé֜⁠ḣ hayĕţi֣yw qdmy⁠k w⁠ʼnţh w⁠rbrbny⁠k şéֽ̌gĕláţá֣⁠kĕ ẇ⁠lĕẖénáţá⁠kĕ֮ ẖamĕrá⁠ʼ֮ şá̌ţa֣yin bĕ̇⁠hwòn֒ wĕ⁠léֽ⁠ʼláhé֣y kasĕpáֽ̇⁠ʼ-wĕ֠⁠dahàbá⁠ʼ nĕẖáşá̌֨⁠ʼ parĕzĕlá֜⁠ʼ ʼáʻá֣⁠ʼ wĕ⁠ʼabĕná֗⁠ʼ di̇֠y láֽʼ-ẖáza֧yin wĕ⁠láʼ-şá̌mĕʻi֛yn wĕ⁠lá֥ʼ yádĕʻi֖yn şǎbȧ֑ẖĕţá̇ wĕ⁠léֽ⁠ʼláhá֞⁠ʼ diֽ̇y-nişĕ̌mĕţá֥⁠kĕ bi̇⁠ydé֛⁠ḣ wĕ⁠kál-ʼòrĕẖáţá֥⁠kĕ lé֖⁠ḣ lá֥ʼ hadȧֽrĕţá̇׃"],[5,24,"בֵּ⁠אדַ֨יִן֙ מִן־קֳדָמ֔וֹ⁠הִי שְׁלִ֖יַחַ פַּסָּ֣⁠א דִֽי־יְדָ֑⁠א וּ⁠כְתָבָ֥⁠א דְנָ֖ה רְשִֽׁים׃","bé̇⁠ʼda֨yin֙ min-qodám֔wò⁠hiy şĕ̌li֖yaẖa pȧsá֣̇⁠ʼ diֽy-yĕdá֑⁠ʼ ẇ⁠kĕţábá֥⁠ʼ dĕná֖h rĕşǐֽym׃"],[5,25,"וּ⁠דְנָ֥ה כְתָבָ֖⁠א דִּ֣י רְשִׁ֑ים מְנֵ֥א מְנֵ֖א תְּקֵ֥ל וּ⁠פַרְסִֽין׃","ẇ⁠dĕná֥h kĕţábá֖⁠ʼ di֣̇y rĕşǐ֑ym mĕné֥ʼ mĕné֖ʼ ţĕ̇qé֥l ẇ⁠parĕsiֽyn׃"],[5,26,"דְּנָ֖ה פְּשַֽׁר־מִלְּתָ֑⁠א מְנֵ֕א מְנָֽה־אֱלָהָ֥⁠א מַלְכוּתָ֖⁠ךְ וְ⁠הַשְׁלְמַֽ⁠הּ׃","dĕ̇ná֖h pĕ̇şǎֽr-milĕ̇ţá֑⁠ʼ mĕné֕ʼ mĕnáֽh-ʼèláhá֥⁠ʼ malĕkẇţá֖⁠kĕ wĕ⁠haşĕ̌lĕmaֽ⁠ḣ׃"],[5,27,"תְּקֵ֑ל תְּקִ֥ילְתָּה בְ⁠מֹֽאזַנְיָ֖⁠א וְ⁠הִשְׁתְּכַ֥חַתְּ חַסִּֽיר׃","ţĕ̇qé֑l ţĕ̇qi֥ylĕţá̇h bĕ⁠mòֽʼzanĕyá֖⁠ʼ wĕ⁠hişĕ̌ţĕ̇ka֥ẖaţĕ̇ ẖasiֽ̇yr׃"],[5,28,"פְּרֵ֑ס פְּרִיסַת֙ מַלְכוּתָ֔⁠ךְ וִ⁠יהִיבַ֖ת לְ⁠מָדַ֥י וּ⁠פָרָֽס׃","pĕ̇ré֑s pĕ̇riysaţ֙ malĕkẇţá֔⁠kĕ wi⁠yhiyba֖ţ lĕ⁠máda֥y ẇ⁠páráֽs׃"],[5,29,"בֵּ⁠אדַ֣יִן ׀ אֲמַ֣ר בֵּלְשַׁאצַּ֗ר וְ⁠הַלְבִּ֤ישׁוּ לְ⁠דָֽנִיֵּאל֙ אַרְגְּוָנָ֔⁠א ו⁠המונכ⁠א דִֽי־דַהֲבָ֖⁠א עַֽל־צַוְּארֵ֑⁠הּ וְ⁠הַכְרִ֣זֽוּ עֲל֔וֹ⁠הִי דִּֽי־לֶהֱוֵ֥א שַׁלִּ֛יט תַּלְתָּ֖א בְּ⁠מַלְכוּתָֽ⁠א׃","bé̇⁠ʼda֣yin ׀ ʼàma֣r bé̇lĕşǎʼẕȧ֗r wĕ⁠halĕbi֤̇yş̌ẇ lĕ⁠dáֽniyé̇ʼl֙ ʼarĕgĕ̇wáná֔⁠ʼ w⁠hmwnk⁠ʼ diֽy-dahàbá֖⁠ʼ ʻaֽl-ẕawĕ̇ʼré֑⁠ḣ wĕ⁠hakĕri֣zֽẇ ʻàl֔wò⁠hiy diֽ̇y-lehèwé֥ʼ şǎli֛̇yt ţȧlĕţá֖̇ʼ bĕ̇⁠malĕkẇţáֽ⁠ʼ׃"],[5,30,"בֵּ֚⁠הּ בְּ⁠לֵ֣ילְיָ֔⁠א קְטִ֕יל בֵּלְאשַׁצַּ֖ר מַלְכָּ֥⁠א כשדי⁠א׃פ","bé֚̇⁠ḣ bĕ̇⁠lé֣ylĕyá֔⁠ʼ qĕti֕yl bé̇lĕʼşǎẕȧ֖r malĕká֥̇⁠ʼ kşdy⁠ʼ׃p"],[5,31,"וְ⁠דָרְיָ֨וֶשׁ֙ מָֽדָיָ֔⁠א קַבֵּ֖ל מַלְכוּתָ֑⁠א כְּ⁠בַ֥ר שְׁנִ֖ין שִׁתִּ֥ין וְ⁠תַרְתֵּֽין׃","wĕ⁠dárĕyá֨weş̌֙ máֽdáyá֔⁠ʼ qabé֖̇l malĕkẇţá֑⁠ʼ kĕ̇⁠ba֥r şĕ̌ni֖yn şǐţi֥̇yn wĕ⁠ţarĕţéֽ̇yn׃"],[6,1,"שְׁפַר֙ קֳדָ֣ם דָּרְיָ֔וֶשׁ וַ⁠הֲקִים֙ עַל־מַלְכוּתָ֔⁠א לַ⁠אֲחַשְׁדַּרְפְּנַיָּ֖⁠א מְאָ֣ה וְ⁠עֶשְׂרִ֑ין דִּ֥י לֶהֱוֺ֖ן בְּ⁠כָל־מַלְכוּתָֽ⁠א׃","şĕ̌par֙ qodá֣m dá̇rĕyá֔weş̌ wa⁠hàqiym֙ ʻal-malĕkẇţá֔⁠ʼ la⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá֖̇⁠ʼ mĕʼá֣h wĕ⁠ʻeşĕ̂ri֑yn di֥̇y lehèwֺ֖n bĕ̇⁠kál-malĕkẇţáֽ⁠ʼ׃"],[6,2,"וְ⁠עֵ֤לָּא מִנְּ⁠הוֹן֙ סָרְכִ֣ין תְּלָתָ֔א דִּ֥י דָנִיֵּ֖אל חַֽד־מִנְּ⁠ה֑וֹן דִּֽי־לֶהֱוֺ֞ן אֲחַשְׁדַּרְפְּנַיָּ֣⁠א אִלֵּ֗ין יָהֲבִ֤ין לְ⁠הוֹן֙ טַעְמָ֔⁠א וּ⁠מַלְכָּ֖⁠א לָֽא־לֶהֱוֵ֥א נָזִֽק׃","wĕ⁠ʻé֤lá̇ʼ minĕ̇⁠hwòn֙ sárĕki֣yn ţĕ̇láţá֔ʼ di֥̇y dániyé֖̇ʼl ẖaֽd-minĕ̇⁠h֑wòn diֽ̇y-lehèwֺ֞n ʼàẖaşĕ̌dȧrĕpĕ̇nayá֣̇⁠ʼ ʼilé̇֗yn yáhàbi֤yn lĕ⁠hwòn֙ taʻĕmá֔⁠ʼ ẇ⁠malĕká֖̇⁠ʼ láֽʼ-lehèwé֥ʼ náziֽq׃"],[6,3,"אֱדַ֨יִן֙ דָּנִיֵּ֣אל דְּנָ֔ה הֲוָ֣א מִתְנַצַּ֔ח עַל־סָרְכַיָּ֖⁠א וַ⁠אֲחַשְׁדַּרְפְּנַיָּ֑⁠א כָּ⁠ל־קֳבֵ֗ל דִּ֣י ר֤וּחַ יַתִּירָא֙ בֵּ֔⁠הּ וּ⁠מַלְכָּ֣⁠א עֲשִׁ֔ית לַ⁠הֲקָמוּתֵ֖⁠הּ עַל־כָּל־מַלְכוּתָֽ⁠א׃","ʼèda֨yin֙ dá̇niyé֣̇ʼl dĕ̇ná֔h hàwá֣ʼ miţĕnaẕȧ֔ẖ ʻal-sárĕkayá֖̇⁠ʼ wa⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá֑̇⁠ʼ ká̇⁠l-qobé֗l di֣̇y r֤ẇẖa yaţi̇yráʼ֙ bé̇֔⁠ḣ ẇ⁠malĕká֣̇⁠ʼ ʻàşǐ֔yţ la⁠hàqámẇţé֖⁠ḣ ʻal-ká̇l-malĕkẇţáֽ⁠ʼ׃"],[6,4,"אֱדַ֨יִן סָֽרְכַיָּ֜⁠א וַ⁠אֲחַשְׁדַּרְפְּנַיָּ֗⁠א הֲו֨וֹ בָעַ֧יִן עִלָּ֛ה לְ⁠הַשְׁכָּחָ֥ה לְ⁠דָנִיֵּ֖אל מִ⁠צַּ֣ד מַלְכוּתָ֑⁠א וְ⁠כָל־עִלָּ֨ה וּ⁠שְׁחִיתָ֜ה לָא־יָכְלִ֣ין לְ⁠הַשְׁכָּחָ֗ה כָּ⁠ל־קֳבֵל֙ דִּֽי־מְהֵימַ֣ן ה֔וּא וְ⁠כָל־שָׁלוּ֙ וּ⁠שְׁחִיתָ֔ה לָ֥א הִשְׁתְּכַ֖חַת עֲלֽוֹ⁠הִי׃","ʼèda֨yin sáֽrĕkayá̇֜⁠ʼ wa⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇֗⁠ʼ hàw֨wò báʻa֧yin ʻilá֛̇h lĕ⁠haşĕ̌ká̇ẖá֥h lĕ⁠dániyé֖̇ʼl mi⁠ẕȧ֣d malĕkẇţá֑⁠ʼ wĕ⁠kál-ʻilá̇֨h ẇ⁠şĕ̌ẖiyţá֜h láʼ-yákĕli֣yn lĕ⁠haşĕ̌ká̇ẖá֗h ká̇⁠l-qobél֙ diֽ̇y-mĕhéyma֣n h֔ẇʼ wĕ⁠kál-şá̌lẇ֙ ẇ⁠şĕ̌ẖiyţá֔h lá֥ʼ hişĕ̌ţĕ̇ka֖ẖaţ ʻàlֽwò⁠hiy׃"],[6,5,"אֱ֠דַיִן גֻּבְרַיָּ֤⁠א אִלֵּךְ֙ אָֽמְרִ֔ין דִּ֣י לָ֧א נְהַשְׁכַּ֛ח לְ⁠דָנִיֵּ֥אל דְּנָ֖ה כָּל־עִלָּ֑א לָהֵ֕ן הַשְׁכַּ֥חְנָֽה עֲל֖וֹ⁠הִי בְּ⁠דָ֥ת אֱלָהֵֽ⁠הּ׃ס","ʼè֠dayin gu̇bĕrayá֤̇⁠ʼ ʼilé̇kĕ֙ ʼáֽmĕri֔yn di֣̇y lá֧ʼ nĕhaşĕ̌kȧ֛ẖ lĕ⁠dániyé֥̇ʼl dĕ̇ná֖h ká̇l-ʻilá֑̇ʼ láhé֕n haşĕ̌kȧ֥ẖĕnáֽh ʻàl֖wò⁠hiy bĕ̇⁠dá֥ţ ʼèláhéֽ⁠ḣ׃s"],[6,6,"אֱ֠דַיִן סָרְכַיָּ֤⁠א וַ⁠אֲחַשְׁדַּרְפְּנַיָּ⁠א֙ אִלֵּ֔ן הַרְגִּ֖שׁוּ עַל־מַלְכָּ֑⁠א וְ⁠כֵן֙ אָמְרִ֣ין לֵ֔⁠הּ דָּרְיָ֥וֶשׁ מַלְכָּ֖⁠א לְ⁠עָלְמִ֥ין חֱיִֽי׃","ʼè֠dayin sárĕkayá֤̇⁠ʼ wa⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇⁠ʼ֙ ʼilé̇֔n harĕgi֖̇ş̌ẇ ʻal-malĕká֑̇⁠ʼ wĕ⁠kén֙ ʼámĕri֣yn lé֔⁠ḣ dá̇rĕyá֥weş̌ malĕká֖̇⁠ʼ lĕ⁠ʻálĕmi֥yn ẖèyiֽy׃"],[6,7,"אִתְיָעַ֜טוּ כֹּ֣ל ׀ סָרְכֵ֣י מַלְכוּתָ֗⁠א סִגְנַיָּ֤⁠א וַֽ⁠אֲחַשְׁדַּרְפְּנַיָּ⁠א֙ הַדָּֽבְרַיָּ֣⁠א וּ⁠פַחֲוָתָ֔⁠א לְ⁠קַיָּמָ֤ה קְיָם֙ מַלְכָּ֔⁠א וּ⁠לְ⁠תַקָּפָ֖ה אֱסָ֑ר דִּ֣י כָל־דִּֽי־יִבְעֵ֣ה בָ֠עוּ מִן־כָּל־אֱלָ֨הּ וֶֽ⁠אֱנָ֜שׁ עַד־יוֹמִ֣ין תְּלָתִ֗ין לָהֵן֙ מִנָּ֣⁠ךְ מַלְכָּ֔⁠א יִתְרְמֵ֕א לְ⁠גֹ֖ב אַרְיָוָתָֽ⁠א׃","ʼiţĕyáʻa֜tẇ kò֣̇l ׀ sárĕké֣y malĕkẇţá֗⁠ʼ sigĕnayá֤̇⁠ʼ wֽa⁠ʼàẖaşĕ̌dȧrĕpĕ̇nayá̇⁠ʼ֙ hadáֽ̇bĕrayá֣̇⁠ʼ ẇ⁠paẖàwáţá֔⁠ʼ lĕ⁠qayá̇má֤h qĕyám֙ malĕká̇֔⁠ʼ ẇ⁠lĕ⁠ţaqá̇pá֖h ʼèsá֑r di֣̇y kál-diֽ̇y-yibĕʻé֣h bá֠ʻẇ min-ká̇l-ʼèlá֨ḣ weֽ⁠ʼèná֜ş̌ ʻad-ywòmi֣yn ţĕ̇láţi֗yn láhén֙ miná֣̇⁠kĕ malĕká̇֔⁠ʼ yiţĕrĕmé֕ʼ lĕ⁠gò֖b ʼarĕyáwáţáֽ⁠ʼ׃"],[6,8,"כְּעַ֣ן מַלְכָּ֔⁠א תְּקִ֥ים אֱסָרָ֖⁠א וְ⁠תִרְשֻׁ֣ם כְּתָבָ֑⁠א דִּ֣י לָ֧א לְ⁠הַשְׁנָיָ֛ה כְּ⁠דָת־מָדַ֥י וּ⁠פָרַ֖ס דִּי־לָ֥א תֶעְדֵּֽא׃","kĕ̇ʻa֣n malĕká̇֔⁠ʼ ţĕ̇qi֥ym ʼèsárá֖⁠ʼ wĕ⁠ţirĕşǔ֣m kĕ̇ţábá֑⁠ʼ di֣̇y lá֧ʼ lĕ⁠haşĕ̌náyá֛h kĕ̇⁠dáţ-máda֥y ẇ⁠pára֖s di̇y-lá֥ʼ ţeʻĕdéֽ̇ʼ׃"],[6,9,"כָּ⁠ל־קֳבֵ֖ל דְּנָ֑ה מַלְכָּ⁠א֙ דָּֽרְיָ֔וֶשׁ רְשַׁ֥ם כְּתָבָ֖⁠א וֶ⁠אֱסָרָֽ⁠א׃","ká̇⁠l-qobé֖l dĕ̇ná֑h malĕká̇⁠ʼ֙ dáֽ̇rĕyá֔weş̌ rĕşǎ֥m kĕ̇ţábá֖⁠ʼ we⁠ʼèsáráֽ⁠ʼ׃"],[6,10,"וְ֠⁠דָנִיֵּאל כְּ⁠דִ֨י יְדַ֜ע דִּֽי־רְשִׁ֤ים כְּתָבָ⁠א֙ עַ֣ל לְ⁠בַיְתֵ֔⁠הּ וְ⁠כַוִּ֨ין פְּתִיחָ֥ן לֵ⁠הּ֙ בְּ⁠עִלִּיתֵ֔⁠הּ נֶ֖גֶד יְרוּשְׁלֶ֑ם וְ⁠זִמְנִין֩ תְּלָתָ֨ה בְ⁠יוֹמָ֜⁠א ה֣וּא ׀ בָּרֵ֣ךְ עַל־בִּרְכ֗וֹ⁠הִי וּ⁠מְצַלֵּ֤א וּ⁠מוֹדֵא֙ קֳדָ֣ם אֱלָהֵ֔⁠הּ כָּ⁠ל־קֳבֵל֙ דִּֽי־הֲוָ֣א עָבֵ֔ד מִן־קַדְמַ֖ת דְּנָֽה׃ס","wĕ֠⁠dániyé̇ʼl kĕ̇⁠di֨y yĕda֜ʻ diֽ̇y-rĕşǐ֤ym kĕ̇ţábá⁠ʼ֙ ʻa֣l lĕ⁠bayĕţé֔⁠ḣ wĕ⁠kawi̇֨yn pĕ̇ţiyẖá֥n lé⁠ḣ֙ bĕ̇⁠ʻili̇yţé֔⁠ḣ ne֖ged yĕrẇşĕ̌le֑m wĕ⁠zimĕniyn֩ ţĕ̇láţá֨h bĕ⁠ywòmá֜⁠ʼ h֣ẇʼ ׀ bá̇ré֣kĕ ʻal-bi̇rĕk֗wò⁠hiy ẇ⁠mĕẕalé֤̇ʼ ẇ⁠mwòdéʼ֙ qodá֣m ʼèláhé֔⁠ḣ ká̇⁠l-qobél֙ diֽ̇y-hàwá֣ʼ ʻábé֔d min-qadĕma֖ţ dĕ̇náֽh׃s"],[6,11,"אֱ֠דַיִן גֻּבְרַיָּ֤⁠א אִלֵּךְ֙ הַרְגִּ֔שׁוּ וְ⁠הַשְׁכַּ֖חוּ לְ⁠דָנִיֵּ֑אל בָּעֵ֥א וּ⁠מִתְחַנַּ֖ן קֳדָ֥ם אֱלָהֵֽ⁠הּ׃","ʼè֠dayin gu̇bĕrayá֤̇⁠ʼ ʼilé̇kĕ֙ harĕgi̇֔ş̌ẇ wĕ⁠haşĕ̌kȧ֖ẖẇ lĕ⁠dániyé֑̇ʼl bá̇ʻé֥ʼ ẇ⁠miţĕẖanȧ֖n qodá֥m ʼèláhéֽ⁠ḣ׃"],[6,12,"בֵּ֠⁠אדַיִן קְרִ֨יבוּ וְ⁠אָמְרִ֥ין קֳדָם־מַלְכָּ⁠א֮ עַל־אֱסָ֣ר מַלְכָּ⁠א֒ הֲ⁠לָ֧א אֱסָ֣ר רְשַׁ֗מְתָּ דִּ֣י כָל־אֱנָ֡שׁ דִּֽי־יִבְעֵה֩ מִן־כָּל־אֱלָ֨הּ וֶֽ⁠אֱנָ֜שׁ עַד־יוֹמִ֣ין תְּלָתִ֗ין לָהֵן֙ מִנָּ֣⁠ךְ מַלְכָּ֔⁠א יִתְרְמֵ֕א לְ⁠ג֖וֹב אַרְיָותָ֑⁠א עָנֵ֨ה מַלְכָּ֜⁠א וְ⁠אָמַ֗ר יַצִּיבָ֧א מִלְּתָ֛⁠א כְּ⁠דָת־מָדַ֥י וּ⁠פָרַ֖ס דִּי־לָ֥א תֶעְדֵּֽא׃","bé̇֠⁠ʼdayin qĕri֨ybẇ wĕ⁠ʼámĕri֥yn qodám-malĕká̇⁠ʼ֮ ʻal-ʼèsá֣r malĕká̇⁠ʼ֒ hà⁠lá֧ʼ ʼèsá֣r rĕşǎ֗mĕţá̇ di֣̇y kál-ʼèná֡ş̌ diֽ̇y-yibĕʻéh֩ min-ká̇l-ʼèlá֨ḣ weֽ⁠ʼèná֜ş̌ ʻad-ywòmi֣yn ţĕ̇láţi֗yn láhén֙ miná֣̇⁠kĕ malĕká̇֔⁠ʼ yiţĕrĕmé֕ʼ lĕ⁠g֖wòb ʼarĕyáwţá֑⁠ʼ ʻáné֨h malĕká̇֜⁠ʼ wĕ⁠ʼáma֗r yaẕi̇ybá֧ʼ milĕ̇ţá֛⁠ʼ kĕ̇⁠dáţ-máda֥y ẇ⁠pára֖s di̇y-lá֥ʼ ţeʻĕdéֽ̇ʼ׃"],[6,13,"בֵּ֠⁠אדַיִן עֲנ֣וֹ וְ⁠אָמְרִין֮ קֳדָ֣ם מַלְכָּ⁠א֒ דִּ֣י דָנִיֵּ֡אל דִּי֩ מִן־בְּנֵ֨י גָלוּתָ֜⁠א דִּ֣י יְה֗וּד לָא־שָׂ֨ם עלי⁠ך מַלְכָּ⁠א֙ טְעֵ֔ם וְ⁠עַל־אֱסָרָ֖⁠א דִּ֣י רְשַׁ֑מְתָּ וְ⁠זִמְנִ֤ין תְּלָתָה֙ בְּ⁠יוֹמָ֔⁠א בָּעֵ֖א בָּעוּתֵֽ⁠הּ׃","bé̇֠⁠ʼdayin ʻàn֣wò wĕ⁠ʼámĕriyn֮ qodá֣m malĕká̇⁠ʼ֒ di֣̇y dániyé̇֡ʼl di̇y֩ min-bĕ̇né֨y gálẇţá֜⁠ʼ di֣̇y yĕh֗ẇd láʼ-şá̂֨m ʻly⁠k malĕká̇⁠ʼ֙ tĕʻé֔m wĕ⁠ʻal-ʼèsárá֖⁠ʼ di֣̇y rĕşǎ֑mĕţá̇ wĕ⁠zimĕni֤yn ţĕ̇láţáh֙ bĕ̇⁠ywòmá֔⁠ʼ bá̇ʻé֖ʼ bá̇ʻẇţéֽ⁠ḣ׃"],[6,14,"אֱדַ֨יִן מַלְכָּ֜⁠א כְּ⁠דִ֧י מִלְּתָ֣⁠א שְׁמַ֗ע שַׂגִּיא֙ בְּאֵ֣שׁ עֲל֔וֹ⁠הִי וְ⁠עַ֧ל דָּנִיֵּ֛אל שָׂ֥ם בָּ֖ל לְ⁠שֵׁיזָבוּתֵ֑⁠הּ וְ⁠עַד֙ מֶֽעָלֵ֣י שִׁמְשָׁ֔⁠א הֲוָ֥א מִשְׁתַּדַּ֖ר לְ⁠הַצָּלוּתֵֽ⁠הּ׃","ʼèda֨yin malĕká̇֜⁠ʼ kĕ̇⁠di֧y milĕ̇ţá֣⁠ʼ şĕ̌ma֗ʻ şâgi̇yʼ֙ bĕ̇ʼé֣ş̌ ʻàl֔wò⁠hiy wĕ⁠ʻa֧l dá̇niyé֛̇ʼl şá֥̂m bá֖̇l lĕ⁠şé̌yzábẇţé֑⁠ḣ wĕ⁠ʻad֙ meֽʻálé֣y şǐmĕşá̌֔⁠ʼ hàwá֥ʼ mişĕ̌ţȧdȧ֖r lĕ⁠haẕá̇lẇţéֽ⁠ḣ׃"],[6,15,"בֵּ⁠אדַ֨יִן֙ גֻּבְרַיָּ֣⁠א אִלֵּ֔ךְ הַרְגִּ֖שׁוּ עַל־מַלְכָּ֑⁠א וְ⁠אָמְרִ֣ין לְ⁠מַלְכָּ֗⁠א דַּ֤ע מַלְכָּ⁠א֙ דִּֽי־דָת֙ לְ⁠מָדַ֣י וּ⁠פָרַ֔ס דִּֽי־כָל־אֱסָ֥ר וּ⁠קְיָ֛ם דִּֽי־מַלְכָּ֥⁠א יְהָקֵ֖ים לָ֥א לְ⁠הַשְׁנָיָֽה׃","bé̇⁠ʼda֨yin֙ gu̇bĕrayá֣̇⁠ʼ ʼilé̇֔kĕ harĕgi֖̇ş̌ẇ ʻal-malĕká֑̇⁠ʼ wĕ⁠ʼámĕri֣yn lĕ⁠malĕká̇֗⁠ʼ dȧ֤ʻ malĕká̇⁠ʼ֙ diֽ̇y-dáţ֙ lĕ⁠máda֣y ẇ⁠pára֔s diֽ̇y-kál-ʼèsá֥r ẇ⁠qĕyá֛m diֽ̇y-malĕká֥̇⁠ʼ yĕháqé֖ym lá֥ʼ lĕ⁠haşĕ̌náyáֽh׃"],[6,16,"בֵּ⁠אדַ֜יִן מַלְכָּ֣⁠א אֲמַ֗ר וְ⁠הַיְתִיו֙ לְ⁠דָ֣נִיֵּ֔אל וּ⁠רְמ֕וֹ לְ⁠גֻבָּ֖⁠א דִּ֣י אַרְיָוָתָ֑⁠א עָנֵ֤ה מַלְכָּ⁠א֙ וְ⁠אָמַ֣ר לְ⁠דָנִיֵּ֔אל אֱלָהָ֗⁠ךְ דִּ֣י אנתה פָּֽלַֽח־לֵ⁠הּ֙ בִּ⁠תְדִירָ֔⁠א ה֖וּא יְשֵׁיזְבִנָּֽ⁠ךְ׃","bé̇⁠ʼda֜yin malĕká֣̇⁠ʼ ʼàma֗r wĕ⁠hayĕţiyw֙ lĕ⁠dá֣niyé̇֔ʼl ẇ⁠rĕm֕wò lĕ⁠gubá֖̇⁠ʼ di֣̇y ʼarĕyáwáţá֑⁠ʼ ʻáné֤h malĕká̇⁠ʼ֙ wĕ⁠ʼáma֣r lĕ⁠dániyé̇֔ʼl ʼèláhá֗⁠kĕ di֣̇y ʼnţh páֽ̇laֽẖ-lé⁠ḣ֙ bi̇⁠ţĕdiyrá֔⁠ʼ h֖ẇʼ yĕşé̌yzĕbináֽ̇⁠kĕ׃"],[6,17,"וְ⁠הֵיתָ֨יִת֙ אֶ֣בֶן חֲדָ֔ה וְ⁠שֻׂמַ֖ת עַל־פֻּ֣ם גֻּבָּ֑⁠א וְ⁠חַתְמַ֨⁠הּ מַלְכָּ֜⁠א בְּ⁠עִזְקְתֵ֗⁠הּ וּ⁠בְ⁠עִזְקָת֙ רַבְרְבָנ֔וֹ⁠הִי דִּ֛י לָא־תִשְׁנֵ֥א צְב֖וּ בְּ⁠דָנִיֵּֽאל׃","wĕ⁠héyţá֨yiţ֙ ʼe֣ben ẖàdá֔h wĕ⁠şûma֖ţ ʻal-pu֣̇m gu̇bá֑̇⁠ʼ wĕ⁠ẖaţĕma֨⁠ḣ malĕká̇֜⁠ʼ bĕ̇⁠ʻizĕqĕţé֗⁠ḣ ẇ⁠bĕ⁠ʻizĕqáţ֙ rabĕrĕbán֔wò⁠hiy di֛̇y láʼ-ţişĕ̌né֥ʼ ẕĕb֖ẇ bĕ̇⁠dániyéֽ̇ʼl׃"],[6,18,"אֱ֠דַיִן אֲזַ֨ל מַלְכָּ֤⁠א לְ⁠הֵֽיכְלֵ⁠הּ֙ וּ⁠בָ֣ת טְוָ֔ת וְ⁠דַחֲוָ֖ן לָא־הַנְעֵ֣ל קָֽדָמ֑וֹ⁠הִי וְ⁠שִׁנְתֵּ֖⁠הּ נַדַּ֥ת עֲלֽוֹ⁠הִי׃","ʼè֠dayin ʼàza֨l malĕká֤̇⁠ʼ lĕ⁠héֽykĕlé⁠ḣ֙ ẇ⁠bá֣ţ tĕwá֔ţ wĕ⁠daẖàwá֖n láʼ-hanĕʻé֣l qáֽdám֑wò⁠hiy wĕ⁠şǐnĕţé֖̇⁠ḣ nadȧ֥ţ ʻàlֽwò⁠hiy׃"],[6,19,"בֵּ⁠אדַ֣יִן מַלְכָּ֔⁠א בִּ⁠שְׁפַּרְפָּרָ֖⁠א יְק֣וּם בְּ⁠נָגְהָ֑⁠א וּ⁠בְ⁠הִ֨תְבְּהָלָ֔ה לְ⁠גֻבָּ֥⁠א דִֽי־אַרְיָוָתָ֖⁠א אֲזַֽל׃","bé̇⁠ʼda֣yin malĕká̇֔⁠ʼ bi̇⁠şĕ̌pȧrĕpá̇rá֖⁠ʼ yĕq֣ẇm bĕ̇⁠nágĕhá֑⁠ʼ ẇ⁠bĕ⁠hi֨ţĕbĕ̇hálá֔h lĕ⁠gubá֥̇⁠ʼ diֽy-ʼarĕyáwáţá֖⁠ʼ ʼàzaֽl׃"],[6,20,"וּ⁠כְ⁠מִקְרְבֵ֣⁠הּ לְ⁠גֻבָּ֔⁠א לְ⁠דָ֣נִיֵּ֔אל בְּ⁠קָ֥ל עֲצִ֖יב זְעִ֑ק עָנֵ֨ה מַלְכָּ֜⁠א וְ⁠אָמַ֣ר לְ⁠דָנִיֵּ֗אל דָּֽנִיֵּאל֙ עֲבֵד֙ אֱלָהָ֣⁠א חַיָּ֔⁠א אֱלָהָ֗⁠ךְ דִּ֣י אנתה פָּֽלַֽח־לֵ⁠הּ֙ בִּ⁠תְדִירָ֔⁠א הַ⁠יְכִ֥ל לְ⁠שֵׁיזָבוּתָ֖⁠ךְ מִן־אַרְיָוָתָֽ⁠א׃","ẇ⁠kĕ⁠miqĕrĕbé֣⁠ḣ lĕ⁠gubá̇֔⁠ʼ lĕ⁠dá֣niyé̇֔ʼl bĕ̇⁠qá֥l ʻàẕi֖yb zĕʻi֑q ʻáné֨h malĕká̇֜⁠ʼ wĕ⁠ʼáma֣r lĕ⁠dániyé̇֗ʼl dáֽ̇niyé̇ʼl֙ ʻàbéd֙ ʼèláhá֣⁠ʼ ẖayá̇֔⁠ʼ ʼèláhá֗⁠kĕ di֣̇y ʼnţh páֽ̇laֽẖ-lé⁠ḣ֙ bi̇⁠ţĕdiyrá֔⁠ʼ ha⁠yĕki֥l lĕ⁠şé̌yzábẇţá֖⁠kĕ min-ʼarĕyáwáţáֽ⁠ʼ׃"],[6,21,"אֱדַ֨יִן֙ דָּנִיֶּ֔אל עִם־מַלְכָּ֖⁠א מַלִּ֑ל מַלְכָּ֖⁠א לְ⁠עָלְמִ֥ין חֱיִֽי׃","ʼèda֨yin֙ dá̇niyė֔ʼl ʻim-malĕká֖̇⁠ʼ mali֑̇l malĕká֖̇⁠ʼ lĕ⁠ʻálĕmi֥yn ẖèyiֽy׃"],[6,22,"אֱלָהִ֞⁠י שְׁלַ֣ח מַלְאֲכֵ֗⁠הּ וּֽ⁠סֲגַ֛ר פֻּ֥ם אַרְיָוָתָ֖⁠א וְ⁠לָ֣א חַבְּל֑וּ⁠נִי כָּ⁠ל־קֳבֵ֗ל דִּ֤י קָֽדָמ֨וֹ⁠הִי֙ זָכוּ֙ הִשְׁתְּכַ֣חַת לִ֔⁠י וְ⁠אַ֤ף קדמי⁠ך מַלְכָּ֔⁠א חֲבוּלָ֖ה לָ֥א עַבְדֵֽת׃","ʼèláhi֞⁠y şĕ̌la֣ẖ malĕʼàké֗⁠ḣ ẇֽ⁠sàga֛r pu֥̇m ʼarĕyáwáţá֖⁠ʼ wĕ⁠lá֣ʼ ẖabĕ̇l֑ẇ⁠niy ká̇⁠l-qobé֗l di֤̇y qáֽdám֨wò⁠hiy֙ zákẇ֙ hişĕ̌ţĕ̇ka֣ẖaţ li֔⁠y wĕ⁠ʼa֤p qdmy⁠k malĕká̇֔⁠ʼ ẖàbẇlá֖h lá֥ʼ ʻabĕdéֽţ׃"],[6,23,"בֵּ⁠אדַ֣יִן מַלְכָּ֗⁠א שַׂגִּיא֙ טְאֵ֣ב עֲל֔וֹ⁠הִי וּ⁠לְ⁠דָ֣נִיֵּ֔אל אֲמַ֖ר לְ⁠הַנְסָקָ֣ה מִן־גֻּבָּ֑⁠א וְ⁠הֻסַּ֨ק דָּנִיֵּ֜אל מִן־גֻּבָּ֗⁠א וְ⁠כָל־חֲבָל֙ לָא־הִשְׁתְּכַ֣ח בֵּ֔⁠הּ דִּ֖י הֵימִ֥ן בֵּ⁠אלָהֵֽ⁠הּ׃","bé̇⁠ʼda֣yin malĕká̇֗⁠ʼ şâgi̇yʼ֙ tĕʼé֣b ʻàl֔wò⁠hiy ẇ⁠lĕ⁠dá֣niyé̇֔ʼl ʼàma֖r lĕ⁠hanĕsáqá֣h min-gu̇bá֑̇⁠ʼ wĕ⁠husȧ֨q dá̇niyé̇֜ʼl min-gu̇bá̇֗⁠ʼ wĕ⁠kál-ẖàbál֙ láʼ-hişĕ̌ţĕ̇ka֣ẖ bé̇֔⁠ḣ di֖̇y héymi֥n bé̇⁠ʼláhéֽ⁠ḣ׃"],[6,24,"וַ⁠אֲמַ֣ר מַלְכָּ֗⁠א וְ⁠הַיְתִ֞יו גֻּבְרַיָּ֤⁠א אִלֵּךְ֙ דִּֽי־אֲכַ֤לוּ קַרְצ֨וֹ⁠הִי֙ דִּ֣י דָֽנִיֵּ֔אל וּ⁠לְ⁠גֹ֤ב אַרְיָוָתָ⁠א֙ רְמ֔וֹ אִנּ֖וּן בְּנֵי⁠ה֣וֹן וּ⁠נְשֵׁי⁠ה֑וֹן וְ⁠לָֽא־מְט֞וֹ לְ⁠אַרְעִ֣ית גֻּבָּ֗⁠א עַ֠ד דִּֽי־שְׁלִ֤טֽוּ בְ⁠הוֹן֙ אַרְיָ֣וָתָ֔⁠א וְ⁠כָל־גַּרְמֵי⁠ה֖וֹן הַדִּֽקוּ׃","wa⁠ʼàma֣r malĕká̇֗⁠ʼ wĕ⁠hayĕţi֞yw gu̇bĕrayá֤̇⁠ʼ ʼilé̇kĕ֙ diֽ̇y-ʼàka֤lẇ qarĕẕ֨wò⁠hiy֙ di֣̇y dáֽniyé̇֔ʼl ẇ⁠lĕ⁠gò֤b ʼarĕyáwáţá⁠ʼ֙ rĕm֔wò ʼiṅ֖ẇn bĕ̇néy⁠h֣wòn ẇ⁠nĕşé̌y⁠h֑wòn wĕ⁠láֽʼ-mĕt֞wò lĕ⁠ʼarĕʻi֣yţ gu̇bá̇֗⁠ʼ ʻa֠d diֽ̇y-şĕ̌li֤tֽẇ bĕ⁠hwòn֙ ʼarĕyá֣wáţá֔⁠ʼ wĕ⁠kál-gȧrĕméy⁠h֖wòn hadiֽ̇qẇ׃"],[6,25,"בֵּ⁠אדַ֜יִן דָּרְיָ֣וֶשׁ מַלְכָּ֗⁠א כְּ֠תַב לְֽ⁠כָל־עַֽמְמַיָּ֞⁠א אֻמַיָּ֧⁠א וְ⁠לִשָּׁנַיָּ֛⁠א דִּֽי־דארין בְּ⁠כָל־אַרְעָ֖⁠א שְׁלָמְ⁠כ֥וֹן יִשְׂגֵּֽא׃","bé̇⁠ʼda֜yin dá̇rĕyá֣weş̌ malĕká̇֗⁠ʼ kĕ̇֠ţab lĕֽ⁠kál-ʻaֽmĕmayá̇֞⁠ʼ ʼumayá֧̇⁠ʼ wĕ⁠lişá̇̌nayá֛̇⁠ʼ diֽ̇y-dʼryn bĕ̇⁠kál-ʼarĕʻá֖⁠ʼ şĕ̌lámĕ⁠k֥wòn yişĕ̂géֽ̇ʼ׃"],[6,26,"מִן־קֳדָמַ⁠י֮ שִׂ֣ים טְעֵם֒ דִּ֣י ׀ בְּ⁠כָל־שָׁלְטָ֣ן מַלְכוּתִ֗⁠י לֶהֱוֺ֤ן זאעין וְ⁠דָ֣חֲלִ֔ין מִן־קֳדָ֖ם אֱלָהֵ֣⁠הּ דִּי־דָֽנִיֵּ֑אל דִּי־ה֣וּא ׀ אֱלָהָ֣⁠א חַיָּ֗⁠א וְ⁠קַיָּם֙ לְ⁠עָ֣לְמִ֔ין וּ⁠מַלְכוּתֵ⁠הּ֙ דִּֽי־לָ֣א תִתְחַבַּ֔ל וְ⁠שָׁלְטָנֵ֖⁠הּ עַד־סוֹפָֽ⁠א׃","min-qodáma⁠y֮ şî֣ym tĕʻém֒ di֣̇y ׀ bĕ̇⁠kál-şá̌lĕtá֣n malĕkẇţi֗⁠y lehèwֺ֤n zʼʻyn wĕ⁠dá֣ẖàli֔yn min-qodá֖m ʼèláhé֣⁠ḣ di̇y-dáֽniyé֑̇ʼl di̇y-h֣ẇʼ ׀ ʼèláhá֣⁠ʼ ẖayá̇֗⁠ʼ wĕ⁠qayá̇m֙ lĕ⁠ʻá֣lĕmi֔yn ẇ⁠malĕkẇţé⁠ḣ֙ diֽ̇y-lá֣ʼ ţiţĕẖabȧ֔l wĕ⁠şá̌lĕtáné֖⁠ḣ ʻad-swòpáֽ⁠ʼ׃"],[6,27,"מְשֵׁיזִ֣ב וּ⁠מַצִּ֗ל וְ⁠עָבֵד֙ אָתִ֣ין וְ⁠תִמְהִ֔ין בִּ⁠שְׁמַיָּ֖⁠א וּ⁠בְ⁠אַרְעָ֑⁠א דִּ֚י שֵׁיזִ֣יב לְ⁠דָֽנִיֵּ֔אל מִן־יַ֖ד אַרְיָוָתָֽ⁠א׃","mĕşé̌yzi֣b ẇ⁠maẕi̇֗l wĕ⁠ʻábéd֙ ʼáţi֣yn wĕ⁠ţimĕhi֔yn bi̇⁠şĕ̌mayá֖̇⁠ʼ ẇ⁠bĕ⁠ʼarĕʻá֑⁠ʼ di֚̇y şé̌yzi֣yb lĕ⁠dáֽniyé̇֔ʼl min-ya֖d ʼarĕyáwáţáֽ⁠ʼ׃"],[6,28,"וְ⁠דָנִיֵּ֣אל דְּנָ֔ה הַצְלַ֖ח בְּ⁠מַלְכ֣וּת דָּרְיָ֑וֶשׁ וּ⁠בְ⁠מַלְכ֖וּת כּ֥וֹרֶשׁ פרסי⁠א׃פ","wĕ⁠dániyé֣̇ʼl dĕ̇ná֔h haẕĕla֖ẖ bĕ̇⁠malĕk֣ẇţ dá̇rĕyá֑weş̌ ẇ⁠bĕ⁠malĕk֖ẇţ k֥̇wòreş̌ prsy⁠ʼ׃p"],[7,1,"בִּ⁠שְׁנַ֣ת חֲדָ֗ה לְ⁠בֵלְאשַׁצַּר֙ מֶ֣לֶךְ בָּבֶ֔ל דָּנִיֵּאל֙ חֵ֣לֶם חֲזָ֔ה וְ⁠חֶזְוֵ֥י רֵאשֵׁ֖⁠הּ עַֽל־מִשְׁכְּבֵ֑⁠הּ בֵּ⁠אדַ֨יִן֙ חֶלְמָ֣⁠א כְתַ֔ב רֵ֥אשׁ מִלִּ֖ין אֲמַֽר׃","bi̇⁠şĕ̌na֣ţ ẖàdá֗h lĕ⁠bélĕʼşǎẕȧr֙ me֣lekĕ bá̇be֔l dá̇niyé̇ʼl֙ ẖé֣lem ẖàzá֔h wĕ⁠ẖezĕwé֥y réʼşé֖̌⁠ḣ ʻaֽl-mişĕ̌kĕ̇bé֑⁠ḣ bé̇⁠ʼda֨yin֙ ẖelĕmá֣⁠ʼ kĕţa֔b ré֥ʼş̌ mili֖̇yn ʼàmaֽr׃"],[7,2,"עָנֵ֤ה דָנִיֵּאל֙ וְ⁠אָמַ֔ר חָזֵ֥ה הֲוֵ֛ית בְּ⁠חֶזְוִ֖⁠י עִם־לֵֽילְיָ֑⁠א וַ⁠אֲר֗וּ אַרְבַּע֙ רוּחֵ֣י שְׁמַיָּ֔⁠א מְגִיחָ֖ן לְ⁠יַמָּ֥⁠א רַבָּֽ⁠א׃","ʻáné֤h dániyé̇ʼl֙ wĕ⁠ʼáma֔r ẖázé֥h hàwé֛yţ bĕ̇⁠ẖezĕwi֖⁠y ʻim-léֽylĕyá֑⁠ʼ wa⁠ʼàr֗ẇ ʼarĕbȧʻ֙ rẇẖé֣y şĕ̌mayá̇֔⁠ʼ mĕgiyẖá֖n lĕ⁠yamá֥̇⁠ʼ rabáֽ̇⁠ʼ׃"],[7,3,"וְ⁠אַרְבַּ֤ע חֵיוָן֙ רַבְרְבָ֔ן סָלְקָ֖ן מִן־יַמָּ֑⁠א שָׁנְיָ֖ן דָּ֥א מִן־דָּֽא׃","wĕ⁠ʼarĕbȧ֤ʻ ẖéywán֙ rabĕrĕbá֔n sálĕqá֖n min-yamá֑̇⁠ʼ şá̌nĕyá֖n dá֥̇ʼ min-dáֽ̇ʼ׃"],[7,4,"קַדְמָיְתָ֣⁠א כְ⁠אַרְיֵ֔ה וְ⁠גַפִּ֥ין דִּֽי־נְשַׁ֖ר לַ֑⁠הּ חָזֵ֣ה הֲוֵ֡ית עַד֩ דִּי־מְּרִ֨יטוּ גַפַּ֜י⁠הּ וּ⁠נְטִ֣ילַת מִן־אַרְעָ֗⁠א וְ⁠עַל־רַגְלַ֨יִן֙ כֶּ⁠אֱנָ֣שׁ הֳקִימַ֔ת וּ⁠לְבַ֥ב אֱנָ֖שׁ יְהִ֥יב לַֽ⁠הּ׃","qadĕmáyĕţá֣⁠ʼ kĕ⁠ʼarĕyé֔h wĕ⁠gapi֥̇yn diֽ̇y-nĕşǎ֖r la֑⁠ḣ ẖázé֣h hàwé֡yţ ʻad֩ di̇y-mĕ̇ri֨ytẇ gapȧ֜y⁠ḣ ẇ⁠nĕti֣ylaţ min-ʼarĕʻá֗⁠ʼ wĕ⁠ʻal-ragĕla֨yin֙ kė⁠ʼèná֣ş̌ hoqiyma֔ţ ẇ⁠lĕba֥b ʼèná֖ş̌ yĕhi֥yb laֽ⁠ḣ׃"],[7,5,"וַ⁠אֲר֣וּ חֵיוָה֩ אָחֳרִ֨י תִנְיָנָ֜ה דָּמְיָ֣ה לְ⁠דֹ֗ב וְ⁠לִ⁠שְׂטַר־חַד֙ הֳקִמַ֔ת וּ⁠תְלָ֥ת עִלְעִ֛ין בְּ⁠פֻמַּ֖⁠הּ בֵּ֣ין שני⁠ה וְ⁠כֵן֙ אָמְרִ֣ין לַ֔⁠הּ ק֥וּמִֽי אֲכֻ֖לִי בְּשַׂ֥ר שַׂגִּֽיא׃","wa⁠ʼàr֣ẇ ẖéywáh֩ ʼáẖori֨y ţinĕyáná֜h dá̇mĕyá֣h lĕ⁠dò֗b wĕ⁠li⁠şĕ̂tar-ẖad֙ hoqima֔ţ ẇ⁠ţĕlá֥ţ ʻilĕʻi֛yn bĕ̇⁠pumȧ֖⁠ḣ bé֣̇yn şny⁠h wĕ⁠kén֙ ʼámĕri֣yn la֔⁠ḣ q֥ẇmiֽy ʼàku֖liy bĕ̇şâ֥r şâgiֽ̇yʼ׃"],[7,6,"בָּאתַ֨ר דְּנָ֜ה חָזֵ֣ה הֲוֵ֗ית וַ⁠אֲר֤וּ אָֽחֳרִי֙ כִּ⁠נְמַ֔ר וְ⁠לַ֨⁠הּ גַּפִּ֥ין אַרְבַּ֛ע דִּי־ע֖וֹף עַל־גבי⁠ה וְ⁠אַרְבְּעָ֤ה רֵאשִׁין֙ לְ⁠חֵ֣יוְתָ֔⁠א וְ⁠שָׁלְטָ֖ן יְהִ֥יב לַֽ⁠הּ׃","bá̇ʼţa֨r dĕ̇ná֜h ẖázé֣h hàwé֗yţ wa⁠ʼàr֤ẇ ʼáֽẖoriy֙ ki̇⁠nĕma֔r wĕ⁠la֨⁠ḣ gȧpi֥̇yn ʼarĕbȧ֛ʻ di̇y-ʻ֖wòp ʻal-gby⁠h wĕ⁠ʼarĕbĕ̇ʻá֤h réʼşǐyn֙ lĕ⁠ẖé֣ywĕţá֔⁠ʼ wĕ⁠şá̌lĕtá֖n yĕhi֥yb laֽ⁠ḣ׃"],[7,7,"בָּאתַ֣ר דְּנָה֩ חָזֵ֨ה הֲוֵ֜ית בְּ⁠חֶזְוֵ֣י לֵֽילְיָ֗⁠א וַ⁠אֲר֣וּ חֵיוָ֣ה רביעיה דְּחִילָה֩ וְ⁠אֵֽימְתָנִ֨י וְ⁠תַקִּיפָ֜א יַתִּ֗ירָא וְ⁠שִׁנַּ֨יִן דִּֽי־פַרְזֶ֥ל לַ⁠הּ֙ רַבְרְבָ֔ן אָֽכְלָ֣ה וּ⁠מַדֱּקָ֔ה וּ⁠שְׁאָרָ֖⁠א ב⁠רגלי⁠ה רָפְסָ֑ה וְ⁠הִ֣יא מְשַׁנְּיָ֗ה מִן־כָּל־חֵֽיוָתָ⁠א֙ דִּ֣י קָֽדָמַ֔י⁠הּ וְ⁠קַרְנַ֥יִן עֲשַׂ֖ר לַֽ⁠הּ׃","bá̇ʼţa֣r dĕ̇náh֩ ẖázé֨h hàwé֜yţ bĕ̇⁠ẖezĕwé֣y léֽylĕyá֗⁠ʼ wa⁠ʼàr֣ẇ ẖéywá֣h rbyʻyh dĕ̇ẖiyláh֩ wĕ⁠ʼéֽymĕţáni֨y wĕ⁠ţaqi̇ypá֜ʼ yaţi̇֗yráʼ wĕ⁠şǐnȧ֨yin diֽ̇y-parĕze֥l la⁠ḣ֙ rabĕrĕbá֔n ʼáֽkĕlá֣h ẇ⁠madè̇qá֔h ẇ⁠şĕ̌ʼárá֖⁠ʼ b⁠rgly⁠h rápĕsá֑h wĕ⁠hi֣yʼ mĕşǎnĕ̇yá֗h min-ká̇l-ẖéֽywáţá⁠ʼ֙ di֣̇y qֽádáma֔y⁠ḣ wĕ⁠qarĕna֥yin ʻàşâ֖r laֽ⁠ḣ׃"],[7,8,"מִשְׂתַּכַּ֨ל הֲוֵ֜ית בְּ⁠קַרְנַיָּ֗⁠א וַ֠⁠אֲלוּ קֶ֣רֶן אָחֳרִ֤י זְעֵירָה֙ סִלְקָ֣ת ביני⁠הון וּ⁠תְלָ֗ת מִן־קַרְנַיָּ⁠א֙ קַדְמָ֣יָתָ֔⁠א אתעקרו מִן־קדמי⁠ה וַ⁠אֲל֨וּ עַיְנִ֜ין כְּ⁠עַיְנֵ֤י אֲנָשָׁ⁠א֙ בְּ⁠קַרְנָ⁠א־דָ֔א וּ⁠פֻ֖ם מְמַלִּ֥ל רַבְרְבָֽן׃","mişĕ̂ţȧkȧ֨l hàwé֜yţ bĕ̇⁠qarĕnayá̇֗⁠ʼ wa֠⁠ʼàlẇ qe֣ren ʼáẖori֤y zĕʻéyráh֙ silĕqá֣ţ byny⁠hwn ẇ⁠ţĕlá֗ţ min-qarĕnayá̇⁠ʼ֙ qadĕmá֣yáţá֔⁠ʼ ʼţʻqrw min-qdmy⁠h wa⁠ʼàl֨ẇ ʻayĕni֜yn kĕ̇⁠ʻayĕné֤y ʼànáşá̌⁠ʼ֙ bĕ̇⁠qarĕná⁠ʼ-dá֔ʼ ẇ⁠pu֖m mĕmali֥̇l rabĕrĕbáֽn׃"],[7,9,"חָזֵ֣ה הֲוֵ֗ית עַ֣ד דִּ֤י כָרְסָוָן֙ רְמִ֔יו וְ⁠עַתִּ֥יק יוֹמִ֖ין יְתִ֑ב לְבוּשֵׁ֣⁠הּ ׀ כִּ⁠תְלַ֣ג חִוָּ֗ר וּ⁠שְׂעַ֤ר רֵאשֵׁ⁠הּ֙ כַּ⁠עֲמַ֣ר נְקֵ֔א כָּרְסְיֵ⁠הּ֙ שְׁבִיבִ֣ין דִּי־נ֔וּר גַּלְגִּלּ֖וֹ⁠הִי נ֥וּר דָּלִֽק׃","ẖázé֣h hàwé֗yţ ʻa֣d di֤̇y kárĕsáwán֙ rĕmi֔yw wĕ⁠ʻaţi֥̇yq ywòmi֖yn yĕţi֑b lĕbẇşé֣̌⁠ḣ ׀ ki̇⁠ţĕla֣g ẖiwá̇֗r ẇ⁠şĕ̂ʻa֤r réʼşé̌⁠ḣ֙ kȧ⁠ʻàma֣r nĕqé֔ʼ ká̇rĕsĕyé⁠ḣ֙ şĕ̌biybi֣yn di̇y-n֔ẇr gȧlĕgi̇l֖̇wò⁠hiy n֥ẇr dá̇liֽq׃"],[7,10,"נְהַ֣ר דִּי־נ֗וּר נָגֵ֤ד וְ⁠נָפֵק֙ מִן־קֳדָמ֔וֹ⁠הִי אֶ֤לֶף אלפים יְשַׁמְּשׁוּנֵּ֔⁠הּ וְ⁠רִבּ֥וֹ רבון קָֽדָמ֣וֹ⁠הִי יְקוּמ֑וּן דִּינָ֥⁠א יְתִ֖ב וְ⁠סִפְרִ֥ין פְּתִֽיחוּ׃","nĕha֣r di̇y-n֗ẇr nágé֤d wĕ⁠nápéq֙ min-qodám֔wò⁠hiy ʼe֤lep ʼlpym yĕşǎmĕ̇ş̌ẇné̇֔⁠ḣ wĕ⁠riḃ֥wò rbwn qֽádám֣wò⁠hiy yĕqẇm֑ẇn di̇yná֥⁠ʼ yĕţi֖b wĕ⁠sipĕri֥yn pĕ̇ţiֽyẖẇ׃"],[7,11,"חָזֵ֣ה הֲוֵ֔ית בֵּ⁠אדַ֗יִן מִן־קָל֙ מִלַּיָּ֣⁠א רַבְרְבָתָ֔⁠א דִּ֥י קַרְנָ֖⁠א מְמַלֱּלָ֑ה חָזֵ֣ה הֲוֵ֡ית עַד֩ דִּ֨י קְטִילַ֤ת חֵֽיוְתָ⁠א֙ וְ⁠הוּבַ֣ד גִּשְׁמַ֔⁠הּ וִ⁠יהִיבַ֖ת לִ⁠יקֵדַ֥ת אֶשָּֽׁא׃","ẖázé֣h hàwé֔yţ bé̇⁠ʼda֗yin min-qál֙ milȧyá֣̇⁠ʼ rabĕrĕbáţá֔⁠ʼ di֥̇y qarĕná֖⁠ʼ mĕmalè̇lá֑h ẖázé֣h hàwé֡yţ ʻad֩ di̇֨y qĕtiyla֤ţ ẖéֽywĕţá⁠ʼ֙ wĕ⁠hẇba֣d gi̇şĕ̌ma֔⁠ḣ wi⁠yhiyba֖ţ li⁠yqéda֥ţ ʼeşáֽ̇̌ʼ׃"],[7,12,"וּ⁠שְׁאָר֙ חֵֽיוָתָ֔⁠א הֶעְדִּ֖יו שָׁלְטָנְ⁠ה֑וֹן וְ⁠אַרְכָ֧ה בְ⁠חַיִּ֛ין יְהִ֥יבַת לְ⁠ה֖וֹן עַד־זְמַ֥ן וְ⁠עִדָּֽן׃","ẇ⁠şĕ̌ʼár֙ ẖéֽywáţá֔⁠ʼ heʻĕdi֖̇yw şá̌lĕtánĕ⁠h֑wòn wĕ⁠ʼarĕká֧h bĕ⁠ẖayi֛̇yn yĕhi֥ybaţ lĕ⁠h֖wòn ʻad-zĕma֥n wĕ⁠ʻidáֽ̇n׃"],[7,13,"חָזֵ֤ה הֲוֵית֙ בְּ⁠חֶזְוֵ֣י לֵֽילְיָ֔⁠א וַ⁠אֲרוּ֙ עִם־עֲנָנֵ֣י שְׁמַיָּ֔⁠א כְּ⁠בַ֥ר אֱנָ֖שׁ אָתֵ֣ה הֲוָ֑ה וְ⁠עַד־עַתִּ֤יק יֽוֹמַיָּ⁠א֙ מְטָ֔ה וּ⁠קְדָמ֖וֹ⁠הִי הַקְרְבֽוּ⁠הִי׃","ẖázé֤h hàwéyţ֙ bĕ̇⁠ẖezĕwé֣y léֽylĕyá֔⁠ʼ wa⁠ʼàrẇ֙ ʻim-ʻànáné֣y şĕ̌mayá̇֔⁠ʼ kĕ̇⁠ba֥r ʼèná֖ş̌ ʼáţé֣h hàwá֑h wĕ⁠ʻad-ʻaţi֤̇yq yֽwòmayá̇⁠ʼ֙ mĕtá֔h ẇ⁠qĕdám֖wò⁠hiy haqĕrĕbֽẇ⁠hiy׃"],[7,14,"וְ⁠לֵ֨⁠הּ יְהִ֤יב שָׁלְטָן֙ וִ⁠יקָ֣ר וּ⁠מַלְכ֔וּ וְ⁠כֹ֣ל עַֽמְמַיָּ֗⁠א אֻמַיָּ֛⁠א וְ⁠לִשָּׁנַיָּ֖⁠א לֵ֣⁠הּ יִפְלְח֑וּן שָׁלְטָנֵ֞⁠הּ שָׁלְטָ֤ן עָלַם֙ דִּֽי־לָ֣א יֶעְדֵּ֔ה וּ⁠מַלְכוּתֵ֖⁠הּ דִּי־לָ֥א תִתְחַבַּֽל׃פ","wĕ⁠lé֨⁠ḣ yĕhi֤yb şá̌lĕtán֙ wi⁠yqá֣r ẇ⁠malĕk֔ẇ wĕ⁠kò֣l ʻaֽmĕmayá̇֗⁠ʼ ʼumayá֛̇⁠ʼ wĕ⁠lişá̇̌nayá֖̇⁠ʼ lé֣⁠ḣ yipĕlĕẖ֑ẇn şá̌lĕtáné֞⁠ḣ şá̌lĕtá֤n ʻálam֙ diֽ̇y-lá֣ʼ yeʻĕdé̇֔h ẇ⁠malĕkẇţé֖⁠ḣ di̇y-lá֥ʼ ţiţĕẖabȧֽl׃p"],[7,15,"אֶתְכְּרִיַּ֥ת רוּחִ֛⁠י אֲנָ֥ה דָנִיֵּ֖אל בְּ⁠ג֣וֹא נִדְנֶ֑ה וְ⁠חֶזְוֵ֥י רֵאשִׁ֖⁠י יְבַהֲלֻנַּֽ⁠נִי׃","ʼeţĕkĕ̇riyȧ֥ţ rẇẖi֛⁠y ʼàná֥h dániyé֖̇ʼl bĕ̇⁠g֣wòʼ nidĕne֑h wĕ⁠ẖezĕwé֥y réʼşǐ֖⁠y yĕbahàlunȧֽ⁠niy׃"],[7,16,"קִרְבֵ֗ת עַל־חַד֙ מִן־קָ֣אֲמַיָּ֔⁠א וְ⁠יַצִּיבָ֥א אֶבְעֵֽא־מִנֵּ֖⁠הּ עַֽל־כָּל־דְּנָ֑ה וַ⁠אֲמַר־לִ֕⁠י וּ⁠פְשַׁ֥ר מִלַּיָּ֖⁠א יְהוֹדְעִנַּֽ⁠נִי׃","qirĕbé֗ţ ʻal-ẖad֙ min-qá֣ʼàmayá̇֔⁠ʼ wĕ⁠yaẕi̇ybá֥ʼ ʼebĕʻéֽʼ-miné֖̇⁠ḣ ʻaֽl-ká̇l-dĕ̇ná֑h wa⁠ʼàmar-li֕⁠y ẇ⁠pĕşǎ֥r milȧyá֖̇⁠ʼ yĕhwòdĕʻinȧֽ⁠niy׃"],[7,17,"אִלֵּין֙ חֵיוָתָ֣⁠א רַבְרְבָתָ֔⁠א דִּ֥י אִנִּ֖ין אַרְבַּ֑ע אַרְבְּעָ֥ה מַלְכִ֖ין יְקוּמ֥וּן מִן־אַרְעָֽ⁠א׃","ʼilé̇yn֙ ẖéywáţá֣⁠ʼ rabĕrĕbáţá֔⁠ʼ di֥̇y ʼini֖̇yn ʼarĕbȧ֑ʻ ʼarĕbĕ̇ʻá֥h malĕki֖yn yĕqẇm֥ẇn min-ʼarĕʻáֽ⁠ʼ׃"],[7,18,"וִֽ⁠יקַבְּלוּן֙ מַלְכוּתָ֔⁠א קַדִּישֵׁ֖י עֶלְיוֹנִ֑ין וְ⁠יַחְסְנ֤וּן מַלְכוּתָ⁠א֙ עַֽד־עָ֣לְמָ֔⁠א וְ⁠עַ֖ד עָלַ֥ם עָלְמַיָּֽ⁠א׃","wiֽ⁠yqabĕ̇lẇn֙ malĕkẇţá֔⁠ʼ qadi̇yşé֖̌y ʻelĕywòni֑yn wĕ⁠yaẖĕsĕn֤ẇn malĕkẇţá⁠ʼ֙ ʻֽad-ʻá֣lĕmá֔⁠ʼ wĕ⁠ʻa֖d ʻála֥m ʻálĕmayáֽ̇⁠ʼ׃"],[7,19,"אֱדַ֗יִן צְבִית֙ לְ⁠יַצָּבָ֔א עַל־חֵֽיוְתָ⁠א֙ רְבִיעָ֣יְתָ֔⁠א דִּֽי־הֲוָ֥ת שָֽׁנְיָ֖ה מִן־כל⁠הון דְּחִילָ֣ה יַתִּ֗ירָה שני⁠ה דִּֽי־פַרְזֶל֙ וְ⁠טִפְרַ֣י⁠הּ דִּֽי־נְחָ֔שׁ אָֽכְלָ֣ה מַדֲּקָ֔ה וּ⁠שְׁאָרָ֖⁠א בְּ⁠רַגְלַ֥י⁠הּ רָֽפְסָֽה׃","ʼèda֗yin ẕĕbiyţ֙ lĕ⁠yaẕá̇bá֔ʼ ʻal-ẖéֽywĕţá⁠ʼ֙ rĕbiyʻá֣yĕţá֔⁠ʼ diֽ̇y-hàwá֥ţ şáֽ̌nĕyá֖h min-kl⁠hwn dĕ̇ẖiylá֣h yaţi̇֗yráh şny⁠h diֽ̇y-parĕzel֙ wĕ⁠tipĕra֣y⁠ḣ diֽ̇y-nĕẖá֔ş̌ ʼáֽkĕlá֣h madà̇qá֔h ẇ⁠şĕ̌ʼárá֖⁠ʼ bĕ̇⁠ragĕla֥y⁠ḣ ráֽpĕsáֽh׃"],[7,20,"וְ⁠עַל־קַרְנַיָּ֤⁠א עֲשַׂר֙ דִּ֣י בְ⁠רֵאשַׁ֔⁠הּ וְ⁠אָחֳרִי֙ דִּ֣י סִלְקַ֔ת ו⁠נפלו מִן־קדמי⁠ה תְּלָ֑ת וְ⁠קַרְנָ֨⁠א דִכֵּ֜ן וְ⁠עַיְנִ֣ין לַ֗⁠הּ וְ⁠פֻם֙ מְמַלִּ֣ל רַבְרְבָ֔ן וְ⁠חֶזְוַ֖⁠הּ רַ֥ב מִן־חַבְרָתַֽ⁠הּ׃","wĕ⁠ʻal-qarĕnayá֤̇⁠ʼ ʻàşâr֙ di֣̇y bĕ⁠réʼşǎ֔⁠ḣ wĕ⁠ʼáẖoriy֙ di֣̇y silĕqa֔ţ w⁠nplw min-qdmy⁠h ţĕ̇lá֑ţ wĕ⁠qarĕná֨⁠ʼ diké̇֜n wĕ⁠ʻayĕni֣yn la֗⁠ḣ wĕ⁠pum֙ mĕmali֣̇l rabĕrĕbá֔n wĕ⁠ẖezĕwa֖⁠ḣ ra֥b min-ẖabĕráţaֽ⁠ḣ׃"],[7,21,"חָזֵ֣ה הֲוֵ֔ית וְ⁠קַרְנָ֣⁠א דִכֵּ֔ן עָבְדָ֥ה קְרָ֖ב עִם־קַדִּישִׁ֑ין וְ⁠יָכְלָ֖ה לְ⁠הֽוֹן׃","ẖázé֣h hàwé֔yţ wĕ⁠qarĕná֣⁠ʼ diké̇֔n ʻábĕdá֥h qĕrá֖b ʻim-qadi̇yşǐ֑yn wĕ⁠yákĕlá֖h lĕ⁠hֽwòn׃"],[7,22,"עַ֣ד דִּֽי־אֲתָ֗ה עַתִּיק֙ יֽוֹמַיָּ֔⁠א וְ⁠דִינָ֣⁠א יְהִ֔ב לְ⁠קַדִּישֵׁ֖י עֶלְיוֹנִ֑ין וְ⁠זִמְנָ֣⁠א מְטָ֔ה וּ⁠מַלְכוּתָ֖⁠א הֶחֱסִ֥נוּ קַדִּישִֽׁין׃","ʻa֣d diֽ̇y-ʼàţá֗h ʻaţi̇yq֙ yֽwòmayá̇֔⁠ʼ wĕ⁠diyná֣⁠ʼ yĕhi֔b lĕ⁠qadi̇yşé֖̌y ʻelĕywòni֑yn wĕ⁠zimĕná֣⁠ʼ mĕtá֔h ẇ⁠malĕkẇţá֖⁠ʼ heẖèsi֥nẇ qadi̇yşǐֽyn׃"],[7,23,"כֵּן֮ אֲמַר֒ חֵֽיוְתָ⁠א֙ רְבִיעָ֣יְתָ֔⁠א מַלְכ֤וּ רביעי⁠א תֶּהֱוֵ֣א בְ⁠אַרְעָ֔⁠א דִּ֥י תִשְׁנֵ֖א מִן־כָּל־מַלְכְוָתָ֑⁠א וְ⁠תֵאכֻל֙ כָּל־אַרְעָ֔⁠א וּ⁠תְדוּשִׁנַּ֖⁠הּ וְ⁠תַדְּקִנַּֽ⁠הּ׃","ké̇n֮ ʼàmar֒ ẖéֽywĕţá⁠ʼ֙ rĕbiyʻá֣yĕţá֔⁠ʼ malĕk֤ẇ rbyʻy⁠ʼ ţėhèwé֣ʼ bĕ⁠ʼarĕʻá֔⁠ʼ di֥̇y ţişĕ̌né֖ʼ min-ká̇l-malĕkĕwáţá֑⁠ʼ wĕ⁠ţéʼkul֙ ká̇l-ʼarĕʻá֔⁠ʼ ẇ⁠ţĕdẇşǐnȧ֖⁠ḣ wĕ⁠ţadĕ̇qinȧֽ⁠ḣ׃"],[7,24,"וְ⁠קַרְנַיָּ֣⁠א עֲשַׂ֔ר מִנַּ⁠הּ֙ מַלְכוּתָ֔⁠ה עַשְׂרָ֥ה מַלְכִ֖ין יְקֻמ֑וּן וְ⁠אָחֳרָ֞ן יְק֣וּם אַחֲרֵי⁠ה֗וֹן וְ⁠ה֤וּא יִשְׁנֵא֙ מִן־קַדְמָיֵ֔⁠א וּ⁠תְלָתָ֥ה מַלְכִ֖ין יְהַשְׁפִּֽל׃","wĕ⁠qarĕnayá֣̇⁠ʼ ʻàşâ֔r minȧ⁠ḣ֙ malĕkẇţá֔⁠h ʻaşĕ̂rá֥h malĕki֖yn yĕqum֑ẇn wĕ⁠ʼáẖorá֞n yĕq֣ẇm ʼaẖàréy⁠h֗wòn wĕ⁠h֤ẇʼ yişĕ̌néʼ֙ min-qadĕmáyé֔⁠ʼ ẇ⁠ţĕláţá֥h malĕki֖yn yĕhaşĕ̌piֽ̇l׃"],[7,25,"וּ⁠מִלִּ֗ין לְ⁠צַ֤ד עלי⁠א יְמַלִּ֔ל וּ⁠לְ⁠קַדִּישֵׁ֥י עֶלְיוֹנִ֖ין יְבַלֵּ֑א וְ⁠יִסְבַּ֗ר לְ⁠הַשְׁנָיָה֙ זִמְנִ֣ין וְ⁠דָ֔ת וְ⁠יִתְיַהֲב֣וּן בִּ⁠ידֵ֔⁠הּ עַד־עִדָּ֥ן וְ⁠עִדָּנִ֖ין וּ⁠פְלַ֥ג עִדָּֽן׃","ẇ⁠mili̇֗yn lĕ⁠ẕa֤d ʻly⁠ʼ yĕmali̇֔l ẇ⁠lĕ⁠qadi̇yşé֥̌y ʻelĕywòni֖yn yĕbalé֑̇ʼ wĕ⁠yisĕbȧ֗r lĕ⁠haşĕ̌náyáh֙ zimĕni֣yn wĕ⁠dá֔ţ wĕ⁠yiţĕyahàb֣ẇn bi̇⁠ydé֔⁠ḣ ʻad-ʻidá֥̇n wĕ⁠ʻidá̇ni֖yn ẇ⁠pĕla֥g ʻidáֽ̇n׃"],[7,26,"וְ⁠דִינָ֖⁠א יִתִּ֑ב וְ⁠שָׁלְטָנֵ֣⁠הּ יְהַעְדּ֔וֹן לְ⁠הַשְׁמָדָ֥ה וּ⁠לְ⁠הוֹבָדָ֖ה עַד־סוֹפָֽ⁠א׃","wĕ⁠diyná֖⁠ʼ yiţi֑̇b wĕ⁠şá̌lĕtáné֣⁠ḣ yĕhaʻĕḋ֔wòn lĕ⁠haşĕ̌mádá֥h ẇ⁠lĕ⁠hwòbádá֖h ʻad-swòpáֽ⁠ʼ׃"],[7,27,"וּ⁠מַלְכוּתָ֨⁠ה וְ⁠שָׁלְטָנָ֜⁠א וּ⁠רְבוּתָ֗⁠א דִּ֚י מַלְכְוָת֙ תְּח֣וֹת כָּל־שְׁמַיָּ֔⁠א יְהִיבַ֕ת לְ⁠עַ֖ם קַדִּישֵׁ֣י עֶלְיוֹנִ֑ין מַלְכוּתֵ⁠הּ֙ מַלְכ֣וּת עָלַ֔ם וְ⁠כֹל֙ שָׁלְטָ֣נַיָּ֔⁠א לֵ֥⁠הּ יִפְלְח֖וּן וְ⁠יִֽשְׁתַּמְּעֽוּן׃","ẇ⁠malĕkẇţá֨⁠h wĕ⁠şá̌lĕtáná֜⁠ʼ ẇ⁠rĕbẇţá֗⁠ʼ di֚̇y malĕkĕwáţ֙ ţĕ̇ẖ֣wòţ ká̇l-şĕ̌mayá̇֔⁠ʼ yĕhiyba֕ţ lĕ⁠ʻa֖m qadi̇yşé֣̌y ʻelĕywòni֑yn malĕkẇţé⁠ḣ֙ malĕk֣ẇţ ʻála֔m wĕ⁠kòl֙ şá̌lĕtá֣nayá̇֔⁠ʼ lé֥⁠ḣ yipĕlĕẖ֖ẇn wĕ⁠yiֽşĕ̌ţȧmĕ̇ʻֽẇn׃"],[7,28,"עַד־כָּ֖ה סוֹפָ֣⁠א דִֽי־מִלְּתָ֑⁠א אֲנָ֨ה דָֽנִיֵּ֜אל שַׂגִּ֣יא ׀ רַעְיוֹנַ֣⁠י יְבַהֲלֻנַּ֗⁠נִי וְ⁠זִיוַ⁠י֙ יִשְׁתַּנּ֣וֹן עֲלַ֔⁠י וּ⁠מִלְּתָ֖⁠א בְּ⁠לִבִּ֥⁠י נִטְרֵֽת׃פ","ʻad-ká֖̇h swòpá֣⁠ʼ diֽy-milĕ̇ţá֑⁠ʼ ʼàná֨h dáֽniyé̇֜ʼl şâgi֣̇yʼ ׀ raʻĕywòna֣⁠y yĕbahàlunȧ֗⁠niy wĕ⁠ziywa⁠y֙ yişĕ̌ţȧṅ֣wòn ʻàla֔⁠y ẇ⁠milĕ̇ţá֖⁠ʼ bĕ̇⁠libi֥̇⁠y nitĕréֽţ׃p"],[8,1,"בִּ⁠שְׁנַ֣ת שָׁל֔וֹשׁ לְ⁠מַלְכ֖וּת בֵּלְאשַׁצַּ֣ר הַ⁠מֶּ֑לֶךְ חָז֞וֹן נִרְאָ֤ה אֵלַ⁠י֙ אֲנִ֣י דָנִיֵּ֔אל אַחֲרֵ֛י הַ⁠נִּרְאָ֥ה אֵלַ֖⁠י בַּ⁠תְּחִלָּֽה׃","bi̇⁠şĕ̌na֣ţ şá̌l֔wòş̌ lĕ⁠malĕk֖ẇţ bé̇lĕʼşǎẕȧ֣r ha⁠mė֑lekĕ ẖáz֞wòn nirĕʼá֤h ʼéla⁠y֙ ʼàni֣y dániyé̇֔ʼl ʼaẖàré֛y ha⁠ni̇rĕʼá֥h ʼéla֖⁠y bȧ⁠ţĕ̇ẖiláֽ̇h׃"],[8,2,"וָֽ⁠אֶרְאֶה֮ בֶּ⁠חָזוֹן֒ וַ⁠יְהִי֙ בִּ⁠רְאֹתִ֔⁠י וַ⁠אֲנִי֙ בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֔ה אֲשֶׁ֖ר בְּ⁠עֵילָ֣ם הַ⁠מְּדִינָ֑ה וָ⁠אֶרְאֶה֙ בֶּֽ⁠חָז֔וֹן וַ⁠אֲנִ֥י הָיִ֖יתִי עַל־אוּבַ֥ל אוּלָֽי׃","wáֽ⁠ʼerĕʼeh֮ bė⁠ẖázwòn֒ wa⁠yĕhiy֙ bi̇⁠rĕʼòţi֔⁠y wa⁠ʼàniy֙ bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֔h ʼàşě֖r bĕ̇⁠ʻéylá֣m ha⁠mĕ̇diyná֑h wá⁠ʼerĕʼeh֙ bėֽ⁠ẖáz֔wòn wa⁠ʼàni֥y háyi֖yţiy ʻal-ʼẇba֥l ʼẇláֽy׃"],[8,3,"וָ⁠אֶשָּׂ֤א עֵינַ⁠י֙ וָ⁠אֶרְאֶ֔ה וְ⁠הִנֵּ֣ה ׀ אַ֣יִל אֶחָ֗ד עֹמֵ֛ד לִ⁠פְנֵ֥י הָ⁠אֻבָ֖ל וְ⁠ל֣⁠וֹ קְרָנָ֑יִם וְ⁠הַ⁠קְּרָנַ֣יִם גְּבֹה֗וֹת וְ⁠הָ⁠אַחַת֙ גְּבֹהָ֣ה מִן־הַ⁠שֵּׁנִ֔ית וְ⁠הַ֨⁠גְּבֹהָ֔ה עֹלָ֖ה בָּ⁠אַחֲרֹנָֽה׃","wá⁠ʼeşá֤̇̂ʼ ʻéyna⁠y֙ wá⁠ʼerĕʼe֔h wĕ⁠hiné֣̇h ׀ ʼa֣yil ʼeẖá֗d ʻòmé֛d li⁠pĕné֥y há⁠ʼubá֖l wĕ⁠l֣⁠wò qĕráná֑yim wĕ⁠ha⁠qĕ̇rána֣yim gĕ̇bòh֗wòţ wĕ⁠há⁠ʼaẖaţ֙ gĕ̇bòhá֣h min-ha⁠şé̇̌ni֔yţ wĕ⁠ha֨⁠gĕ̇bòhá֔h ʻòlá֖h bá̇⁠ʼaẖàrònáֽh׃"],[8,4,"רָאִ֣יתִי אֶת־הָ⁠אַ֡יִל מְנַגֵּחַ֩ יָ֨מָּ⁠ה וְ⁠צָפ֜וֹנָ⁠ה וָ⁠נֶ֗גְבָּ⁠ה וְ⁠כָל־חַיּוֹת֙ לֹֽא־יַֽעַמְד֣וּ לְ⁠פָנָ֔י⁠ו וְ⁠אֵ֥ין מַצִּ֖יל מִ⁠יָּד֑⁠וֹ וְ⁠עָשָׂ֥ה כִ⁠רְצֹנ֖⁠וֹ וְ⁠הִגְדִּֽיל׃","ráʼi֣yţiy ʼeţ-há⁠ʼa֡yil mĕnagé̇ẖa֩ yá֨má̇⁠h wĕ⁠ẕáp֜wòná⁠h wá⁠ne֗gĕbá̇⁠h wĕ⁠kál-ẖaẏwòţ֙ lòֽʼ-yaֽʻamĕd֣ẇ lĕ⁠páná֔y⁠w wĕ⁠ʼé֥yn maẕi֖̇yl mi⁠yá̇d֑⁠wò wĕ⁠ʻáşá֥̂h ki⁠rĕẕòn֖⁠wò wĕ⁠higĕdiֽ̇yl׃"],[8,5,"וַ⁠אֲנִ֣י ׀ הָיִ֣יתִי מֵבִ֗ין וְ⁠הִנֵּ֤ה צְפִיר־הָֽ⁠עִזִּים֙ בָּ֤א מִן־הַֽ⁠מַּעֲרָב֙ עַל־פְּנֵ֣י כָל־הָ⁠אָ֔רֶץ וְ⁠אֵ֥ין נוֹגֵ֖עַ בָּ⁠אָ֑רֶץ וְ⁠הַ֨⁠צָּפִ֔יר קֶ֥רֶן חָז֖וּת בֵּ֥ין עֵינָֽי⁠ו׃","wa⁠ʼàni֣y ׀ háyi֣yţiy mébi֗yn wĕ⁠hiné֤̇h ẕĕpiyr-háֽ⁠ʻizi̇ym֙ bá֤̇ʼ min-haֽ⁠mȧʻàráb֙ ʻal-pĕ̇né֣y kál-há⁠ʼá֔reẕ wĕ⁠ʼé֥yn nwògé֖ʻa bá̇⁠ʼá֑reẕ wĕ⁠ha֨⁠ẕá̇pi֔yr qe֥ren ẖáz֖ẇţ bé֥̇yn ʻéynáֽy⁠w׃"],[8,6,"וַ⁠יָּבֹ֗א עַד־הָ⁠אַ֨יִל֙ בַּ֣עַל הַ⁠קְּרָנַ֔יִם אֲשֶׁ֣ר רָאִ֔יתִי עֹמֵ֖ד לִ⁠פְנֵ֣י הָ⁠אֻבָ֑ל וַ⁠יָּ֥רָץ אֵלָ֖י⁠ו בַּ⁠חֲמַ֥ת כֹּחֽ⁠וֹ׃","wa⁠yá̇bò֗ʼ ʻad-há⁠ʼa֨yil֙ bȧ֣ʻal ha⁠qĕ̇rána֔yim ʼàşě֣r ráʼi֔yţiy ʻòmé֖d li⁠pĕné֣y há⁠ʼubá֑l wa⁠yá֥̇ráẕ ʼélá֖y⁠w bȧ⁠ẖàma֥ţ kò̇ẖֽ⁠wò׃"],[8,7,"וּ⁠רְאִיתִ֞י⁠ו מַגִּ֣יעַ ׀ אֵ֣צֶל הָ⁠אַ֗יִל וַ⁠יִּתְמַרְמַ֤ר אֵלָי⁠ו֙ וַ⁠יַּ֣ךְ אֶת־הָ⁠אַ֔יִל וַ⁠יְשַׁבֵּר֙ אֶת־שְׁתֵּ֣י קְרָנָ֔י⁠ו וְ⁠לֹא־הָ֥יָה כֹ֛חַ בָּ⁠אַ֖יִל לַ⁠עֲמֹ֣ד לְ⁠פָנָ֑י⁠ו וַ⁠יַּשְׁלִיכֵ֤⁠הוּ אַ֨רְצָ⁠ה֙ וַֽ⁠יִּרְמְסֵ֔⁠הוּ וְ⁠לֹא־הָיָ֥ה מַצִּ֛יל לָ⁠אַ֖יִל מִ⁠יָּדֽ⁠וֹ׃","ẇ⁠rĕʼiyţi֞y⁠w magi֣̇yʻa ׀ ʼé֣ẕel há⁠ʼa֗yil wa⁠yi̇ţĕmarĕma֤r ʼéláy⁠w֙ wa⁠yȧ֣kĕ ʼeţ-há⁠ʼa֔yil wa⁠yĕşǎbé̇r֙ ʼeţ-şĕ̌ţé֣̇y qĕráná֔y⁠w wĕ⁠lòʼ-há֥yáh kò֛ẖa bá̇⁠ʼa֖yil la⁠ʻàmò֣d lĕ⁠páná֑y⁠w wa⁠yȧşĕ̌liyké֤⁠hẇ ʼa֨rĕẕá⁠h֙ waֽ⁠yi̇rĕmĕsé֔⁠hẇ wĕ⁠lòʼ-háyá֥h maẕi֛̇yl lá⁠ʼa֖yil mi⁠yá̇dֽ⁠wò׃"],[8,8,"וּ⁠צְפִ֥יר הָ⁠עִזִּ֖ים הִגְדִּ֣יל עַד־מְאֹ֑ד וּ⁠כְ⁠עָצְמ֗⁠וֹ נִשְׁבְּרָה֙ הַ⁠קֶּ֣רֶן הַ⁠גְּדוֹלָ֔ה וַֽ⁠תַּעֲלֶ֜נָה חָז֤וּת אַרְבַּע֙ תַּחְתֶּ֔י⁠הָ לְ⁠אַרְבַּ֖ע רוּח֥וֹת הַ⁠שָּׁמָֽיִם׃","ẇ⁠ẕĕpi֥yr há⁠ʻizi֖̇ym higĕdi֣̇yl ʻad-mĕʼò֑d ẇ⁠kĕ⁠ʻáẕĕm֗⁠wò nişĕ̌bĕ̇ráh֙ ha⁠qė֣ren ha⁠gĕ̇dwòlá֔h waֽ⁠ţȧʻàle֜náh ẖáz֤ẇţ ʼarĕbȧʻ֙ ţȧẖĕţė֔y⁠há lĕ⁠ʼarĕbȧ֖ʻ rẇẖ֥wòţ ha⁠şá̇̌máֽyim׃"],[8,9,"וּ⁠מִן־הָ⁠אַחַ֣ת מֵ⁠הֶ֔ם יָצָ֥א קֶֽרֶן־אַחַ֖ת מִ⁠צְּעִירָ֑ה וַ⁠תִּגְדַּל־יֶ֛תֶר אֶל־הַ⁠נֶּ֥גֶב וְ⁠אֶל־הַ⁠מִּזְרָ֖ח וְ⁠אֶל־הַ⁠צֶּֽבִי׃","ẇ⁠min-há⁠ʼaẖa֣ţ mé⁠he֔m yáẕá֥ʼ qeֽren-ʼaẖa֖ţ mi⁠ẕĕ̇ʻiyrá֑h wa⁠ţi̇gĕdȧl-ye֛ţer ʼel-ha⁠nė֥geb wĕ⁠ʼel-ha⁠mi̇zĕrá֖ẖ wĕ⁠ʼel-ha⁠ẕėֽbiy׃"],[8,10,"וַ⁠תִּגְדַּ֖ל עַד־צְבָ֣א הַ⁠שָּׁמָ֑יִם וַ⁠תַּפֵּ֥ל אַ֛רְצָ⁠ה מִן־הַ⁠צָּבָ֥א וּ⁠מִן־הַ⁠כּוֹכָבִ֖ים וַֽ⁠תִּרְמְסֵֽ⁠ם׃","wa⁠ţi̇gĕdȧ֖l ʻad-ẕĕbá֣ʼ ha⁠şá̇̌má֑yim wa⁠ţȧpé֥̇l ʼa֛rĕẕá⁠h min-ha⁠ẕá̇bá֥ʼ ẇ⁠min-ha⁠k̇wòkábi֖ym waֽ⁠ţi̇rĕmĕséֽ⁠m׃"],[8,11,"וְ⁠עַ֥ד שַֽׂר־הַ⁠צָּבָ֖א הִגְדִּ֑יל וּ⁠מִמֶּ֨⁠נּוּ֙ הרים הַ⁠תָּמִ֔יד וְ⁠הֻשְׁלַ֖ךְ מְכ֥וֹן מִקְדָּשֽׁ⁠וֹ׃","wĕ⁠ʻa֥d şâֽr-ha⁠ẕá̇bá֖ʼ higĕdi֑̇yl ẇ⁠mimė֨⁠ṅẇ֙ hrym ha⁠ţá̇mi֔yd wĕ⁠huşĕ̌la֖kĕ mĕk֥wòn miqĕdá̇şֽ̌⁠wò׃"],[8,12,"וְ⁠צָבָ֛א תִּנָּתֵ֥ן עַל־הַ⁠תָּמִ֖יד בְּ⁠פָ֑שַׁע וְ⁠תַשְׁלֵ֤ךְ אֱמֶת֙ אַ֔רְצָ⁠ה וְ⁠עָשְׂתָ֖ה וְ⁠הִצְלִֽיחָה׃","wĕ⁠ẕábá֛ʼ ţi̇ná̇ţé֥n ʻal-ha⁠ţá̇mi֖yd bĕ̇⁠pá֑şǎʻ wĕ⁠ţaşĕ̌lé֤kĕ ʼèmeţ֙ ʼa֔rĕẕá⁠h wĕ⁠ʻáşĕ̂ţá֖h wĕ⁠hiẕĕliֽyẖáh׃"],[8,13,"וָ⁠אֶשְׁמְעָ֥⁠ה אֶֽחָד־קָד֖וֹשׁ מְדַבֵּ֑ר וַ⁠יֹּאמֶר֩ אֶחָ֨ד קָד֜וֹשׁ לַ⁠פַּֽלְמוֹנִ֣י הַֽ⁠מְדַבֵּ֗ר עַד־מָתַ֞י הֶ⁠חָז֤וֹן הַ⁠תָּמִיד֙ וְ⁠הַ⁠פֶּ֣שַׁע שֹׁמֵ֔ם תֵּ֛ת וְ⁠קֹ֥דֶשׁ וְ⁠צָבָ֖א מִרְמָֽס׃","wá⁠ʼeşĕ̌mĕʻá֥⁠h ʼeֽẖád-qád֖wòş̌ mĕdabé֑̇r wa⁠yò̇ʼmer֩ ʼeẖá֨d qád֜wòş̌ la⁠pȧֽlĕmwòni֣y haֽ⁠mĕdabé̇֗r ʻad-máţa֞y he⁠ẖáz֤wòn ha⁠ţá̇miyd֙ wĕ⁠ha⁠pė֣şǎʻ şò̌mé֔m ţé֛̇ţ wĕ⁠qò֥deş̌ wĕ⁠ẕábá֖ʼ mirĕmáֽs׃"],[8,14,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י עַ֚ד עֶ֣רֶב בֹּ֔קֶר אַלְפַּ֖יִם וּ⁠שְׁלֹ֣שׁ מֵא֑וֹת וְ⁠נִצְדַּ֖ק קֹֽדֶשׁ׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y ʻa֚d ʻe֣reb bò̇֔qer ʼalĕpȧ֖yim ẇ⁠şĕ̌lò֣ş̌ méʼ֑wòţ wĕ⁠niẕĕdȧ֖q qòֽdeş̌׃"],[8,15,"וַ⁠יְהִ֗י בִּ⁠רְאֹתִ֛⁠י אֲנִ֥י דָנִיֵּ֖אל אֶת־הֶ⁠חָז֑וֹן וָ⁠אֲבַקְשָׁ֣⁠ה בִינָ֔ה וְ⁠הִנֵּ֛ה עֹמֵ֥ד לְ⁠נֶגְדִּ֖⁠י כְּ⁠מַרְאֵה־גָֽבֶר׃","wa⁠yĕhi֗y bi̇⁠rĕʼòţi֛⁠y ʼàni֥y dániyé֖̇ʼl ʼeţ-he⁠ẖáz֑wòn wá⁠ʼàbaqĕşá֣̌⁠h biyná֔h wĕ⁠hiné֛̇h ʻòmé֥d lĕ⁠negĕdi֖̇⁠y kĕ̇⁠marĕʼéh-gáֽber׃"],[8,16,"וָ⁠אֶשְׁמַ֥ע קוֹל־אָדָ֖ם בֵּ֣ין אוּלָ֑י וַ⁠יִּקְרָא֙ וַ⁠יֹּאמַ֔ר גַּבְרִיאֵ֕ל הָבֵ֥ן לְ⁠הַלָּ֖ז אֶת־הַ⁠מַּרְאֶֽה׃","wá⁠ʼeşĕ̌ma֥ʻ qwòl-ʼádá֖m bé֣̇yn ʼẇlá֑y wa⁠yi̇qĕráʼ֙ wa⁠yò̇ʼma֔r gȧbĕriyʼé֕l hábé֥n lĕ⁠halá֖̇z ʼeţ-ha⁠mȧrĕʼeֽh׃"],[8,17,"וַ⁠יָּבֹא֙ אֵ֣צֶל עָמְדִ֔⁠י וּ⁠בְ⁠בֹא֣⁠וֹ נִבְעַ֔תִּי וָ⁠אֶפְּלָ֖⁠ה עַל־פָּנָ֑⁠י וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ הָבֵ֣ן בֶּן־אָדָ֔ם כִּ֖י לְ⁠עֶת־קֵ֥ץ הֶ⁠חָזֽוֹן׃","wa⁠yá̇bòʼ֙ ʼé֣ẕel ʻámĕdi֔⁠y ẇ⁠bĕ⁠bòʼ֣⁠wò nibĕʻa֔ţi̇y wá⁠ʼepĕ̇lá֖⁠h ʻal-pá̇ná֑⁠y wa⁠yò֤̇ʼmer ʼéla⁠y֙ hábé֣n bėn-ʼádá֔m ki֖̇y lĕ⁠ʻeţ-qé֥ẕ he⁠ẖázֽwòn׃"],[8,18,"וּ⁠בְ⁠דַבְּר֣⁠וֹ עִמִּ֔⁠י נִרְדַּ֥מְתִּי עַל־פָּנַ֖⁠י אָ֑רְצָ⁠ה וַ⁠יִּ֨גַּע־בִּ֔⁠י וַ⁠יַּֽעֲמִידֵ֖⁠נִי עַל־עָמְדִֽ⁠י׃","ẇ⁠bĕ⁠dabĕ̇r֣⁠wò ʻimi̇֔⁠y nirĕdȧ֥mĕţi̇y ʻal-pá̇na֖⁠y ʼá֑rĕẕá⁠h wa⁠yi̇֨gȧʻ-bi̇֔⁠y wa⁠yȧֽʻàmiydé֖⁠niy ʻal-ʻámĕdiֽ⁠y׃"],[8,19,"וַ⁠יֹּ֨אמֶר֙ הִנְ⁠נִ֣י מוֹדִֽיעֲ⁠ךָ֔ אֵ֥ת אֲשֶׁר־יִהְיֶ֖ה בְּ⁠אַחֲרִ֣ית הַ⁠זָּ֑עַם כִּ֖י לְ⁠מוֹעֵ֥ד קֵֽץ׃","wa⁠yò̇֨ʼmer֙ hinĕ⁠ni֣y mwòdiֽyʻà⁠ká֔ ʼé֥ţ ʼàşěr-yihĕye֖h bĕ̇⁠ʼaẖàri֣yţ ha⁠zá֑̇ʻam ki֖̇y lĕ⁠mwòʻé֥d qéֽẕ׃"],[8,20,"הָ⁠אַ֥יִל אֲשֶׁר־רָאִ֖יתָ בַּ֣עַל הַ⁠קְּרָנָ֑יִם מַלְכֵ֖י מָדַ֥י וּ⁠פָרָֽס׃","há⁠ʼa֥yil ʼàşěr-ráʼi֖yţá bȧ֣ʻal ha⁠qĕ̇ráná֑yim malĕké֖y máda֥y ẇ⁠páráֽs׃"],[8,21,"וְ⁠הַ⁠צָּפִ֥יר הַ⁠שָּׂעִ֖יר מֶ֣לֶךְ יָוָ֑ן וְ⁠הַ⁠קֶּ֤רֶן הַ⁠גְּדוֹלָה֙ אֲשֶׁ֣ר בֵּין־עֵינָ֔י⁠ו ה֖וּא הַ⁠מֶּ֥לֶךְ הָ⁠רִאשֽׁוֹן׃","wĕ⁠ha⁠ẕá̇pi֥yr ha⁠şá̇̂ʻi֖yr me֣lekĕ yáwá֑n wĕ⁠ha⁠qė֤ren ha⁠gĕ̇dwòláh֙ ʼàşě֣r bé̇yn-ʻéyná֔y⁠w h֖ẇʼ ha⁠mė֥lekĕ há⁠riʼşֽ̌wòn׃"],[8,22,"וְ⁠הַ֨⁠נִּשְׁבֶּ֔רֶת וַ⁠תַּֽעֲמֹ֥דְנָה אַרְבַּ֖ע תַּחְתֶּ֑י⁠הָ אַרְבַּ֧ע מַלְכֻי֛וֹת מִ⁠גּ֥וֹי יַעֲמֹ֖דְנָה וְ⁠לֹ֥א בְ⁠כֹחֽ⁠וֹ׃","wĕ⁠ha֨⁠ni̇şĕ̌bė֔reţ wa⁠ţȧֽʻàmò֥dĕnáh ʼarĕbȧ֖ʻ ţȧẖĕţė֑y⁠há ʼarĕbȧ֧ʻ malĕkuy֛wòţ mi⁠ġ֥wòy yaʻàmò֖dĕnáh wĕ⁠lò֥ʼ bĕ⁠kòẖֽ⁠wò׃"],[8,23,"וּֽ⁠בְ⁠אַחֲרִית֙ מַלְכוּתָ֔⁠ם כְּ⁠הָתֵ֖ם הַ⁠פֹּשְׁעִ֑ים יַעֲמֹ֛ד מֶ֥לֶךְ עַז־פָּנִ֖ים וּ⁠מֵבִ֥ין חִידֽוֹת׃","ẇֽ⁠bĕ⁠ʼaẖàriyţ֙ malĕkẇţá֔⁠m kĕ̇⁠háţé֖m ha⁠pò̇şĕ̌ʻi֑ym yaʻàmò֛d me֥lekĕ ʻaz-pá̇ni֖ym ẇ⁠mébi֥yn ẖiydֽwòţ׃"],[8,24,"וְ⁠עָצַ֤ם כֹּח⁠וֹ֙ וְ⁠לֹ֣א בְ⁠כֹח֔⁠וֹ וְ⁠נִפְלָא֥וֹת יַשְׁחִ֖ית וְ⁠הִצְלִ֣יחַ וְ⁠עָשָׂ֑ה וְ⁠הִשְׁחִ֥ית עֲצוּמִ֖ים וְ⁠עַם־קְדֹשִֽׁים׃","wĕ⁠ʻáẕa֤m kò̇ẖ⁠wò֙ wĕ⁠lò֣ʼ bĕ⁠kòẖ֔⁠wò wĕ⁠nipĕláʼ֥wòţ yaşĕ̌ẖi֖yţ wĕ⁠hiẕĕli֣yẖa wĕ⁠ʻáşá֑̂h wĕ⁠hişĕ̌ẖi֥yţ ʻàẕẇmi֖ym wĕ⁠ʻam-qĕdòşǐֽym׃"],[8,25,"וְ⁠עַל־שִׂכְל֗⁠וֹ וְ⁠הִצְלִ֤יחַ מִרְמָה֙ בְּ⁠יָד֔⁠וֹ וּ⁠בִ⁠לְבָב֣⁠וֹ יַגְדִּ֔יל וּ⁠בְ⁠שַׁלְוָ֖ה יַשְׁחִ֣ית רַבִּ֑ים וְ⁠עַ֤ל־שַׂר־שָׂרִים֙ יַעֲמֹ֔ד וּ⁠בְ⁠אֶ֥פֶס יָ֖ד יִשָּׁבֵֽר׃","wĕ⁠ʻal-şîkĕl֗⁠wò wĕ⁠hiẕĕli֤yẖa mirĕmáh֙ bĕ̇⁠yád֔⁠wò ẇ⁠bi⁠lĕbáb֣⁠wò yagĕdi̇֔yl ẇ⁠bĕ⁠şǎlĕwá֖h yaşĕ̌ẖi֣yţ rabi֑̇ym wĕ⁠ʻa֤l-şâr-şá̂riym֙ yaʻàmò֔d ẇ⁠bĕ⁠ʼe֥pes yá֖d yişá̇̌béֽr׃"],[8,26,"וּ⁠מַרְאֵ֨ה הָ⁠עֶ֧רֶב וְ⁠הַ⁠בֹּ֛קֶר אֲשֶׁ֥ר נֶאֱמַ֖ר אֱמֶ֣ת ה֑וּא וְ⁠אַתָּה֙ סְתֹ֣ם הֶֽ⁠חָז֔וֹן כִּ֖י לְ⁠יָמִ֥ים רַבִּֽים׃","ẇ⁠marĕʼé֨h há⁠ʻe֧reb wĕ⁠ha⁠bò֛̇qer ʼàşě֥r neʼèma֖r ʼème֣ţ h֑ẇʼ wĕ⁠ʼaţá̇h֙ sĕţò֣m heֽ⁠ẖáz֔wòn ki֖̇y lĕ⁠yámi֥ym rabiֽ̇ym׃"],[8,27,"וַ⁠אֲנִ֣י דָנִיֵּ֗אל נִהְיֵ֤יתִי וְ⁠נֶֽחֱלֵ֨יתִי֙ יָמִ֔ים וָ⁠אָק֕וּם וָ⁠אֶֽעֱשֶׂ֖ה אֶת־מְלֶ֣אכֶת הַ⁠מֶּ֑לֶךְ וָ⁠אֶשְׁתּוֹמֵ֥ם עַל־הַ⁠מַּרְאֶ֖ה וְ⁠אֵ֥ין מֵבִֽין׃פ","wa⁠ʼàni֣y dániyé̇֗ʼl nihĕyé֤yţiy wĕ⁠nֽeẖèlé֨yţiy֙ yámi֔ym wá⁠ʼáq֕ẇm wá⁠ʼeֽʻèşê֖h ʼeţ-mĕle֣ʼkeţ ha⁠mė֑lekĕ wá⁠ʼeşĕ̌ţ̇wòmé֥m ʻal-ha⁠mȧrĕʼe֖h wĕ⁠ʼé֥yn mébiֽyn׃p"],[9,1,"בִּ⁠שְׁנַ֣ת אַחַ֗ת לְ⁠דָרְיָ֛וֶשׁ בֶּן־אֲחַשְׁוֵר֖וֹשׁ מִ⁠זֶּ֣רַע מָדָ֑י אֲשֶׁ֣ר הָמְלַ֔ךְ עַ֖ל מַלְכ֥וּת כַּשְׂדִּֽים׃","bi̇⁠şĕ̌na֣ţ ʼaẖa֗ţ lĕ⁠dárĕyá֛weş̌ bėn-ʼàẖaşĕ̌wér֖wòş̌ mi⁠zė֣raʻ mádá֑y ʼàşě֣r hámĕla֔kĕ ʻa֖l malĕk֥ẇţ kȧşĕ̂diֽ̇ym׃"],[9,2,"בִּ⁠שְׁנַ֤ת אַחַת֙ לְ⁠מָלְכ֔⁠וֹ אֲנִי֙ דָּֽנִיֵּ֔אל בִּינֹ֖תִי בַּ⁠סְּפָרִ֑ים מִסְפַּ֣ר הַ⁠שָּׁנִ֗ים אֲשֶׁ֨ר הָיָ֤ה דְבַר־יְהוָה֙ אֶל־יִרְמִיָ֣ה הַ⁠נָּבִ֔יא לְ⁠מַלֹּ֛אות לְ⁠חָרְב֥וֹת יְרוּשָׁלִַ֖ם שִׁבְעִ֥ים שָׁנָֽה׃","bi̇⁠şĕ̌na֤ţ ʼaẖaţ֙ lĕ⁠málĕk֔⁠wò ʼàniy֙ dáֽ̇niyé̇֔ʼl bi̇ynò֖ţiy bȧ⁠sĕ̇pári֑ym misĕpȧ֣r ha⁠şá̇̌ni֗ym ʼàşě֨r háyá֤h dĕbar-yĕhwáh֙ ʼel-yirĕmiyá֣h ha⁠ná̇bi֔yʼ lĕ⁠malò֛̇ʼwţ lĕ⁠ẖárĕb֥wòţ yĕrẇşá̌lia֖m şǐbĕʻi֥ym şá̌náֽh׃"],[9,3,"וָ⁠אֶתְּנָ֣⁠ה אֶת־פָּנַ֗⁠י אֶל־אֲדֹנָ⁠י֙ הָֽ⁠אֱלֹהִ֔ים לְ⁠בַקֵּ֥שׁ תְּפִלָּ֖ה וְ⁠תַחֲנוּנִ֑ים בְּ⁠צ֖וֹם וְ⁠שַׂ֥ק וָ⁠אֵֽפֶר׃","wá⁠ʼeţĕ̇ná֣⁠h ʼeţ-pá̇na֗⁠y ʼel-ʼàdòná⁠y֙ háֽ⁠ʼèlòhi֔ym lĕ⁠baqé֥̇ş̌ ţĕ̇pilá֖̇h wĕ⁠ţaẖànẇni֑ym bĕ̇⁠ẕ֖wòm wĕ⁠şâ֥q wá⁠ʼéֽper׃"],[9,4,"וָֽ⁠אֶתְפַּֽלְלָ֛⁠ה לַ⁠יהוָ֥ה אֱלֹהַ֖⁠י וָ⁠אֶתְוַדֶּ֑ה וָ⁠אֹֽמְרָ֗⁠ה אָנָּ֤א אֲדֹנָ⁠י֙ הָ⁠אֵ֤ל הַ⁠גָּדוֹל֙ וְ⁠הַ⁠נּוֹרָ֔א שֹׁמֵ֤ר הַ⁠בְּרִית֙ וְֽ⁠הַ⁠חֶ֔סֶד לְ⁠אֹהֲבָ֖י⁠ו וּ⁠לְ⁠שֹׁמְרֵ֥י מִצְוֺתָֽי⁠ו׃","wáֽ⁠ʼeţĕpȧֽlĕlá֛⁠h la⁠yhwá֥h ʼèlòha֖⁠y wá⁠ʼeţĕwadė֑h wá⁠ʼòֽmĕrá֗⁠h ʼáná֤̇ʼ ʼàdòná⁠y֙ há⁠ʼé֤l ha⁠gá̇dwòl֙ wĕ⁠ha⁠ṅwòrá֔ʼ şò̌mé֤r ha⁠bĕ̇riyţ֙ wĕֽ⁠ha⁠ẖe֔sed lĕ⁠ʼòhàbá֖y⁠w ẇ⁠lĕ⁠şò̌mĕré֥y miẕĕwֺţáֽy⁠w׃"],[9,5,"חָטָ֥אנוּ וְ⁠עָוִ֖ינוּ ו⁠הרשענו וּ⁠מָרָ֑דְנוּ וְ⁠ס֥וֹר מִ⁠מִּצְוֺתֶ֖⁠ךָ וּ⁠מִ⁠מִּשְׁפָּטֶֽי⁠ךָ׃","ẖátá֥ʼnẇ wĕ⁠ʻáwi֖ynẇ w⁠hrşʻnw ẇ⁠márá֑dĕnẇ wĕ⁠s֥wòr mi⁠mi̇ẕĕwֺţe֖⁠ká ẇ⁠mi⁠mi̇şĕ̌pá̇teֽy⁠ká׃"],[9,6,"וְ⁠לֹ֤א שָׁמַ֨עְנוּ֙ אֶל־עֲבָדֶ֣י⁠ךָ הַ⁠נְּבִיאִ֔ים אֲשֶׁ֤ר דִּבְּרוּ֙ בְּ⁠שִׁמְ⁠ךָ֔ אֶל־מְלָכֵ֥י⁠נוּ שָׂרֵ֖י⁠נוּ וַ⁠אֲבֹתֵ֑י⁠נוּ וְ⁠אֶ֖ל כָּל־עַ֥ם הָ⁠אָֽרֶץ׃","wĕ⁠lò֤ʼ şá̌ma֨ʻĕnẇ֙ ʼel-ʻàbáde֣y⁠ká ha⁠nĕ̇biyʼi֔ym ʼàşě֤r di̇bĕ̇rẇ֙ bĕ̇⁠şǐmĕ⁠ká֔ ʼel-mĕláké֥y⁠nẇ şá̂ré֖y⁠nẇ wa⁠ʼàbòţé֑y⁠nẇ wĕ⁠ʼe֖l ká̇l-ʻa֥m há⁠ʼáֽreẕ׃"],[9,7,"לְ⁠ךָ֤ אֲדֹנָ⁠י֙ הַ⁠צְּדָקָ֔ה וְ⁠לָ֛⁠נוּ בֹּ֥שֶׁת הַ⁠פָּנִ֖ים כַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה לְ⁠אִ֤ישׁ יְהוּדָה֙ וּ⁠לְ⁠יוֹשְׁבֵ֣י יְרֽוּשָׁלִַ֔ם וּֽ⁠לְ⁠כָל־יִשְׂרָאֵ֞ל הַ⁠קְּרֹבִ֣ים וְ⁠הָ⁠רְחֹקִ֗ים בְּ⁠כָל־הָֽ⁠אֲרָצוֹת֙ אֲשֶׁ֣ר הִדַּחְתָּ֣⁠ם שָׁ֔ם בְּ⁠מַעֲלָ֖⁠ם אֲשֶׁ֥ר מָֽעֲלוּ־בָֽ⁠ךְ׃","lĕ⁠ká֤ ʼàdòná⁠y֙ ha⁠ẕĕ̇dáqá֔h wĕ⁠lá֛⁠nẇ bò֥̇şěţ ha⁠pá̇ni֖ym kȧ⁠ẏ֣wòm ha⁠zė֑h lĕ⁠ʼi֤yş̌ yĕhẇdáh֙ ẇ⁠lĕ⁠ywòşĕ̌bé֣y yĕrֽẇşá̌lia֔m ẇֽ⁠lĕ⁠kál-yişĕ̂ráʼé֞l ha⁠qĕ̇ròbi֣ym wĕ⁠há⁠rĕẖòqi֗ym bĕ̇⁠kál-háֽ⁠ʼàráẕwòţ֙ ʼàşě֣r hidȧẖĕţá֣̇⁠m şá̌֔m bĕ̇⁠maʻàlá֖⁠m ʼàşě֥r máֽʻàlẇ-báֽ⁠kĕ׃"],[9,8,"יְהוָ֗ה לָ֚⁠נוּ בֹּ֣שֶׁת הַ⁠פָּנִ֔ים לִ⁠מְלָכֵ֥י⁠נוּ לְ⁠שָׂרֵ֖י⁠נוּ וְ⁠לַ⁠אֲבֹתֵ֑י⁠נוּ אֲשֶׁ֥ר חָטָ֖אנוּ לָֽ⁠ךְ׃","yĕhwá֗h lá֚⁠nẇ bò֣̇şěţ ha⁠pá̇ni֔ym li⁠mĕláké֥y⁠nẇ lĕ⁠şá̂ré֖y⁠nẇ wĕ⁠la⁠ʼàbòţé֑y⁠nẇ ʼàşě֥r ẖátá֖ʼnẇ láֽ⁠kĕ׃"],[9,9,"לַֽ⁠אדֹנָ֣⁠י אֱלֹהֵ֔י⁠נוּ הָ⁠רַחֲמִ֖ים וְ⁠הַ⁠סְּלִח֑וֹת כִּ֥י מָרַ֖דְנוּ בּֽ⁠וֹ׃","laֽ⁠ʼdòná֣⁠y ʼèlòhé֔y⁠nẇ há⁠raẖàmi֖ym wĕ⁠ha⁠sĕ̇liẖ֑wòţ ki֥̇y mára֖dĕnẇ ḃֽ⁠wò׃"],[9,10,"וְ⁠לֹ֣א שָׁמַ֔עְנוּ בְּ⁠ק֖וֹל יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ לָ⁠לֶ֤כֶת בְּ⁠תֽוֹרֹתָי⁠ו֙ אֲשֶׁ֣ר נָתַ֣ן לְ⁠פָנֵ֔י⁠נוּ בְּ⁠יַ֖ד עֲבָדָ֥י⁠ו הַ⁠נְּבִיאִֽים׃","wĕ⁠lò֣ʼ şá̌ma֔ʻĕnẇ bĕ̇⁠q֖wòl yĕhwá֣h ʼèlòhé֑y⁠nẇ lá⁠le֤keţ bĕ̇⁠ţֽwòròţáy⁠w֙ ʼàşě֣r náţa֣n lĕ⁠páné֔y⁠nẇ bĕ̇⁠ya֖d ʻàbádá֥y⁠w ha⁠nĕ̇biyʼiֽym׃"],[9,11,"וְ⁠כָל־יִשְׂרָאֵ֗ל עָֽבְרוּ֙ אֶת־תּ֣וֹרָתֶ֔⁠ךָ וְ⁠ס֕וֹר לְ⁠בִלְתִּ֖י שְׁמ֣וֹעַ בְּ⁠קֹלֶ֑⁠ךָ וַ⁠תִּתַּ֨ךְ עָלֵ֜י⁠נוּ הָ⁠אָלָ֣ה וְ⁠הַ⁠שְּׁבֻעָ֗ה אֲשֶׁ֤ר כְּתוּבָה֙ בְּ⁠תוֹרַת֙ מֹשֶׁ֣ה עֶֽבֶד־הָֽ⁠אֱלֹהִ֔ים כִּ֥י חָטָ֖אנוּ לֽ⁠וֹ׃","wĕ⁠kál-yişĕ̂ráʼé֗l ʻáֽbĕrẇ֙ ʼeţ-ţ֣̇wòráţe֔⁠ká wĕ⁠s֕wòr lĕ⁠bilĕţi֖̇y şĕ̌m֣wòʻa bĕ̇⁠qòle֑⁠ká wa⁠ţi̇ţȧ֨kĕ ʻálé֜y⁠nẇ há⁠ʼálá֣h wĕ⁠ha⁠şĕ̇̌buʻá֗h ʼàşě֤r kĕ̇ţẇbáh֙ bĕ̇⁠ţwòraţ֙ mòşě֣h ʻeֽbed-háֽ⁠ʼèlòhi֔ym ki֥̇y ẖátá֖ʼnẇ lֽ⁠wò׃"],[9,12,"וַ⁠יָּ֜קֶם אֶת־דברי⁠ו ׀ אֲשֶׁר־דִּבֶּ֣ר עָלֵ֗י⁠נוּ וְ⁠עַ֤ל שֹֽׁפְטֵ֨י⁠נוּ֙ אֲשֶׁ֣ר שְׁפָט֔וּ⁠נוּ לְ⁠הָבִ֥יא עָלֵ֖י⁠נוּ רָעָ֣ה גְדֹלָ֑ה אֲשֶׁ֣ר לֹֽא־נֶעֶשְׂתָ֗ה תַּ֚חַת כָּל־הַ⁠שָּׁמַ֔יִם כַּ⁠אֲשֶׁ֥ר נֶעֶשְׂתָ֖ה בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yá̇֜qem ʼeţ-dbry⁠w ׀ ʼàşěr-di̇bė֣r ʻálé֗y⁠nẇ wĕ⁠ʻa֤l şòֽ̌pĕté֨y⁠nẇ֙ ʼàşě֣r şĕ̌pát֔ẇ⁠nẇ lĕ⁠hábi֥yʼ ʻálé֖y⁠nẇ ráʻá֣h gĕdòlá֑h ʼàşě֣r lòֽʼ-neʻeşĕ̂ţá֗h ţȧ֚ẖaţ ká̇l-ha⁠şá̇̌ma֔yim kȧ⁠ʼàşě֥r neʻeşĕ̂ţá֖h bi̇⁠yrẇşá̌liáֽm׃"],[9,13,"כַּ⁠אֲשֶׁ֤ר כָּתוּב֙ בְּ⁠תוֹרַ֣ת מֹשֶׁ֔ה אֵ֛ת כָּל־הָ⁠רָעָ֥ה הַ⁠זֹּ֖את בָּ֣אָה עָלֵ֑י⁠נוּ וְ⁠לֹֽא־חִלִּ֜ינוּ אֶת־פְּנֵ֣י ׀ יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ לָ⁠שׁוּב֙ מֵֽ⁠עֲוֺנֵ֔⁠נוּ וּ⁠לְ⁠הַשְׂכִּ֖יל בַּ⁠אֲמִתֶּֽ⁠ךָ׃","kȧ⁠ʼàşě֤r ká̇ţẇb֙ bĕ̇⁠ţwòra֣ţ mòşě֔h ʼé֛ţ ká̇l-há⁠ráʻá֥h ha⁠zò֖̇ʼţ bá֣̇ʼáh ʻálé֑y⁠nẇ wĕ⁠lòֽʼ-ẖili̇֜ynẇ ʼeţ-pĕ̇né֣y ׀ yĕhwá֣h ʼèlòhé֗y⁠nẇ lá⁠ş̌ẇb֙ méֽ⁠ʻàwֺné֔⁠nẇ ẇ⁠lĕ⁠haşĕ̂ki֖̇yl bȧ⁠ʼàmiţėֽ⁠ká׃"],[9,14,"וַ⁠יִּשְׁקֹ֤ד יְהוָה֙ עַל־הָ֣⁠רָעָ֔ה וַ⁠יְבִיאֶ֖⁠הָ עָלֵ֑י⁠נוּ כִּֽי־צַדִּ֞יק יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ עַל־כָּל־מַֽעֲשָׂי⁠ו֙ אֲשֶׁ֣ר עָשָׂ֔ה וְ⁠לֹ֥א שָׁמַ֖עְנוּ בְּ⁠קֹלֽ⁠וֹ׃","wa⁠yi̇şĕ̌qò֤d yĕhwáh֙ ʻal-há֣⁠ráʻá֔h wa⁠yĕbiyʼe֖⁠há ʻálé֑y⁠nẇ kiֽ̇y-ẕadi̇֞yq yĕhwá֣h ʼèlòhé֗y⁠nẇ ʻal-ká̇l-maֽʻàşá̂y⁠w֙ ʼàşě֣r ʻáşá̂֔h wĕ⁠lò֥ʼ şá̌ma֖ʻĕnẇ bĕ̇⁠qòlֽ⁠wò׃"],[9,15,"וְ⁠עַתָּ֣ה ׀ אֲדֹנָ֣⁠י אֱלֹהֵ֗י⁠נוּ אֲשֶׁר֩ הוֹצֵ֨אתָ אֶֽת־עַמְּ⁠ךָ֜ מֵ⁠אֶ֤רֶץ מִצְרַ֨יִם֙ בְּ⁠יָ֣ד חֲזָקָ֔ה וַ⁠תַּֽעַשׂ־לְ⁠ךָ֥ שֵׁ֖ם כַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה חָטָ֖אנוּ רָשָֽׁעְנוּ׃","wĕ⁠ʻaţá֣̇h ׀ ʼàdòná֣⁠y ʼèlòhé֗y⁠nẇ ʼàşěr֩ hwòẕé֨ʼţá ʼeֽţ-ʻamĕ̇⁠ká֜ mé⁠ʼe֤reẕ miẕĕra֨yim֙ bĕ̇⁠yá֣d ẖàzáqá֔h wa⁠ţȧֽʻaş̂-lĕ⁠ká֥ şé֖̌m kȧ⁠ẏ֣wòm ha⁠zė֑h ẖátá֖ʼnẇ ráşáֽ̌ʻĕnẇ׃"],[9,16,"אֲדֹנָ֗⁠י כְּ⁠כָל־צִדְקֹתֶ֨⁠ךָ֙ יָֽשָׁב־נָ֤א אַפְּ⁠ךָ֙ וַ⁠חֲמָ֣תְ⁠ךָ֔ מֵ⁠עִֽירְ⁠ךָ֥ יְרוּשָׁלִַ֖ם הַר־קָדְשֶׁ֑⁠ךָ כִּ֤י בַ⁠חֲטָאֵ֨י⁠נוּ֙ וּ⁠בַ⁠עֲוֺנ֣וֹת אֲבֹתֵ֔י⁠נוּ יְרוּשָׁלִַ֧ם וְ⁠עַמְּ⁠ךָ֛ לְ⁠חֶרְפָּ֖ה לְ⁠כָל־סְבִיבֹתֵֽי⁠נוּ׃","ʼàdòná֗⁠y kĕ̇⁠kál-ẕidĕqòţe֨⁠ká֙ yáֽşá̌b-ná֤ʼ ʼapĕ̇⁠ká֙ wa⁠ẖàmá֣ţĕ⁠ká֔ mé⁠ʻiֽyrĕ⁠ká֥ yĕrẇşá̌lia֖m har-qádĕşě֑⁠ká ki֤̇y ba⁠ẖàtáʼé֨y⁠nẇ֙ ẇ⁠ba⁠ʻàwֺn֣wòţ ʼàbòţé֔y⁠nẇ yĕrẇşá̌lia֧m wĕ⁠ʻamĕ̇⁠ká֛ lĕ⁠ẖerĕpá֖̇h lĕ⁠kál-sĕbiybòţéֽy⁠nẇ׃"],[9,17,"וְ⁠עַתָּ֣ה ׀ שְׁמַ֣ע אֱלֹהֵ֗י⁠נוּ אֶל־תְּפִלַּ֤ת עַבְדְּ⁠ךָ֙ וְ⁠אֶל־תַּ֣חֲנוּנָ֔י⁠ו וְ⁠הָאֵ֣ר פָּנֶ֔י⁠ךָ עַל־מִקְדָּשְׁ⁠ךָ֖ הַ⁠שָּׁמֵ֑ם לְמַ֖עַן אֲדֹנָֽ⁠י׃","wĕ⁠ʻaţá֣̇h ׀ şĕ̌ma֣ʻ ʼèlòhé֗y⁠nẇ ʼel-ţĕ̇pilȧ֤ţ ʻabĕdĕ̇⁠ká֙ wĕ⁠ʼel-ţȧ֣ẖànẇná֔y⁠w wĕ⁠háʼé֣r pá̇ne֔y⁠ká ʻal-miqĕdá̇şĕ̌⁠ká֖ ha⁠şá̇̌mé֑m lĕma֖ʻan ʼàdònáֽ⁠y׃"],[9,18,"הַטֵּ֨ה אֱלֹהַ֥⁠י ׀ אָזְנְ⁠ךָ֮ וּֽ⁠שֲׁמָע֒ פקח⁠ה עֵינֶ֗י⁠ךָ וּ⁠רְאֵה֙ שֹֽׁמְמֹתֵ֔י⁠נוּ וְ⁠הָ⁠עִ֕יר אֲשֶׁר־נִקְרָ֥א שִׁמְ⁠ךָ֖ עָלֶ֑י⁠הָ כִּ֣י ׀ לֹ֣א עַל־צִדְקֹתֵ֗י⁠נוּ אֲנַ֨חְנוּ מַפִּילִ֤ים תַּחֲנוּנֵ֨י⁠נוּ֙ לְ⁠פָנֶ֔י⁠ךָ כִּ֖י עַל־רַחֲמֶ֥י⁠ךָ הָ⁠רַבִּֽים׃","haté̇֨h ʼèlòha֥⁠y ׀ ʼázĕnĕ⁠ká֮ ẇֽ⁠şà̌máʻ֒ pqẖ⁠h ʻéyne֗y⁠ká ẇ⁠rĕʼéh֙ şòֽ̌mĕmòţé֔y⁠nẇ wĕ⁠há⁠ʻi֕yr ʼàşěr-niqĕrá֥ʼ şǐmĕ⁠ká֖ ʻále֑y⁠há ki֣̇y ׀ lò֣ʼ ʻal-ẕidĕqòţé֗y⁠nẇ ʼàna֨ẖĕnẇ mapi̇yli֤ym ţȧẖànẇné֨y⁠nẇ֙ lĕ⁠páne֔y⁠ká ki֖̇y ʻal-raẖàme֥y⁠ká há⁠rabiֽ̇ym׃"],[9,19,"אֲדֹנָ֤⁠י ׀ שְׁמָ֨עָ⁠ה֙ אֲדֹנָ֣⁠י ׀ סְלָ֔חָ⁠ה אֲדֹנָ֛⁠י הַֽקֲשִׁ֥יבָ⁠ה וַ⁠עֲשֵׂ֖ה אַל־תְּאַחַ֑ר לְמַֽעֲנְ⁠ךָ֣ אֱלֹהַ֔⁠י כִּֽי־שִׁמְ⁠ךָ֣ נִקְרָ֔א עַל־עִירְ⁠ךָ֖ וְ⁠עַל־עַמֶּֽ⁠ךָ׃","ʼàdòná֤⁠y ׀ şĕ̌má֨ʻá⁠h֙ ʼàdòná֣⁠y ׀ sĕlá֔ẖá⁠h ʼàdòná֛⁠y haֽqàşǐ֥ybá⁠h wa⁠ʻàşé֖̂h ʼal-ţĕ̇ʼaẖa֑r lĕmaֽʻànĕ⁠ká֣ ʼèlòha֔⁠y kiֽ̇y-şǐmĕ⁠ká֣ niqĕrá֔ʼ ʻal-ʻiyrĕ⁠ká֖ wĕ⁠ʻal-ʻamėֽ⁠ká׃"],[9,20,"וְ⁠ע֨וֹד אֲנִ֤י מְדַבֵּר֙ וּ⁠מִתְפַּלֵּ֔ל וּ⁠מִתְוַדֶּה֙ חַטָּאתִ֔⁠י וְ⁠חַטַּ֖את עַמִּ֣⁠י יִשְׂרָאֵ֑ל וּ⁠מַפִּ֣יל תְּחִנָּתִ֗⁠י לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹהַ֔⁠י עַ֖ל הַר־קֹ֥דֶשׁ אֱלֹהָֽ⁠י׃","wĕ⁠ʻ֨wòd ʼàni֤y mĕdabé̇r֙ ẇ⁠miţĕpȧlé̇֔l ẇ⁠miţĕwadėh֙ ẖatá̇ʼţi֔⁠y wĕ⁠ẖatȧ֖ʼţ ʻami֣̇⁠y yişĕ̂ráʼé֑l ẇ⁠mapi֣̇yl ţĕ̇ẖiná̇ţi֗⁠y li⁠pĕnéy֙ yĕhwá֣h ʼèlòha֔⁠y ʻa֖l har-qò֥deş̌ ʼèlòháֽ⁠y׃"],[9,21,"וְ⁠ע֛וֹד אֲנִ֥י מְדַבֵּ֖ר בַּ⁠תְּפִלָּ֑ה וְ⁠הָ⁠אִ֣ישׁ גַּבְרִיאֵ֡ל אֲשֶׁר֩ רָאִ֨יתִי בֶ⁠חָז֤וֹן בַּ⁠תְּחִלָּה֙ מֻעָ֣ף בִּ⁠יעָ֔ף נֹגֵ֣עַ אֵלַ֔⁠י כְּ⁠עֵ֖ת מִנְחַת־עָֽרֶב׃","wĕ⁠ʻ֛wòd ʼàni֥y mĕdabé֖̇r bȧ⁠ţĕ̇pilá֑̇h wĕ⁠há⁠ʼi֣yş̌ gȧbĕriyʼé֡l ʼàşěr֩ ráʼi֨yţiy be⁠ẖáz֤wòn bȧ⁠ţĕ̇ẖilá̇h֙ muʻá֣p bi̇⁠yʻá֔p nògé֣ʻa ʼéla֔⁠y kĕ̇⁠ʻé֖ţ minĕẖaţ-ʻáֽreb׃"],[9,22,"וַ⁠יָּ֖בֶן וַ⁠יְדַבֵּ֣ר עִמִּ֑⁠י וַ⁠יֹּאמַ֕ר דָּנִיֵּ֕אל עַתָּ֥ה יָצָ֖אתִי לְ⁠הַשְׂכִּילְ⁠ךָ֥ בִינָֽה׃","wa⁠yá֖̇ben wa⁠yĕdabé֣̇r ʻimi֑̇⁠y wa⁠yò̇ʼma֕r dá̇niyé̇֕ʼl ʻaţá֥̇h yáẕá֖ʼţiy lĕ⁠haşĕ̂ki̇ylĕ⁠ká֥ biynáֽh׃"],[9,23,"בִּ⁠תְחִלַּ֨ת תַּחֲנוּנֶ֜י⁠ךָ יָצָ֣א דָבָ֗ר וַ⁠אֲנִי֙ בָּ֣אתִי לְ⁠הַגִּ֔יד כִּ֥י חֲמוּד֖וֹת אָ֑תָּה וּ⁠בִין֙ בַּ⁠דָּבָ֔ר וְ⁠הָבֵ֖ן בַּ⁠מַּרְאֶֽה׃","bi̇⁠ţĕẖilȧ֨ţ ţȧẖànẇne֜y⁠ká yáẕá֣ʼ dábá֗r wa⁠ʼàniy֙ bá֣̇ʼţiy lĕ⁠hagi̇֔yd ki֥̇y ẖàmẇd֖wòţ ʼá֑ţá̇h ẇ⁠biyn֙ bȧ⁠dá̇bá֔r wĕ⁠hábé֖n bȧ⁠mȧrĕʼeֽh׃"],[9,24,"שָׁבֻעִ֨ים שִׁבְעִ֜ים נֶחְתַּ֥ךְ עַֽל־עַמְּ⁠ךָ֣ ׀ וְ⁠עַל־עִ֣יר קָדְשֶׁ֗⁠ךָ לְ⁠כַלֵּ֨א הַ⁠פֶּ֜שַׁע ו⁠ל⁠חתם חטאות וּ⁠לְ⁠כַפֵּ֣ר עָוֺ֔ן וּ⁠לְ⁠הָבִ֖יא צֶ֣דֶק עֹֽלָמִ֑ים וְ⁠לַ⁠חְתֹּם֙ חָז֣וֹן וְ⁠נָבִ֔יא וְ⁠לִ⁠מְשֹׁ֖חַ קֹ֥דֶשׁ קָֽדָשִֽׁים׃","şá̌buʻi֨ym şǐbĕʻi֜ym neẖĕţȧ֥kĕ ʻaֽl-ʻamĕ̇⁠ká֣ ׀ wĕ⁠ʻal-ʻi֣yr qádĕşě֗⁠ká lĕ⁠kalé̇֨ʼ ha⁠pė֜şǎʻ w⁠l⁠ẖţm ẖtʼwţ ẇ⁠lĕ⁠kapé֣̇r ʻáwֺ֔n ẇ⁠lĕ⁠hábi֖yʼ ẕe֣deq ʻòֽlámi֑ym wĕ⁠la⁠ẖĕţò̇m֙ ẖáz֣wòn wĕ⁠nábi֔yʼ wĕ⁠li⁠mĕşò֖̌ẖa qò֥deş̌ qáֽdáşǐֽym׃"],[9,25,"וְ⁠תֵדַ֨ע וְ⁠תַשְׂכֵּ֜ל מִן־מֹצָ֣א דָבָ֗ר לְ⁠הָשִׁיב֙ וְ⁠לִ⁠בְנ֤וֹת יְרֽוּשָׁלִַ֨ם֙ עַד־מָשִׁ֣יחַ נָגִ֔יד שָׁבֻעִ֖ים שִׁבְעָ֑ה וְ⁠שָׁבֻעִ֞ים שִׁשִּׁ֣ים וּ⁠שְׁנַ֗יִם תָּשׁוּב֙ וְ⁠נִבְנְתָה֙ רְח֣וֹב וְ⁠חָר֔וּץ וּ⁠בְ⁠צ֖וֹק הָ⁠עִתִּֽים׃","wĕ⁠ţéda֨ʻ wĕ⁠ţaşĕ̂ké̇֜l min-mòẕá֣ʼ dábá֗r lĕ⁠háşǐyb֙ wĕ⁠li⁠bĕn֤wòţ yĕrֽẇşá̌lia֨m֙ ʻad-máşǐ֣yẖa nági֔yd şá̌buʻi֖ym şǐbĕʻá֑h wĕ⁠şá̌buʻi֞ym şǐşi֣̇̌ym ẇ⁠şĕ̌na֗yim ţá̇ş̌ẇb֙ wĕ⁠nibĕnĕţáh֙ rĕẖ֣wòb wĕ⁠ẖár֔ẇẕ ẇ⁠bĕ⁠ẕ֖wòq há⁠ʻiţiֽ̇ym׃"],[9,26,"וְ⁠אַחֲרֵ֤י הַ⁠שָּׁבֻעִים֙ שִׁשִּׁ֣ים וּ⁠שְׁנַ֔יִם יִכָּרֵ֥ת מָשִׁ֖יחַ וְ⁠אֵ֣ין ל֑⁠וֹ וְ⁠הָ⁠עִ֨יר וְ⁠הַ⁠קֹּ֜דֶשׁ יַ֠שְׁחִית עַ֣ם נָגִ֤יד הַ⁠בָּא֙ וְ⁠קִצּ֣⁠וֹ בַ⁠שֶּׁ֔טֶף וְ⁠עַד֙ קֵ֣ץ מִלְחָמָ֔ה נֶחֱרֶ֖צֶת שֹׁמֵמֽוֹת׃","wĕ⁠ʼaẖàré֤y ha⁠şá̇̌buʻiym֙ şǐşi֣̇̌ym ẇ⁠şĕ̌na֔yim yiká̇ré֥ţ máşǐ֖yẖa wĕ⁠ʼé֣yn l֑⁠wò wĕ⁠há⁠ʻi֨yr wĕ⁠ha⁠qò̇֜deş̌ ya֠şĕ̌ẖiyţ ʻa֣m nági֤yd ha⁠bá̇ʼ֙ wĕ⁠qiẕ֣̇⁠wò ba⁠şė̌֔tep wĕ⁠ʻad֙ qé֣ẕ milĕẖámá֔h neẖère֖ẕeţ şò̌mémֽwòţ׃"],[9,27,"וְ⁠הִגְבִּ֥יר בְּרִ֛ית לָ⁠רַבִּ֖ים שָׁב֣וּעַ אֶחָ֑ד וַ⁠חֲצִ֨י הַ⁠שָּׁב֜וּעַ יַשְׁבִּ֣ית ׀ זֶ֣בַח וּ⁠מִנְחָ֗ה וְ⁠עַ֨ל כְּנַ֤ף שִׁקּוּצִים֙ מְשֹׁמֵ֔ם וְ⁠עַד־כָּלָה֙ וְ⁠נֶ֣חֱרָצָ֔ה תִּתַּ֖ךְ עַל־שֹׁמֵֽם׃פ","wĕ⁠higĕbi֥̇yr bĕ̇ri֛yţ lá⁠rabi֖̇ym şá̌b֣ẇʻa ʼeẖá֑d wa⁠ẖàẕi֨y ha⁠şá̇̌b֜ẇʻa yaşĕ̌bi֣̇yţ ׀ ze֣baẖ ẇ⁠minĕẖá֗h wĕ⁠ʻa֨l kĕ̇na֤p şǐq̇ẇẕiym֙ mĕşò̌mé֔m wĕ⁠ʻad-ká̇láh֙ wĕ⁠ne֣ẖèráẕá֔h ţi̇ţȧ֖kĕ ʻal-şò̌méֽm׃p"],[10,1,"בִּ⁠שְׁנַ֣ת שָׁל֗וֹשׁ לְ⁠כ֨וֹרֶשׁ֙ מֶ֣לֶךְ פָּרַ֔ס דָּבָר֙ נִגְלָ֣ה לְ⁠דָֽנִיֵּ֔אל אֲשֶׁר־נִקְרָ֥א שְׁמ֖⁠וֹ בֵּלְטְשַׁאצַּ֑ר וֶ⁠אֱמֶ֤ת הַ⁠דָּבָר֙ וְ⁠צָבָ֣א גָד֔וֹל וּ⁠בִין֙ אֶת־הַ⁠דָּבָ֔ר וּ⁠בִ֥ינָה ל֖⁠וֹ בַּ⁠מַּרְאֶֽה׃","bi̇⁠şĕ̌na֣ţ şá̌l֗wòş̌ lĕ⁠k֨wòreş̌֙ me֣lekĕ pá̇ra֔s dá̇bár֙ nigĕlá֣h lĕ⁠dáֽniyé̇֔ʼl ʼàşěr-niqĕrá֥ʼ şĕ̌m֖⁠wò bé̇lĕtĕşǎʼẕȧ֑r we⁠ʼème֤ţ ha⁠dá̇bár֙ wĕ⁠ẕábá֣ʼ gád֔wòl ẇ⁠biyn֙ ʼeţ-ha⁠dá̇bá֔r ẇ⁠bi֥ynáh l֖⁠wò bȧ⁠mȧrĕʼeֽh׃"],[10,2,"בַּ⁠יָּמִ֖ים הָ⁠הֵ֑ם אֲנִ֤י דָֽנִיֵּאל֙ הָיִ֣יתִי מִתְאַבֵּ֔ל שְׁלֹשָׁ֥ה שָׁבֻעִ֖ים יָמִֽים׃","bȧ⁠yá̇mi֖ym há⁠hé֑m ʼàni֤y dáֽniyé̇ʼl֙ háyi֣yţiy miţĕʼabé̇֔l şĕ̌lòşá֥̌h şá̌buʻi֖ym yámiֽym׃"],[10,3,"לֶ֣חֶם חֲמֻד֞וֹת לֹ֣א אָכַ֗לְתִּי וּ⁠בָשָׂ֥ר וָ⁠יַ֛יִן לֹא־בָ֥א אֶל־פִּ֖⁠י וְ⁠ס֣וֹךְ לֹא־סָ֑כְתִּי עַד־מְלֹ֕את שְׁלֹ֥שֶׁת שָׁבֻעִ֖ים יָמִֽים׃פ","le֣ẖem ẖàmud֞wòţ lò֣ʼ ʼáka֗lĕţi̇y ẇ⁠báşá֥̂r wá⁠ya֛yin lòʼ-bá֥ʼ ʼel-pi֖̇⁠y wĕ⁠s֣wòkĕ lòʼ-sá֑kĕţi̇y ʻad-mĕlò֕ʼţ şĕ̌lò֥şěţ şá̌buʻi֖ym yámiֽym׃p"],[10,4,"וּ⁠בְ⁠י֛וֹם עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֑וֹן וַ⁠אֲנִ֗י הָיִ֛יתִי עַ֣ל יַ֧ד הַ⁠נָּהָ֛ר הַ⁠גָּד֖וֹל ה֥וּא חִדָּֽקֶל׃","ẇ⁠bĕ⁠y֛wòm ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h la⁠ẖò֣deş̌ há⁠riʼş֑̌wòn wa⁠ʼàni֗y háyi֛yţiy ʻa֣l ya֧d ha⁠ná̇há֛r ha⁠gá̇d֖wòl h֥ẇʼ ẖidáֽ̇qel׃"],[10,5,"וָ⁠אֶשָּׂ֤א אֶת־עֵינַ⁠י֙ וָ⁠אֵ֔רֶא וְ⁠הִנֵּ֥ה אִישׁ־אֶחָ֖ד לָב֣וּשׁ בַּדִּ֑ים וּ⁠מָתְנָ֥י⁠ו חֲגֻרִ֖ים בְּ⁠כֶ֥תֶם אוּפָֽז׃","wá⁠ʼeşá֤̇̂ʼ ʼeţ-ʻéyna⁠y֙ wá⁠ʼé֔reʼ wĕ⁠hiné֥̇h ʼiyş̌-ʼeẖá֖d láb֣ẇş̌ bȧdi֑̇ym ẇ⁠máţĕná֥y⁠w ẖàguri֖ym bĕ̇⁠ke֥ţem ʼẇpáֽz׃"],[10,6,"וּ⁠גְוִיָּת֣⁠וֹ כְ⁠תַרְשִׁ֗ישׁ וּ⁠פָנָ֞י⁠ו כְּ⁠מַרְאֵ֤ה בָרָק֙ וְ⁠עֵינָי⁠ו֙ כְּ⁠לַפִּ֣ידֵי אֵ֔שׁ וּ⁠זְרֹֽעֹתָי⁠ו֙ וּ⁠מַרְגְּלֹתָ֔י⁠ו כְּ⁠עֵ֖ין נְחֹ֣שֶׁת קָלָ֑ל וְ⁠ק֥וֹל דְּבָרָ֖י⁠ו כְּ⁠ק֥וֹל הָמֽוֹן׃","ẇ⁠gĕwiyá̇ţ֣⁠wò kĕ⁠ţarĕşǐ֗yş̌ ẇ⁠páná֞y⁠w kĕ̇⁠marĕʼé֤h báráq֙ wĕ⁠ʻéynáy⁠w֙ kĕ̇⁠lapi֣̇ydéy ʼé֔ş̌ ẇ⁠zĕròֽʻòţáy⁠w֙ ẇ⁠marĕgĕ̇lòţá֔y⁠w kĕ̇⁠ʻé֖yn nĕẖò֣şěţ qálá֑l wĕ⁠q֥wòl dĕ̇bárá֖y⁠w kĕ̇⁠q֥wòl hámֽwòn׃"],[10,7,"וְ⁠רָאִיתִי֩ אֲנִ֨י דָנִיֵּ֤אל לְ⁠בַדִּ⁠י֙ אֶת־הַ⁠מַּרְאָ֔ה וְ⁠הָ⁠אֲנָשִׁים֙ אֲשֶׁ֣ר הָי֣וּ עִמִּ֔⁠י לֹ֥א רָא֖וּ אֶת־הַ⁠מַּרְאָ֑ה אֲבָ֗ל חֲרָדָ֤ה גְדֹלָה֙ נָפְלָ֣ה עֲלֵי⁠הֶ֔ם וַֽ⁠יִּבְרְח֖וּ בְּ⁠הֵחָבֵֽא׃","wĕ⁠ráʼiyţiy֩ ʼàni֨y dániyé֤̇ʼl lĕ⁠badi̇⁠y֙ ʼeţ-ha⁠mȧrĕʼá֔h wĕ⁠há⁠ʼànáşǐym֙ ʼàşě֣r háy֣ẇ ʻimi̇֔⁠y lò֥ʼ ráʼ֖ẇ ʼeţ-ha⁠mȧrĕʼá֑h ʼàbá֗l ẖàrádá֤h gĕdòláh֙ nápĕlá֣h ʻàléy⁠he֔m waֽ⁠yi̇bĕrĕẖ֖ẇ bĕ̇⁠héẖábéֽʼ׃"],[10,8,"וַ⁠אֲנִי֙ נִשְׁאַ֣רְתִּי לְ⁠בַדִּ֔⁠י וָֽ⁠אֶרְאֶ֗ה אֶת־הַ⁠מַּרְאָ֤ה הַ⁠גְּדֹלָה֙ הַ⁠זֹּ֔את וְ⁠לֹ֥א נִשְׁאַר־בִּ֖⁠י כֹּ֑ח וְ⁠הוֹדִ֗⁠י נֶהְפַּ֤ךְ עָלַ⁠י֙ לְ⁠מַשְׁחִ֔ית וְ⁠לֹ֥א עָצַ֖רְתִּי כֹּֽחַ׃","wa⁠ʼàniy֙ nişĕ̌ʼa֣rĕţi̇y lĕ⁠badi̇֔⁠y wáֽ⁠ʼerĕʼe֗h ʼeţ-ha⁠mȧrĕʼá֤h ha⁠gĕ̇dòláh֙ ha⁠zò̇֔ʼţ wĕ⁠lò֥ʼ nişĕ̌ʼar-bi֖̇⁠y kò֑̇ẖ wĕ⁠hwòdi֗⁠y nehĕpȧ֤kĕ ʻála⁠y֙ lĕ⁠maşĕ̌ẖi֔yţ wĕ⁠lò֥ʼ ʻáẕa֖rĕţi̇y kòֽ̇ẖa׃"],[10,9,"וָ⁠אֶשְׁמַ֖ע אֶת־ק֣וֹל דְּבָרָ֑י⁠ו וּ⁠כְ⁠שָׁמְעִ⁠י֙ אֶת־ק֣וֹל דְּבָרָ֔י⁠ו וַ⁠אֲנִ֗י הָיִ֛יתִי נִרְדָּ֥ם עַל־פָּנַ֖⁠י וּ⁠פָנַ֥⁠י אָֽרְצָ⁠ה׃","wá⁠ʼeşĕ̌ma֖ʻ ʼeţ-q֣wòl dĕ̇bárá֑y⁠w ẇ⁠kĕ⁠şá̌mĕʻi⁠y֙ ʼeţ-q֣wòl dĕ̇bárá֔y⁠w wa⁠ʼàni֗y háyi֛yţiy nirĕdá֥̇m ʻal-pá̇na֖⁠y ẇ⁠pána֥⁠y ʼáֽrĕẕá⁠h׃"],[10,10,"וְ⁠הִנֵּה־יָ֖ד נָ֣גְעָה בִּ֑⁠י וַ⁠תְּנִיעֵ֥⁠נִי עַל־בִּרְכַּ֖⁠י וְ⁠כַפּ֥וֹת יָדָֽ⁠י׃","wĕ⁠hiné̇h-yá֖d ná֣gĕʻáh bi֑̇⁠y wa⁠ţĕ̇niyʻé֥⁠niy ʻal-bi̇rĕkȧ֖⁠y wĕ⁠kaṗ֥wòţ yádáֽ⁠y׃"],[10,11,"וַ⁠יֹּ֣אמֶר אֵלַ֡⁠י דָּנִיֵּ֣אל אִישׁ־חֲ֠מֻדוֹת הָבֵ֨ן בַּ⁠דְּבָרִ֜ים אֲשֶׁר֩ אָנֹכִ֨י דֹבֵ֤ר אֵלֶ֨י⁠ךָ֙ וַ⁠עֲמֹ֣ד עַל־עָמְדֶ֔⁠ךָ כִּ֥י עַתָּ֖ה שֻׁלַּ֣חְתִּי אֵלֶ֑י⁠ךָ וּ⁠בְ⁠דַבְּר֥⁠וֹ עִמִּ֛⁠י אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה עָמַ֥דְתִּי מַרְעִֽיד׃","wa⁠yò֣̇ʼmer ʼéla֡⁠y dá̇niyé֣̇ʼl ʼiyş̌-ẖà֠mudwòţ hábé֨n bȧ⁠dĕ̇bári֜ym ʼàşěr֩ ʼánòki֨y dòbé֤r ʼéle֨y⁠ká֙ wa⁠ʻàmò֣d ʻal-ʻámĕde֔⁠ká ki֥̇y ʻaţá֖̇h şǔlȧ֣ẖĕţi̇y ʼéle֑y⁠ká ẇ⁠bĕ⁠dabĕ̇r֥⁠wò ʻimi֛̇⁠y ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h ʻáma֥dĕţi̇y marĕʻiֽyd׃"],[10,12,"וַ⁠יֹּ֣אמֶר אֵלַ⁠י֮ אַל־תִּירָ֣א דָנִיֵּאל֒ כִּ֣י ׀ מִן־הַ⁠יּ֣וֹם הָ⁠רִאשׁ֗וֹן אֲשֶׁ֨ר נָתַ֧תָּ אֶֽת־לִבְּ⁠ךָ֛ לְ⁠הָבִ֧ין וּ⁠לְ⁠הִתְעַנּ֛וֹת לִ⁠פְנֵ֥י אֱלֹהֶ֖י⁠ךָ נִשְׁמְע֣וּ דְבָרֶ֑י⁠ךָ וַ⁠אֲנִי־בָ֖אתִי בִּ⁠דְבָרֶֽי⁠ךָ׃","wa⁠yò֣̇ʼmer ʼéla⁠y֮ ʼal-ţi̇yrá֣ʼ dániyé̇ʼl֒ ki֣̇y ׀ min-ha⁠ẏ֣wòm há⁠riʼş̌֗wòn ʼàşě֨r náţa֧ţá̇ ʼeֽţ-libĕ̇⁠ká֛ lĕ⁠hábi֧yn ẇ⁠lĕ⁠hiţĕʻaṅ֛wòţ li⁠pĕné֥y ʼèlòhe֖y⁠ká nişĕ̌mĕʻ֣ẇ dĕbáre֑y⁠ká wa⁠ʼàniy-bá֖ʼţiy bi̇⁠dĕbáreֽy⁠ká׃"],[10,13,"וְ⁠שַׂ֣ר ׀ מַלְכ֣וּת פָּרַ֗ס עֹמֵ֤ד לְ⁠נֶגְדִּ⁠י֙ עֶשְׂרִ֣ים וְ⁠אֶחָ֣ד י֔וֹם וְ⁠הִנֵּ֣ה מִֽיכָאֵ֗ל אַחַ֛ד הַ⁠שָּׂרִ֥ים הָ⁠רִאשֹׁנִ֖ים בָּ֣א לְ⁠עָזְרֵ֑⁠נִי וַ⁠אֲנִי֙ נוֹתַ֣רְתִּי שָׁ֔ם אֵ֖צֶל מַלְכֵ֥י פָרָֽס׃","wĕ⁠şâ֣r ׀ malĕk֣ẇţ pá̇ra֗s ʻòmé֤d lĕ⁠negĕdi̇⁠y֙ ʻeşĕ̂ri֣ym wĕ⁠ʼeẖá֣d y֔wòm wĕ⁠hiné֣̇h miֽykáʼé֗l ʼaẖa֛d ha⁠şá̇̂ri֥ym há⁠riʼşò̌ni֖ym bá֣̇ʼ lĕ⁠ʻázĕré֑⁠niy wa⁠ʼàniy֙ nwòţa֣rĕţi̇y şá̌֔m ʼé֖ẕel malĕké֥y páráֽs׃"],[10,14,"וּ⁠בָ֨אתִי֙ לַ⁠הֲבִ֣ינְ⁠ךָ֔ אֵ֛ת אֲשֶׁר־יִקְרָ֥ה לְ⁠עַמְּ⁠ךָ֖ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֑ים כִּי־ע֥וֹד חָז֖וֹן לַ⁠יָּמִֽים׃","ẇ⁠bá֨ʼţiy֙ la⁠hàbi֣ynĕ⁠ká֔ ʼé֛ţ ʼàşěr-yiqĕrá֥h lĕ⁠ʻamĕ̇⁠ká֖ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֑ym ki̇y-ʻ֥wòd ẖáz֖wòn la⁠yá̇miֽym׃"],[10,15,"וּ⁠בְ⁠דַבְּר֣⁠וֹ עִמִּ֔⁠י כַּ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה נָתַ֧תִּי פָנַ֛⁠י אַ֖רְצָ⁠ה וְ⁠נֶאֱלָֽמְתִּי׃","ẇ⁠bĕ⁠dabĕ̇r֣⁠wò ʻimi̇֔⁠y kȧ⁠dĕ̇bári֖ym há⁠ʼé֑lėh náţa֧ţi̇y pána֛⁠y ʼa֖rĕẕá⁠h wĕ⁠neʼèláֽmĕţi̇y׃"],[10,16,"וְ⁠הִנֵּ֗ה כִּ⁠דְמוּת֙ בְּנֵ֣י אָדָ֔ם נֹגֵ֖עַ עַל־שְׂפָתָ֑⁠י וָ⁠אֶפְתַּח־פִּ֗⁠י וָ⁠אֲדַבְּרָ⁠ה֙ וָ⁠אֹֽמְרָ⁠ה֙ אֶל־הָ⁠עֹמֵ֣ד לְ⁠נֶגְדִּ֔⁠י אֲדֹנִ֗⁠י בַּ⁠מַּרְאָה֙ נֶהֶפְכ֤וּ צִירַ⁠י֙ עָלַ֔⁠י וְ⁠לֹ֥א עָצַ֖רְתִּי כֹּֽחַ׃","wĕ⁠hiné̇֗h ki̇⁠dĕmẇţ֙ bĕ̇né֣y ʼádá֔m nògé֖ʻa ʻal-şĕ̂páţá֑⁠y wá⁠ʼepĕţȧẖ-pi̇֗⁠y wá⁠ʼàdabĕ̇rá⁠h֙ wá⁠ʼòֽmĕrá⁠h֙ ʼel-há⁠ʻòmé֣d lĕ⁠negĕdi̇֔⁠y ʼàdòni֗⁠y bȧ⁠mȧrĕʼáh֙ nehepĕk֤ẇ ẕiyra⁠y֙ ʻála֔⁠y wĕ⁠lò֥ʼ ʻáẕa֖rĕţi̇y kòֽ̇ẖa׃"],[10,17,"וְ⁠הֵ֣יךְ יוּכַ֗ל עֶ֤בֶד אֲדֹנִ⁠י֙ זֶ֔ה לְ⁠דַבֵּ֖ר עִם־אֲדֹ֣נִ⁠י זֶ֑ה וַ⁠אֲנִ֤י מֵ⁠עַ֨תָּה֙ לֹֽא־יַעֲמָד־בִּ֣⁠י כֹ֔חַ וּ⁠נְשָׁמָ֖ה לֹ֥א נִשְׁאֲרָה־בִֽ⁠י׃","wĕ⁠hé֣ykĕ yẇka֗l ʻe֤bed ʼàdòni⁠y֙ ze֔h lĕ⁠dabé֖̇r ʻim-ʼàdò֣ni⁠y ze֑h wa⁠ʼàni֤y mé⁠ʻa֨ţá̇h֙ lòֽʼ-yaʻàmád-bi֣̇⁠y kò֔ẖa ẇ⁠nĕşá̌má֖h lò֥ʼ nişĕ̌ʼàráh-biֽ⁠y׃"],[10,18,"וַ⁠יֹּ֧סֶף וַ⁠יִּגַּע־בִּ֛⁠י כְּ⁠מַרְאֵ֥ה אָדָ֖ם וַֽ⁠יְחַזְּקֵֽ⁠נִי׃","wa⁠yò֧̇sep wa⁠yi̇gȧʻ-bi֛̇⁠y kĕ̇⁠marĕʼé֥h ʼádá֖m waֽ⁠yĕẖazĕ̇qéֽ⁠niy׃"],[10,19,"וַ⁠יֹּ֜אמֶר אַל־תִּירָ֧א אִישׁ־חֲמֻד֛וֹת שָׁל֥וֹם לָ֖⁠ךְ חֲזַ֣ק וַ⁠חֲזָ֑ק וּֽ⁠בְ⁠דַבְּר֤⁠וֹ עִמִּ⁠י֙ הִתְחַזַּ֔קְתִּי וָ⁠אֹֽמְרָ֛⁠ה יְדַבֵּ֥ר אֲדֹנִ֖⁠י כִּ֥י חִזַּקְתָּֽ⁠נִי׃","wa⁠yò̇֜ʼmer ʼal-ţi̇yrá֧ʼ ʼiyş̌-ẖàmud֛wòţ şá̌l֥wòm lá֖⁠kĕ ẖàza֣q wa⁠ẖàzá֑q ẇֽ⁠bĕ⁠dabĕ̇r֤⁠wò ʻimi̇⁠y֙ hiţĕẖazȧ֔qĕţi̇y wá⁠ʼòֽmĕrá֛⁠h yĕdabé֥̇r ʼàdòni֖⁠y ki֥̇y ẖizȧqĕţáֽ̇⁠niy׃"],[10,20,"וַ⁠יֹּ֗אמֶר הֲ⁠יָדַ֨עְתָּ֙ לָ⁠מָּה־בָּ֣אתִי אֵלֶ֔י⁠ךָ וְ⁠עַתָּ֣ה אָשׁ֔וּב לְ⁠הִלָּחֵ֖ם עִם־שַׂ֣ר פָּרָ֑ס וַ⁠אֲנִ֣י יוֹצֵ֔א וְ⁠הִנֵּ֥ה שַׂר־יָוָ֖ן בָּֽא׃","wa⁠yò̇֗ʼmer hà⁠yáda֨ʻĕţá̇֙ lá⁠má̇h-bá֣̇ʼţiy ʼéle֔y⁠ká wĕ⁠ʻaţá֣̇h ʼáş̌֔ẇb lĕ⁠hilá̇ẖé֖m ʻim-şâ֣r pá̇rá֑s wa⁠ʼàni֣y ywòẕé֔ʼ wĕ⁠hiné֥̇h şâr-yáwá֖n báֽ̇ʼ׃"],[10,21,"אֲבָל֙ אַגִּ֣יד לְ⁠ךָ֔ אֶת־הָ⁠רָשׁ֥וּם בִּ⁠כְתָ֖ב אֱמֶ֑ת וְ⁠אֵ֨ין אֶחָ֜ד מִתְחַזֵּ֤ק עִמִּ⁠י֙ עַל־אֵ֔לֶּה כִּ֥י אִם־מִיכָאֵ֖ל שַׂרְ⁠כֶֽם׃פ","ʼàbál֙ ʼagi֣̇yd lĕ⁠ká֔ ʼeţ-há⁠ráş֥̌ẇm bi̇⁠kĕţá֖b ʼème֑ţ wĕ⁠ʼé֨yn ʼeẖá֜d miţĕẖazé֤̇q ʻimi̇⁠y֙ ʻal-ʼé֔lėh ki֥̇y ʼim-miykáʼé֖l şârĕ⁠keֽm׃p"],[11,1,"וַ⁠אֲנִי֙ בִּ⁠שְׁנַ֣ת אַחַ֔ת לְ⁠דָרְיָ֖וֶשׁ הַ⁠מָּדִ֑י עָמְדִ֛⁠י לְ⁠מַחֲזִ֥יק וּ⁠לְ⁠מָע֖וֹז לֽ⁠וֹ׃","wa⁠ʼàniy֙ bi̇⁠şĕ̌na֣ţ ʼaẖa֔ţ lĕ⁠dárĕyá֖weş̌ ha⁠má̇di֑y ʻámĕdi֛⁠y lĕ⁠maẖàzi֥yq ẇ⁠lĕ⁠máʻ֖wòz lֽ⁠wò׃"],[11,2,"וְ⁠עַתָּ֕ה אֱמֶ֖ת אַגִּ֣יד לָ֑⁠ךְ הִנֵּה־עוֹד֩ שְׁלֹשָׁ֨ה מְלָכִ֜ים עֹמְדִ֣ים לְ⁠פָרַ֗ס וְ⁠הָֽ⁠רְבִיעִי֙ יַעֲשִׁ֤יר עֹֽשֶׁר־גָּדוֹל֙ מִ⁠כֹּ֔ל וּ⁠כְ⁠חֶזְקָת֣⁠וֹ בְ⁠עָשְׁר֔⁠וֹ יָעִ֣יר הַ⁠כֹּ֔ל אֵ֖ת מַלְכ֥וּת יָוָֽן׃","wĕ⁠ʻaţá̇֕h ʼème֖ţ ʼagi֣̇yd lá֑⁠kĕ hiné̇h-ʻwòd֩ şĕ̌lòşá̌֨h mĕláki֜ym ʻòmĕdi֣ym lĕ⁠pára֗s wĕ⁠háֽ⁠rĕbiyʻiy֙ yaʻàşǐ֤yr ʻòֽşěr-gá̇dwòl֙ mi⁠kò̇֔l ẇ⁠kĕ⁠ẖezĕqáţ֣⁠wò bĕ⁠ʻáşĕ̌r֔⁠wò yáʻi֣yr ha⁠kò̇֔l ʼé֖ţ malĕk֥ẇţ yáwáֽn׃"],[11,3,"וְ⁠עָמַ֖ד מֶ֣לֶךְ גִּבּ֑וֹר וּ⁠מָשַׁל֙ מִמְשָׁ֣ל רַ֔ב וְ⁠עָשָׂ֖ה כִּ⁠רְצוֹנֽ⁠וֹ׃","wĕ⁠ʻáma֖d me֣lekĕ gi̇ḃ֑wòr ẇ⁠máşǎl֙ mimĕşá֣̌l ra֔b wĕ⁠ʻáşá֖̂h ki̇⁠rĕẕwònֽ⁠wò׃"],[11,4,"וּ⁠כְ⁠עָמְד⁠וֹ֙ תִּשָּׁבֵ֣ר מַלְכוּת֔⁠וֹ וְ⁠תֵחָ֕ץ לְ⁠אַרְבַּ֖ע רוּח֣וֹת הַ⁠שָּׁמָ֑יִם וְ⁠לֹ֣א לְ⁠אַחֲרִית֗⁠וֹ וְ⁠לֹ֤א כְ⁠מָשְׁל⁠וֹ֙ אֲשֶׁ֣ר מָשָׁ֔ל כִּ֤י תִנָּתֵשׁ֙ מַלְכוּת֔⁠וֹ וְ⁠לַ⁠אֲחֵרִ֖ים מִ⁠לְּ⁠בַד־אֵֽלֶּה׃","ẇ⁠kĕ⁠ʻámĕd⁠wò֙ ţi̇şá̇̌bé֣r malĕkẇţ֔⁠wò wĕ⁠ţéẖá֕ẕ lĕ⁠ʼarĕbȧ֖ʻ rẇẖ֣wòţ ha⁠şá̇̌má֑yim wĕ⁠lò֣ʼ lĕ⁠ʼaẖàriyţ֗⁠wò wĕ⁠lò֤ʼ kĕ⁠máşĕ̌l⁠wò֙ ʼàşě֣r máşá̌֔l ki֤̇y ţiná̇ţéş̌֙ malĕkẇţ֔⁠wò wĕ⁠la⁠ʼàẖéri֖ym mi⁠lĕ̇⁠bad-ʼéֽlėh׃"],[11,5,"וְ⁠יֶחֱזַ֥ק מֶֽלֶךְ־הַ⁠נֶּ֖גֶב וּ⁠מִן־שָׂרָ֑י⁠ו וְ⁠יֶחֱזַ֤ק עָלָי⁠ו֙ וּ⁠מָשָׁ֔ל מִמְשָׁ֥ל רַ֖ב מֶמְשַׁלְתּֽ⁠וֹ׃","wĕ⁠yeẖèza֥q meֽlekĕ-ha⁠nė֖geb ẇ⁠min-şá̂rá֑y⁠w wĕ⁠yeẖèza֤q ʻáláy⁠w֙ ẇ⁠máşá̌֔l mimĕşá֥̌l ra֖b memĕşǎlĕţֽ̇⁠wò׃"],[11,6,"וּ⁠לְ⁠קֵ֤ץ שָׁנִים֙ יִתְחַבָּ֔רוּ וּ⁠בַ֣ת מֶֽלֶךְ־הַ⁠נֶּ֗גֶב תָּבוֹא֙ אֶל־מֶ֣לֶךְ הַ⁠צָּפ֔וֹן לַ⁠עֲשׂ֖וֹת מֵישָׁרִ֑ים וְ⁠לֹֽא־תַעְצֹ֞ר כּ֣וֹחַ הַ⁠זְּר֗וֹעַ וְ⁠לֹ֤א יַעֲמֹד֙ וּ⁠זְרֹע֔⁠וֹ וְ⁠תִנָּתֵ֨ן הִ֤יא וּ⁠מְבִיאֶ֨י⁠הָ֙ וְ⁠הַ⁠יֹּ֣לְדָ֔⁠הּ וּ⁠מַחֲזִקָ֖⁠הּ בָּ⁠עִתִּֽים׃","ẇ⁠lĕ⁠qé֤ẕ şá̌niym֙ yiţĕẖabá̇֔rẇ ẇ⁠ba֣ţ meֽlekĕ-ha⁠nė֗geb ţá̇bwòʼ֙ ʼel-me֣lekĕ ha⁠ẕá̇p֔wòn la⁠ʻàş֖̂wòţ méyşá̌ri֑ym wĕ⁠lòֽʼ-ţaʻĕẕò֞r k֣̇wòẖa ha⁠zĕ̇r֗wòʻa wĕ⁠lò֤ʼ yaʻàmòd֙ ẇ⁠zĕròʻ֔⁠wò wĕ⁠ţiná̇ţé֨n hi֤yʼ ẇ⁠mĕbiyʼe֨y⁠há֙ wĕ⁠ha⁠yò֣̇lĕdá֔⁠ḣ ẇ⁠maẖàziqá֖⁠ḣ bá̇⁠ʻiţiֽ̇ym׃"],[11,7,"וְ⁠עָמַ֛ד מִ⁠נֵּ֥צֶר שָׁרָשֶׁ֖י⁠הָ כַּנּ֑⁠וֹ וְ⁠יָבֹ֣א אֶל־הַ⁠חַ֗יִל וְ⁠יָבֹא֙ בְּ⁠מָעוֹז֙ מֶ֣לֶךְ הַ⁠צָּפ֔וֹן וְ⁠עָשָׂ֥ה בָ⁠הֶ֖ם וְ⁠הֶחֱזִֽיק׃","wĕ⁠ʻáma֛d mi⁠né֥̇ẕer şá̌ráşě֖y⁠há kȧṅ֑⁠wò wĕ⁠yábò֣ʼ ʼel-ha⁠ẖa֗yil wĕ⁠yábòʼ֙ bĕ̇⁠máʻwòz֙ me֣lekĕ ha⁠ẕá̇p֔wòn wĕ⁠ʻáşá֥̂h bá⁠he֖m wĕ⁠heẖèziֽyq׃"],[11,8,"וְ⁠גַ֣ם אֱֽלֹהֵי⁠הֶ֡ם עִם־נְסִֽכֵי⁠הֶם֩ עִם־כְּלֵ֨י חֶמְדָּתָ֜⁠ם כֶּ֧סֶף וְ⁠זָהָ֛ב בַּ⁠שְּׁבִ֖י יָבִ֣א מִצְרָ֑יִם וְ⁠הוּא֙ שָׁנִ֣ים יַעֲמֹ֔ד מִ⁠מֶּ֖לֶךְ הַ⁠צָּפֽוֹן׃","wĕ⁠ga֣m ʼèֽlòhéy⁠he֡m ʻim-nĕsiֽkéy⁠hem֩ ʻim-kĕ̇lé֨y ẖemĕdá̇ţá֜⁠m kė֧sep wĕ⁠záhá֛b bȧ⁠şĕ̇̌bi֖y yábi֣ʼ miẕĕrá֑yim wĕ⁠hẇʼ֙ şá̌ni֣ym yaʻàmò֔d mi⁠mė֖lekĕ ha⁠ẕá̇pֽwòn׃"],[11,9,"וּ⁠בָ֗א בְּ⁠מַלְכוּת֙ מֶ֣לֶךְ הַ⁠נֶּ֔גֶב וְ⁠שָׁ֖ב אֶל־אַדְמָתֽ⁠וֹ׃","ẇ⁠bá֗ʼ bĕ̇⁠malĕkẇţ֙ me֣lekĕ ha⁠nė֔geb wĕ⁠şá֖̌b ʼel-ʼadĕmáţֽ⁠wò׃"],[11,10,"ו⁠בנ⁠ו יִתְגָּר֗וּ וְ⁠אָסְפוּ֙ הֲמוֹן֙ חֲיָלִ֣ים רַבִּ֔ים וּ⁠בָ֥א ב֖וֹא וְ⁠שָׁטַ֣ף וְ⁠עָבָ֑ר וְ⁠יָשֹׁ֥ב ו⁠יתגרו עַד־מעז⁠ה׃","w⁠bn⁠w yiţĕgá̇r֗ẇ wĕ⁠ʼásĕpẇ֙ hàmwòn֙ ẖàyáli֣ym rabi̇֔ym ẇ⁠bá֥ʼ b֖wòʼ wĕ⁠şá̌ta֣p wĕ⁠ʻábá֑r wĕ⁠yáşò֥̌b w⁠yţgrw ʻad-mʻz⁠h׃"],[11,11,"וְ⁠יִתְמַרְמַר֙ מֶ֣לֶךְ הַ⁠נֶּ֔גֶב וְ⁠יָצָ֕א וְ⁠נִלְחַ֥ם עִמּ֖⁠וֹ עִם־מֶ֣לֶךְ הַ⁠צָּפ֑וֹן וְ⁠הֶעֱמִיד֙ הָמ֣וֹן רָ֔ב וְ⁠נִתַּ֥ן הֶ⁠הָמ֖וֹן בְּ⁠יָדֽ⁠וֹ׃","wĕ⁠yiţĕmarĕmar֙ me֣lekĕ ha⁠nė֔geb wĕ⁠yáẕá֕ʼ wĕ⁠nilĕẖa֥m ʻiṁ֖⁠wò ʻim-me֣lekĕ ha⁠ẕá̇p֑wòn wĕ⁠heʻèmiyd֙ hám֣wòn rá֔b wĕ⁠niţȧ֥n he⁠hám֖wòn bĕ̇⁠yádֽ⁠wò׃"],[11,12,"וְ⁠נִשָּׂ֥א הֶ⁠הָמ֖וֹן ירום לְבָב֑⁠וֹ וְ⁠הִפִּ֛יל רִבֹּא֖וֹת וְ⁠לֹ֥א יָעֽוֹז׃","wĕ⁠nişá֥̇̂ʼ he⁠hám֖wòn yrwm lĕbáb֑⁠wò wĕ⁠hipi֛̇yl ribò̇ʼ֖wòţ wĕ⁠lò֥ʼ yáʻֽwòz׃"],[11,13,"וְ⁠שָׁב֙ מֶ֣לֶךְ הַ⁠צָּפ֔וֹן וְ⁠הֶעֱמִ֣יד הָמ֔וֹן רַ֖ב מִן־הָ⁠רִאשׁ֑וֹן וּ⁠לְ⁠קֵ֨ץ הָֽ⁠עִתִּ֤ים שָׁנִים֙ יָ֣בוֹא ב֔וֹא בְּ⁠חַ֥יִל גָּד֖וֹל וּ⁠בִ⁠רְכ֥וּשׁ רָֽב׃","wĕ⁠şá̌b֙ me֣lekĕ ha⁠ẕá̇p֔wòn wĕ⁠heʻèmi֣yd hám֔wòn ra֖b min-há⁠riʼş֑̌wòn ẇ⁠lĕ⁠qé֨ẕ háֽ⁠ʻiţi֤̇ym şá̌niym֙ yá֣bwòʼ b֔wòʼ bĕ̇⁠ẖa֥yil gá̇d֖wòl ẇ⁠bi⁠rĕk֥ẇş̌ ráֽb׃"],[11,14,"וּ⁠בָ⁠עִתִּ֣ים הָ⁠הֵ֔ם רַבִּ֥ים יַֽעַמְד֖וּ עַל־מֶ֣לֶךְ הַ⁠נֶּ֑גֶב וּ⁠בְנֵ֣י ׀ פָּרִיצֵ֣י עַמְּ⁠ךָ֗ יִֽנַּשְּׂא֛וּ לְ⁠הַעֲמִ֥יד חָז֖וֹן וְ⁠נִכְשָֽׁלוּ׃","ẇ⁠bá⁠ʻiţi֣̇ym há⁠hé֔m rabi֥̇ym yaֽʻamĕd֖ẇ ʻal-me֣lekĕ ha⁠nė֑geb ẇ⁠bĕné֣y ׀ pá̇riyẕé֣y ʻamĕ̇⁠ká֗ yiֽnȧşĕ̇̂ʼ֛ẇ lĕ⁠haʻàmi֥yd ẖáz֖wòn wĕ⁠nikĕşáֽ̌lẇ׃"],[11,15,"וְ⁠יָבֹא֙ מֶ֣לֶךְ הַ⁠צָּפ֔וֹן וְ⁠יִשְׁפֹּךְ֙ סֽוֹלֲלָ֔ה וְ⁠לָכַ֖ד עִ֣יר מִבְצָר֑וֹת וּ⁠זְרֹע֤וֹת הַ⁠נֶּ֨גֶב֙ לֹ֣א יַעֲמֹ֔דוּ וְ⁠עַם֙ מִבְחָרָ֔י⁠ו וְ⁠אֵ֥ין כֹּ֖חַ לַ⁠עֲמֹֽד׃","wĕ⁠yábòʼ֙ me֣lekĕ ha⁠ẕá̇p֔wòn wĕ⁠yişĕ̌pò̇kĕ֙ sֽwòlàlá֔h wĕ⁠láka֖d ʻi֣yr mibĕẕár֑wòţ ẇ⁠zĕròʻ֤wòţ ha⁠nė֨geb֙ lò֣ʼ yaʻàmò֔dẇ wĕ⁠ʻam֙ mibĕẖárá֔y⁠w wĕ⁠ʼé֥yn kò֖̇ẖa la⁠ʻàmòֽd׃"],[11,16,"וְ⁠יַ֨עַשׂ הַ⁠בָּ֤א אֵלָי⁠ו֙ כִּ⁠רְצוֹנ֔⁠וֹ וְ⁠אֵ֥ין עוֹמֵ֖ד לְ⁠פָנָ֑י⁠ו וְ⁠יַעֲמֹ֥ד בְּ⁠אֶֽרֶץ־הַ⁠צְּבִ֖י וְ⁠כָלָ֥ה בְ⁠יָדֽ⁠וֹ׃","wĕ⁠ya֨ʻaş̂ ha⁠bá֤̇ʼ ʼéláy⁠w֙ ki̇⁠rĕẕwòn֔⁠wò wĕ⁠ʼé֥yn ʻwòmé֖d lĕ⁠páná֑y⁠w wĕ⁠yaʻàmò֥d bĕ̇⁠ʼeֽreẕ-ha⁠ẕĕ̇bi֖y wĕ⁠kálá֥h bĕ⁠yádֽ⁠wò׃"],[11,17,"וְ⁠יָשֵׂ֣ם ׀ פָּ֠נָי⁠ו לָ⁠ב֞וֹא בְּ⁠תֹ֧קֶף כָּל־מַלְכוּת֛⁠וֹ וִ⁠ישָׁרִ֥ים עִמּ֖⁠וֹ וְ⁠עָשָׂ֑ה וּ⁠בַ֤ת הַ⁠נָּשִׁים֙ יִתֶּן־ל֣⁠וֹ לְ⁠הַשְׁחִיתָ֔⁠הּ וְ⁠לֹ֥א תַעֲמֹ֖ד וְ⁠לֹא־ל֥⁠וֹ תִהְיֶֽה׃","wĕ⁠yáşé֣̂m ׀ pá̇֠náy⁠w lá⁠b֞wòʼ bĕ̇⁠ţò֧qep ká̇l-malĕkẇţ֛⁠wò wi⁠yşá̌ri֥ym ʻiṁ֖⁠wò wĕ⁠ʻáşá֑̂h ẇ⁠ba֤ţ ha⁠ná̇şǐym֙ yiţėn-l֣⁠wò lĕ⁠haşĕ̌ẖiyţá֔⁠ḣ wĕ⁠lò֥ʼ ţaʻàmò֖d wĕ⁠lòʼ-l֥⁠wò ţihĕyeֽh׃"],[11,18,"ו⁠ישב ׀ פָּנָ֛י⁠ו לְ⁠אִיִּ֖ים וְ⁠לָכַ֣ד רַבִּ֑ים וְ⁠הִשְׁבִּ֨ית קָצִ֤ין חֶרְפָּת⁠וֹ֙ ל֔⁠וֹ בִּלְתִּ֥י חֶרְפָּת֖⁠וֹ יָשִׁ֥יב לֽ⁠וֹ׃","w⁠yşb ׀ pá̇ná֛y⁠w lĕ⁠ʼiyi֖̇ym wĕ⁠láka֣d rabi֑̇ym wĕ⁠hişĕ̌bi̇֨yţ qáẕi֤yn ẖerĕpá̇ţ⁠wò֙ l֔⁠wò bi̇lĕţi֥̇y ẖerĕpá̇ţ֖⁠wò yáşǐ֥yb lֽ⁠wò׃"],[11,19,"וְ⁠יָשֵׁ֣ב פָּנָ֔י⁠ו לְ⁠מָעוּזֵּ֖י אַרְצ֑⁠וֹ וְ⁠נִכְשַׁ֥ל וְ⁠נָפַ֖ל וְ⁠לֹ֥א יִמָּצֵֽא׃","wĕ⁠yáşé֣̌b pá̇ná֔y⁠w lĕ⁠máʻẇzé֖̇y ʼarĕẕ֑⁠wò wĕ⁠nikĕşǎ֥l wĕ⁠nápa֖l wĕ⁠lò֥ʼ yimá̇ẕéֽʼ׃"],[11,20,"וְ⁠עָמַ֧ד עַל־כַּנּ֛⁠וֹ מַעֲבִ֥יר נוֹגֵ֖שׂ הֶ֣דֶר מַלְכ֑וּת וּ⁠בְ⁠יָמִ֤ים אֲחָדִים֙ יִשָּׁבֵ֔ר וְ⁠לֹ֥א בְ⁠אַפַּ֖יִם וְ⁠לֹ֥א בְ⁠מִלְחָמָֽה׃","wĕ⁠ʻáma֧d ʻal-kȧṅ֛⁠wò maʻàbi֥yr nwògé֖ş̂ he֣der malĕk֑ẇţ ẇ⁠bĕ⁠yámi֤ym ʼàẖádiym֙ yişá̇̌bé֔r wĕ⁠lò֥ʼ bĕ⁠ʼapȧ֖yim wĕ⁠lò֥ʼ bĕ⁠milĕẖámáֽh׃"],[11,21,"וְ⁠עָמַ֤ד עַל־כַּנּ⁠וֹ֙ נִבְזֶ֔ה וְ⁠לֹא־נָתְנ֥וּ עָלָ֖י⁠ו ה֣וֹד מַלְכ֑וּת וּ⁠בָ֣א בְ⁠שַׁלְוָ֔ה וְ⁠הֶחֱזִ֥יק מַלְכ֖וּת בַּ⁠חֲלַקְלַקּֽוֹת׃","wĕ⁠ʻáma֤d ʻal-kȧṅ⁠wò֙ nibĕze֔h wĕ⁠lòʼ-náţĕn֥ẇ ʻálá֖y⁠w h֣wòd malĕk֑ẇţ ẇ⁠bá֣ʼ bĕ⁠şǎlĕwá֔h wĕ⁠heẖèzi֥yq malĕk֖ẇţ bȧ⁠ẖàlaqĕlaqֽ̇wòţ׃"],[11,22,"וּ⁠זְרֹע֥וֹת הַ⁠שֶּׁ֛טֶף יִשָּׁטְפ֥וּ מִ⁠לְּ⁠פָנָ֖י⁠ו וְ⁠יִשָּׁבֵ֑רוּ וְ⁠גַ֖ם נְגִ֥יד בְּרִֽית׃","ẇ⁠zĕròʻ֥wòţ ha⁠şė֛̌tep yişá̇̌tĕp֥ẇ mi⁠lĕ̇⁠páná֖y⁠w wĕ⁠yişá̇̌bé֑rẇ wĕ⁠ga֖m nĕgi֥yd bĕ̇riֽyţ׃"],[11,23,"וּ⁠מִן־הִֽתְחַבְּר֥וּת אֵלָ֖י⁠ו יַעֲשֶׂ֣ה מִרְמָ֑ה וְ⁠עָלָ֥ה וְ⁠עָצַ֖ם בִּ⁠מְעַט־גּֽוֹי׃","ẇ⁠min-hiֽţĕẖabĕ̇r֥ẇţ ʼélá֖y⁠w yaʻàşê֣h mirĕmá֑h wĕ⁠ʻálá֥h wĕ⁠ʻáẕa֖m bi̇⁠mĕʻat-ġֽwòy׃"],[11,24,"בְּ⁠שַׁלְוָ֞ה וּ⁠בְ⁠מִשְׁמַנֵּ֣י מְדִינָה֮ יָבוֹא֒ וְ⁠עָשָׂ֗ה אֲשֶׁ֨ר לֹא־עָשׂ֤וּ אֲבֹתָי⁠ו֙ וַ⁠אֲב֣וֹת אֲבֹתָ֔י⁠ו בִּזָּ֧ה וְ⁠שָׁלָ֛ל וּ⁠רְכ֖וּשׁ לָ⁠הֶ֣ם יִבְז֑וֹר וְ⁠עַ֧ל מִבְצָרִ֛ים יְחַשֵּׁ֥ב מַחְשְׁבֹתָ֖י⁠ו וְ⁠עַד־עֵֽת׃","bĕ̇⁠şǎlĕwá֞h ẇ⁠bĕ⁠mişĕ̌mané֣̇y mĕdiynáh֮ yábwòʼ֒ wĕ⁠ʻáşá̂֗h ʼàşě֨r lòʼ-ʻáş֤̂ẇ ʼàbòţáy⁠w֙ wa⁠ʼàb֣wòţ ʼàbòţá֔y⁠w bi̇zá֧̇h wĕ⁠şá̌lá֛l ẇ⁠rĕk֖ẇş̌ lá⁠he֣m yibĕz֑wòr wĕ⁠ʻa֧l mibĕẕári֛ym yĕẖaşé֥̇̌b maẖĕşĕ̌bòţá֖y⁠w wĕ⁠ʻad-ʻéֽţ׃"],[11,25,"וְ⁠יָעֵר֩ כֹּח֨⁠וֹ וּ⁠לְבָב֜⁠וֹ עַל־מֶ֣לֶךְ הַ⁠נֶּגֶב֮ בְּ⁠חַ֣יִל גָּדוֹל֒ וּ⁠מֶ֣לֶךְ הַ⁠נֶּ֗גֶב יִתְגָּרֶה֙ לַ⁠מִּלְחָמָ֔ה בְּ⁠חַֽיִל־גָּד֥וֹל וְ⁠עָצ֖וּם עַד־מְאֹ֑ד וְ⁠לֹ֣א יַעֲמֹ֔ד כִּֽי־יַחְשְׁב֥וּ עָלָ֖י⁠ו מַחֲשָׁבֽוֹת׃","wĕ⁠yáʻér֩ kò̇ẖ֨⁠wò ẇ⁠lĕbáb֜⁠wò ʻal-me֣lekĕ ha⁠nėgeb֮ bĕ̇⁠ẖa֣yil gá̇dwòl֒ ẇ⁠me֣lekĕ ha⁠nė֗geb yiţĕgá̇reh֙ la⁠mi̇lĕẖámá֔h bĕ̇⁠ẖaֽyil-gá̇d֥wòl wĕ⁠ʻáẕ֖ẇm ʻad-mĕʼò֑d wĕ⁠lò֣ʼ yaʻàmò֔d kiֽ̇y-yaẖĕşĕ̌b֥ẇ ʻálá֖y⁠w maẖàşá̌bֽwòţ׃"],[11,26,"וְ⁠אֹכְלֵ֧י פַת־בָּג֛⁠וֹ יִשְׁבְּר֖וּ⁠הוּ וְ⁠חֵיל֣⁠וֹ יִשְׁט֑וֹף וְ⁠נָפְל֖וּ חֲלָלִ֥ים רַבִּֽים׃","wĕ⁠ʼòkĕlé֧y paţ-bá̇g֛⁠wò yişĕ̌bĕ̇r֖ẇ⁠hẇ wĕ⁠ẖéyl֣⁠wò yişĕ̌t֑wòp wĕ⁠nápĕl֖ẇ ẖàláli֥ym rabiֽ̇ym׃"],[11,27,"וּ⁠שְׁנֵי⁠הֶ֤ם הַ⁠מְּלָכִים֙ לְבָבָ֣⁠ם לְ⁠מֵרָ֔ע וְ⁠עַל־שֻׁלְחָ֥ן אֶחָ֖ד כָּזָ֣ב יְדַבֵּ֑רוּ וְ⁠לֹ֣א תִצְלָ֔ח כִּי־ע֥וֹד קֵ֖ץ לַ⁠מּוֹעֵֽד׃","ẇ⁠şĕ̌néy⁠he֤m ha⁠mĕ̇lákiym֙ lĕbábá֣⁠m lĕ⁠mérá֔ʻ wĕ⁠ʻal-şǔlĕẖá֥n ʼeẖá֖d ká̇zá֣b yĕdabé֑̇rẇ wĕ⁠lò֣ʼ ţiẕĕlá֔ẖ ki̇y-ʻ֥wòd qé֖ẕ la⁠ṁwòʻéֽd׃"],[11,28,"וְ⁠יָשֹׁ֤ב אַרְצ⁠וֹ֙ בִּ⁠רְכ֣וּשׁ גָּד֔וֹל וּ⁠לְבָב֖⁠וֹ עַל־בְּרִ֣ית קֹ֑דֶשׁ וְ⁠עָשָׂ֖ה וְ⁠שָׁ֥ב לְ⁠אַרְצֽ⁠וֹ׃","wĕ⁠yáşò֤̌b ʼarĕẕ⁠wò֙ bi̇⁠rĕk֣ẇş̌ gá̇d֔wòl ẇ⁠lĕbáb֖⁠wò ʻal-bĕ̇ri֣yţ qò֑deş̌ wĕ⁠ʻáşá֖̂h wĕ⁠şá֥̌b lĕ⁠ʼarĕẕֽ⁠wò׃"],[11,29,"לַ⁠מּוֹעֵ֥ד יָשׁ֖וּב וּ⁠בָ֣א בַ⁠נֶּ֑גֶב וְ⁠לֹֽא־תִהְיֶ֥ה כָ⁠רִאשֹׁנָ֖ה וְ⁠כָ⁠אַחֲרֹנָֽה׃","la⁠ṁwòʻé֥d yáş֖̌ẇb ẇ⁠bá֣ʼ ba⁠nė֑geb wĕ⁠lòֽʼ-ţihĕye֥h ká⁠riʼşò̌ná֖h wĕ⁠ká⁠ʼaẖàrònáֽh׃"],[11,30,"וּ⁠בָ֨אוּ ב֜⁠וֹ צִיִּ֤ים כִּתִּים֙ וְ⁠נִכְאָ֔ה וְ⁠שָׁ֛ב וְ⁠זָעַ֥ם עַל־בְּרִֽית־ק֖וֹדֶשׁ וְ⁠עָשָׂ֑ה וְ⁠שָׁ֣ב וְ⁠יָבֵ֔ן עַל־עֹזְבֵ֖י בְּרִ֥ית קֹֽדֶשׁ׃","ẇ⁠bá֨ʼẇ b֜⁠wò ẕiyi֤̇ym ki̇ţi̇ym֙ wĕ⁠nikĕʼá֔h wĕ⁠şá֛̌b wĕ⁠záʻa֥m ʻal-bĕ̇riֽyţ-q֖wòdeş̌ wĕ⁠ʻáşá֑̂h wĕ⁠şá֣̌b wĕ⁠yábé֔n ʻal-ʻòzĕbé֖y bĕ̇ri֥yţ qòֽdeş̌׃"],[11,31,"וּ⁠זְרֹעִ֖ים מִמֶּ֣⁠נּוּ יַעֲמֹ֑דוּ וְ⁠חִלְּל֞וּ הַ⁠מִּקְדָּ֤שׁ הַ⁠מָּעוֹז֙ וְ⁠הֵסִ֣ירוּ הַ⁠תָּמִ֔יד וְ⁠נָתְנ֖וּ הַ⁠שִּׁקּ֥וּץ מְשׁוֹמֵֽם׃","ẇ⁠zĕròʻi֖ym mimė֣⁠ṅẇ yaʻàmò֑dẇ wĕ⁠ẖilĕ̇l֞ẇ ha⁠mi̇qĕdá֤̇ş̌ ha⁠má̇ʻwòz֙ wĕ⁠hési֣yrẇ ha⁠ţá̇mi֔yd wĕ⁠náţĕn֖ẇ ha⁠şi̇̌q֥̇ẇẕ mĕş̌wòméֽm׃"],[11,32,"וּ⁠מַרְשִׁיעֵ֣י בְרִ֔ית יַחֲנִ֖יף בַּ⁠חֲלַקּ֑וֹת וְ⁠עַ֛ם יֹדְעֵ֥י אֱלֹהָ֖י⁠ו יַחֲזִ֥קוּ וְ⁠עָשֽׂוּ׃","ẇ⁠marĕşǐyʻé֣y bĕri֔yţ yaẖàni֖yp bȧ⁠ẖàlaq֑̇wòţ wĕ⁠ʻa֛m yòdĕʻé֥y ʼèlòhá֖y⁠w yaẖàzi֥qẇ wĕ⁠ʻáşֽ̂ẇ׃"],[11,33,"וּ⁠מַשְׂכִּ֣ילֵי עָ֔ם יָבִ֖ינוּ לָֽ⁠רַבִּ֑ים וְ⁠נִכְשְׁל֞וּ בְּ⁠חֶ֧רֶב וּ⁠בְ⁠לֶהָבָ֛ה בִּ⁠שְׁבִ֥י וּ⁠בְ⁠בִזָּ֖ה יָמִֽים׃","ẇ⁠maşĕ̂ki֣̇yléy ʻá֔m yábi֖ynẇ láֽ⁠rabi֑̇ym wĕ⁠nikĕşĕ̌l֞ẇ bĕ̇⁠ẖe֧reb ẇ⁠bĕ⁠lehábá֛h bi̇⁠şĕ̌bi֥y ẇ⁠bĕ⁠bizá֖̇h yámiֽym׃"],[11,34,"וּ⁠בְ⁠הִכָּ֣שְׁלָ֔⁠ם יֵעָזְר֖וּ עֵ֣זֶר מְעָ֑ט וְ⁠נִלְו֧וּ עֲלֵי⁠הֶ֛ם רַבִּ֖ים בַּ⁠חֲלַקְלַקּֽוֹת׃","ẇ⁠bĕ⁠hiká֣̇şĕ̌lá֔⁠m yéʻázĕr֖ẇ ʻé֣zer mĕʻá֑t wĕ⁠nilĕw֧ẇ ʻàléy⁠he֛m rabi֖̇ym bȧ⁠ẖàlaqĕlaqֽ̇wòţ׃"],[11,35,"וּ⁠מִן־הַ⁠מַּשְׂכִּילִ֣ים יִכָּֽשְׁל֗וּ לִ⁠צְר֥וֹף בָּ⁠הֶ֛ם וּ⁠לְ⁠בָרֵ֥ר וְ⁠לַ⁠לְבֵּ֖ן עַד־עֵ֣ת קֵ֑ץ כִּי־ע֖וֹד לַ⁠מּוֹעֵֽד׃","ẇ⁠min-ha⁠mȧşĕ̂ki̇yli֣ym yikáֽ̇şĕ̌l֗ẇ li⁠ẕĕr֥wòp bá̇⁠he֛m ẇ⁠lĕ⁠báré֥r wĕ⁠la⁠lĕbé֖̇n ʻad-ʻé֣ţ qé֑ẕ ki̇y-ʻ֖wòd la⁠ṁwòʻéֽd׃"],[11,36,"וְ⁠עָשָׂ֨ה כִ⁠רְצוֹנ֜⁠וֹ הַ⁠מֶּ֗לֶךְ וְ⁠יִתְרוֹמֵ֤ם וְ⁠יִתְגַּדֵּל֙ עַל־כָּל־אֵ֔ל וְ⁠עַל֙ אֵ֣ל אֵלִ֔ים יְדַבֵּ֖ר נִפְלָא֑וֹת וְ⁠הִצְלִ֨יחַ֙ עַד־כָּ֣לָה זַ֔עַם כִּ֥י נֶחֱרָצָ֖ה נֶעֱשָֽׂתָה׃","wĕ⁠ʻáşá̂֨h ki⁠rĕẕwòn֜⁠wò ha⁠mė֗lekĕ wĕ⁠yiţĕrwòmé֤m wĕ⁠yiţĕgȧdé̇l֙ ʻal-ká̇l-ʼé֔l wĕ⁠ʻal֙ ʼé֣l ʼéli֔ym yĕdabé֖̇r nipĕláʼ֑wòţ wĕ⁠hiẕĕli֨yẖa֙ ʻad-ká֣̇láh za֔ʻam ki֥̇y neẖèráẕá֖h neʻèşáֽ̂ţáh׃"],[11,37,"וְ⁠עַל־אֱלֹהֵ֤י אֲבֹתָי⁠ו֙ לֹ֣א יָבִ֔ין וְ⁠עַל־חֶמְדַּ֥ת נָשִׁ֛ים וְ⁠עַֽל־כָּל־אֱל֖וֹהַּ לֹ֣א יָבִ֑ין כִּ֥י עַל־כֹּ֖ל יִתְגַּדָּֽל׃","wĕ⁠ʻal-ʼèlòhé֤y ʼàbòţáy⁠w֙ lò֣ʼ yábi֔yn wĕ⁠ʻal-ẖemĕdȧ֥ţ náşǐ֛ym wĕ⁠ʻaֽl-ká̇l-ʼèl֖wòhȧ lò֣ʼ yábi֑yn ki֥̇y ʻal-kò֖̇l yiţĕgȧdáֽ̇l׃"],[11,38,"וְ⁠לֶ⁠אֱלֹ֨הַּ֙ מָֽעֻזִּ֔ים עַל־כַּנּ֖⁠וֹ יְכַבֵּ֑ד וְ⁠לֶ⁠אֱל֜וֹהַּ אֲשֶׁ֧ר לֹא־יְדָעֻ֣⁠הוּ אֲבֹתָ֗י⁠ו יְכַבֵּ֛ד בְּ⁠זָהָ֥ב וּ⁠בְ⁠כֶ֛סֶף וּ⁠בְ⁠אֶ֥בֶן יְקָרָ֖ה וּ⁠בַ⁠חֲמֻדֽוֹת׃","wĕ⁠le⁠ʼèlò֨hȧ֙ máֽʻuzi̇֔ym ʻal-kȧṅ֖⁠wò yĕkabé֑̇d wĕ⁠le⁠ʼèl֜wòhȧ ʼàşě֧r lòʼ-yĕdáʻu֣⁠hẇ ʼàbòţá֗y⁠w yĕkabé֛̇d bĕ̇⁠záhá֥b ẇ⁠bĕ⁠ke֛sep ẇ⁠bĕ⁠ʼe֥ben yĕqárá֖h ẇ⁠ba⁠ẖàmudֽwòţ׃"],[11,39,"וְ⁠עָשָׂ֞ה לְ⁠מִבְצְרֵ֤י מָֽעֻזִּים֙ עִם־אֱל֣וֹהַּ נֵכָ֔ר אֲשֶׁ֥ר הכיר יַרְבֶּ֣ה כָב֑וֹד וְ⁠הִמְשִׁילָ⁠ם֙ בָּֽ⁠רַבִּ֔ים וַ⁠אֲדָמָ֖ה יְחַלֵּ֥ק בִּ⁠מְחִֽיר׃","wĕ⁠ʻáşá̂֞h lĕ⁠mibĕẕĕré֤y máֽʻuzi̇ym֙ ʻim-ʼèl֣wòhȧ néká֔r ʼàşě֥r hkyr yarĕbė֣h káb֑wòd wĕ⁠himĕşǐylá⁠m֙ báֽ̇⁠rabi̇֔ym wa⁠ʼàdámá֖h yĕẖalé֥̇q bi̇⁠mĕẖiֽyr׃"],[11,40,"וּ⁠בְ⁠עֵ֣ת קֵ֗ץ יִתְנַגַּ֤ח עִמּ⁠וֹ֙ מֶ֣לֶךְ הַ⁠נֶּ֔גֶב וְ⁠יִשְׂתָּעֵ֨ר עָלָ֜י⁠ו מֶ֣לֶךְ הַ⁠צָּפ֗וֹן בְּ⁠רֶ֨כֶב֙ וּ⁠בְ⁠פָ֣רָשִׁ֔ים וּ⁠בָ⁠אֳנִיּ֖וֹת רַבּ֑וֹת וּ⁠בָ֥א בַ⁠אֲרָצ֖וֹת וְ⁠שָׁטַ֥ף וְ⁠עָבָֽר׃","ẇ⁠bĕ⁠ʻé֣ţ qé֗ẕ yiţĕnagȧ֤ẖ ʻiṁ⁠wò֙ me֣lekĕ ha⁠nė֔geb wĕ⁠yişĕ̂ţá̇ʻé֨r ʻálá֜y⁠w me֣lekĕ ha⁠ẕá̇p֗wòn bĕ̇⁠re֨keb֙ ẇ⁠bĕ⁠pá֣ráşǐ֔ym ẇ⁠bá⁠ʼoniẏ֖wòţ raḃ֑wòţ ẇ⁠bá֥ʼ ba⁠ʼàráẕ֖wòţ wĕ⁠şá̌ta֥p wĕ⁠ʻábáֽr׃"],[11,41,"וּ⁠בָא֙ בְּ⁠אֶ֣רֶץ הַ⁠צְּבִ֔י וְ⁠רַבּ֖וֹת יִכָּשֵׁ֑לוּ וְ⁠אֵ֨לֶּה֙ יִמָּלְט֣וּ מִ⁠יָּד֔⁠וֹ אֱד֣וֹם וּ⁠מוֹאָ֔ב וְ⁠רֵאשִׁ֖ית בְּנֵ֥י עַמּֽוֹן׃","ẇ⁠báʼ֙ bĕ̇⁠ʼe֣reẕ ha⁠ẕĕ̇bi֔y wĕ⁠raḃ֖wòţ yiká̇şé֑̌lẇ wĕ⁠ʼé֨lėh֙ yimá̇lĕt֣ẇ mi⁠yá̇d֔⁠wò ʼèd֣wòm ẇ⁠mwòʼá֔b wĕ⁠réʼşǐ֖yţ bĕ̇né֥y ʻaṁֽwòn׃"],[11,42,"וְ⁠יִשְׁלַ֥ח יָד֖⁠וֹ בַּ⁠אֲרָצ֑וֹת וְ⁠אֶ֣רֶץ מִצְרַ֔יִם לֹ֥א תִהְיֶ֖ה לִ⁠פְלֵיטָֽה׃","wĕ⁠yişĕ̌la֥ẖ yád֖⁠wò bȧ⁠ʼàráẕ֑wòţ wĕ⁠ʼe֣reẕ miẕĕra֔yim lò֥ʼ ţihĕye֖h li⁠pĕléytáֽh׃"],[11,43,"וּ⁠מָשַׁ֗ל בְּ⁠מִכְמַנֵּי֙ הַ⁠זָּהָ֣ב וְ⁠הַ⁠כֶּ֔סֶף וּ⁠בְ⁠כֹ֖ל חֲמֻד֣וֹת מִצְרָ֑יִם וְ⁠לֻבִ֥ים וְ⁠כֻשִׁ֖ים בְּ⁠מִצְעָדָֽי⁠ו׃","ẇ⁠máşǎ֗l bĕ̇⁠mikĕmané̇y֙ ha⁠zá̇há֣b wĕ⁠ha⁠kė֔sep ẇ⁠bĕ⁠kò֖l ẖàmud֣wòţ miẕĕrá֑yim wĕ⁠lubi֥ym wĕ⁠kuşǐ֖ym bĕ̇⁠miẕĕʻádáֽy⁠w׃"],[11,44,"וּ⁠שְׁמֻע֣וֹת יְבַהֲלֻ֔⁠הוּ מִ⁠מִּזְרָ֖ח וּ⁠מִ⁠צָּפ֑וֹן וְ⁠יָצָא֙ בְּ⁠חֵמָ֣א גְדֹלָ֔ה לְ⁠הַשְׁמִ֥יד וּֽ⁠לְ⁠הַחֲרִ֖ים רַבִּֽים׃","ẇ⁠şĕ̌muʻ֣wòţ yĕbahàlu֔⁠hẇ mi⁠mi̇zĕrá֖ẖ ẇ⁠mi⁠ẕá̇p֑wòn wĕ⁠yáẕáʼ֙ bĕ̇⁠ẖémá֣ʼ gĕdòlá֔h lĕ⁠haşĕ̌mi֥yd ẇֽ⁠lĕ⁠haẖàri֖ym rabiֽ̇ym׃"],[11,45,"וְ⁠יִטַּע֙ אָהֳלֶ֣י אַפַּדְנ֔⁠וֹ בֵּ֥ין יַמִּ֖ים לְ⁠הַר־צְבִי־קֹ֑דֶשׁ וּ⁠בָא֙ עַד־קִצּ֔⁠וֹ וְ⁠אֵ֥ין עוֹזֵ֖ר לֽ⁠וֹ׃","wĕ⁠yitȧʻ֙ ʼáhole֣y ʼapȧdĕn֔⁠wò bé֥̇yn yami֖̇ym lĕ⁠har-ẕĕbiy-qò֑deş̌ ẇ⁠báʼ֙ ʻad-qiẕ̇֔⁠wò wĕ⁠ʼé֥yn ʻwòzé֖r lֽ⁠wò׃"],[12,1,"וּ⁠בָ⁠עֵ֣ת הַ⁠הִיא֩ יַעֲמֹ֨ד מִֽיכָאֵ֜ל הַ⁠שַּׂ֣ר הַ⁠גָּד֗וֹל הָ⁠עֹמֵד֮ עַל־בְּנֵ֣י עַמֶּ⁠ךָ֒ וְ⁠הָיְתָה֙ עֵ֣ת צָרָ֔ה אֲשֶׁ֤ר לֹֽא־נִהְיְתָה֙ מִֽ⁠הְי֣וֹת גּ֔וֹי עַ֖ד הָ⁠עֵ֣ת הַ⁠הִ֑יא וּ⁠בָ⁠עֵ֤ת הַ⁠הִיא֙ יִמָּלֵ֣ט עַמְּ⁠ךָ֔ כָּל־הַ⁠נִּמְצָ֖א כָּת֥וּב בַּ⁠סֵּֽפֶר׃","ẇ⁠bá⁠ʻé֣ţ ha⁠hiyʼ֩ yaʻàmò֨d miֽykáʼé֜l ha⁠şȧ֣̂r ha⁠gá̇d֗wòl há⁠ʻòméd֮ ʻal-bĕ̇né֣y ʻamė⁠ká֒ wĕ⁠háyĕţáh֙ ʻé֣ţ ẕárá֔h ʼàşě֤r lòֽʼ-nihĕyĕţáh֙ miֽ⁠hĕy֣wòţ ġ֔wòy ʻa֖d há⁠ʻé֣ţ ha⁠hi֑yʼ ẇ⁠bá⁠ʻé֤ţ ha⁠hiyʼ֙ yimá̇lé֣t ʻamĕ̇⁠ká֔ ká̇l-ha⁠ni̇mĕẕá֖ʼ ká̇ţ֥ẇb bȧ⁠séֽ̇per׃"],[12,2,"וְ⁠רַבִּ֕ים מִ⁠יְּשֵׁנֵ֥י אַדְמַת־עָפָ֖ר יָקִ֑יצוּ אֵ֚לֶּה לְ⁠חַיֵּ֣י עוֹלָ֔ם וְ⁠אֵ֥לֶּה לַ⁠חֲרָפ֖וֹת לְ⁠דִרְא֥וֹן עוֹלָֽם׃ס","wĕ⁠rabi̇֕ym mi⁠yĕ̇şé̌né֥y ʼadĕmaţ-ʻápá֖r yáqi֑yẕẇ ʼé֚lėh lĕ⁠ẖayé֣̇y ʻwòlá֔m wĕ⁠ʼé֥lėh la⁠ẖàráp֖wòţ lĕ⁠dirĕʼ֥wòn ʻwòláֽm׃s"],[12,3,"וְ⁠הַ֨⁠מַּשְׂכִּלִ֔ים יַזְהִ֖רוּ כְּ⁠זֹ֣הַר הָ⁠רָקִ֑יעַ וּ⁠מַצְדִּיקֵי֙ הָֽ⁠רַבִּ֔ים כַּ⁠כּוֹכָבִ֖ים לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃פ","wĕ⁠ha֨⁠mȧşĕ̂ki̇li֔ym yazĕhi֖rẇ kĕ̇⁠zò֣har há⁠ráqi֑yʻa ẇ⁠maẕĕdi̇yqéy֙ háֽ⁠rabi̇֔ym kȧ⁠k̇wòkábi֖ym lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃p"],[12,4,"וְ⁠אַתָּ֣ה דָֽנִיֵּ֗אל סְתֹ֧ם הַ⁠דְּבָרִ֛ים וַ⁠חֲתֹ֥ם הַ⁠סֵּ֖פֶר עַד־עֵ֣ת קֵ֑ץ יְשֹׁטְט֥וּ רַבִּ֖ים וְ⁠תִרְבֶּ֥ה הַ⁠דָּֽעַת׃","wĕ⁠ʼaţá֣̇h dáֽniyé̇֗ʼl sĕţò֧m ha⁠dĕ̇bári֛ym wa⁠ẖàţò֥m ha⁠sé֖̇per ʻad-ʻé֣ţ qé֑ẕ yĕşò̌tĕt֥ẇ rabi֖̇ym wĕ⁠ţirĕbė֥h ha⁠dáֽ̇ʻaţ׃"],[12,5,"וְ⁠רָאִ֨יתִי֙ אֲנִ֣י דָנִיֵּ֔אל וְ⁠הִנֵּ֛ה שְׁנַ֥יִם אֲחֵרִ֖ים עֹמְדִ֑ים אֶחָ֥ד הֵ֨נָּה֙ לִ⁠שְׂפַ֣ת הַ⁠יְאֹ֔ר וְ⁠אֶחָ֥ד הֵ֖נָּה לִ⁠שְׂפַ֥ת הַ⁠יְאֹֽר׃","wĕ⁠ráʼi֨yţiy֙ ʼàni֣y dániyé̇֔ʼl wĕ⁠hiné֛̇h şĕ̌na֥yim ʼàẖéri֖ym ʻòmĕdi֑ym ʼeẖá֥d hé֨ná̇h֙ li⁠şĕ̂pa֣ţ ha⁠yĕʼò֔r wĕ⁠ʼeẖá֥d hé֖ná̇h li⁠şĕ̂pa֥ţ ha⁠yĕʼòֽr׃"],[12,6,"וַ⁠יֹּ֗אמֶר לָ⁠אִישׁ֙ לְב֣וּשׁ הַ⁠בַּדִּ֔ים אֲשֶׁ֥ר מִ⁠מַּ֖עַל לְ⁠מֵימֵ֣י הַ⁠יְאֹ֑ר עַד־מָתַ֖י קֵ֥ץ הַ⁠פְּלָאֽוֹת׃","wa⁠yò̇֗ʼmer lá⁠ʼiyş̌֙ lĕb֣ẇş̌ ha⁠bȧdi̇֔ym ʼàşě֥r mi⁠mȧ֖ʻal lĕ⁠méymé֣y ha⁠yĕʼò֑r ʻad-máţa֖y qé֥ẕ ha⁠pĕ̇láʼֽwòţ׃"],[12,7,"וָ⁠אֶשְׁמַ֞ע אֶת־הָ⁠אִ֣ישׁ ׀ לְב֣וּשׁ הַ⁠בַּדִּ֗ים אֲשֶׁ֣ר מִ⁠מַּעַל֮ לְ⁠מֵימֵ֣י הַ⁠יְאֹר֒ וַ⁠יָּ֨רֶם יְמִינ֤⁠וֹ וּ⁠שְׂמֹאל⁠וֹ֙ אֶל־הַ⁠שָּׁמַ֔יִם וַ⁠יִּשָּׁבַ֖ע בְּ⁠חֵ֣י הָ⁠עוֹלָ֑ם כִּי֩ לְ⁠מוֹעֵ֨ד מֽוֹעֲדִ֜ים וָ⁠חֵ֗צִי וּ⁠כְ⁠כַלּ֛וֹת נַפֵּ֥ץ יַד־עַם־קֹ֖דֶשׁ תִּכְלֶ֥ינָה כָל־אֵֽלֶּה׃","wá⁠ʼeşĕ̌ma֞ʻ ʼeţ-há⁠ʼi֣yş̌ ׀ lĕb֣ẇş̌ ha⁠bȧdi̇֗ym ʼàşě֣r mi⁠mȧʻal֮ lĕ⁠méymé֣y ha⁠yĕʼòr֒ wa⁠yá̇֨rem yĕmiyn֤⁠wò ẇ⁠şĕ̂mòʼl⁠wò֙ ʼel-ha⁠şá̇̌ma֔yim wa⁠yi̇şá̇̌ba֖ʻ bĕ̇⁠ẖé֣y há⁠ʻwòlá֑m ki̇y֩ lĕ⁠mwòʻé֨d mֽwòʻàdi֜ym wá⁠ẖé֗ẕiy ẇ⁠kĕ⁠kal֛̇wòţ napé֥̇ẕ yad-ʻam-qò֖deş̌ ţi̇kĕle֥ynáh kál-ʼéֽlėh׃"],[12,8,"וַ⁠אֲנִ֥י שָׁמַ֖עְתִּי וְ⁠לֹ֣א אָבִ֑ין וָ⁠אֹ֣מְרָ֔⁠ה אֲדֹנִ֕⁠י מָ֥ה אַחֲרִ֖ית אֵֽלֶּה׃פ","wa⁠ʼàni֥y şá̌ma֖ʻĕţi̇y wĕ⁠lò֣ʼ ʼábi֑yn wá⁠ʼò֣mĕrá֔⁠h ʼàdòni֕⁠y má֥h ʼaẖàri֖yţ ʼéֽlėh׃p"],[12,9,"וַ⁠יֹּ֖אמֶר לֵ֣ךְ דָּנִיֵּ֑אל כִּֽי־סְתֻמִ֧ים וַ⁠חֲתֻמִ֛ים הַ⁠דְּבָרִ֖ים עַד־עֵ֥ת קֵֽץ׃","wa⁠yò֖̇ʼmer lé֣kĕ dá̇niyé֑̇ʼl kiֽ̇y-sĕţumi֧ym wa⁠ẖàţumi֛ym ha⁠dĕ̇bári֖ym ʻad-ʻé֥ţ qéֽẕ׃"],[12,10,"יִ֠תְבָּֽרֲרוּ וְ⁠יִֽתְלַבְּנ֤וּ וְ⁠יִצָּֽרְפוּ֙ רַבִּ֔ים וְ⁠הִרְשִׁ֣יעוּ רְשָׁעִ֔ים וְ⁠לֹ֥א יָבִ֖ינוּ כָּל־רְשָׁעִ֑ים וְ⁠הַ⁠מַּשְׂכִּלִ֖ים יָבִֽינוּ׃","yi֠ţĕbáֽ̇ràrẇ wĕ⁠yiֽţĕlabĕ̇n֤ẇ wĕ⁠yiẕáֽ̇rĕpẇ֙ rabi̇֔ym wĕ⁠hirĕşǐ֣yʻẇ rĕşá̌ʻi֔ym wĕ⁠lò֥ʼ yábi֖ynẇ ká̇l-rĕşá̌ʻi֑ym wĕ⁠ha⁠mȧşĕ̂ki̇li֖ym yábiֽynẇ׃"],[12,11,"וּ⁠מֵ⁠עֵת֙ הוּסַ֣ר הַ⁠תָּמִ֔יד וְ⁠לָ⁠תֵ֖ת שִׁקּ֣וּץ שֹׁמֵ֑ם יָמִ֕ים אֶ֖לֶף מָאתַ֥יִם וְ⁠תִשְׁעִֽים׃","ẇ⁠mé⁠ʻéţ֙ hẇsa֣r ha⁠ţá̇mi֔yd wĕ⁠lá⁠ţé֖ţ şǐq֣̇ẇẕ şò̌mé֑m yámi֕ym ʼe֖lep máʼţa֥yim wĕ⁠ţişĕ̌ʻiֽym׃"],[12,12,"אַשְׁרֵ֥י הַֽ⁠מְחַכֶּ֖ה וְ⁠יַגִּ֑יעַ לְ⁠יָמִ֕ים אֶ֕לֶף שְׁלֹ֥שׁ מֵא֖וֹת שְׁלֹשִׁ֥ים וַ⁠חֲמִשָּֽׁה׃","ʼaşĕ̌ré֥y haֽ⁠mĕẖakė֖h wĕ⁠yagi֑̇yʻa lĕ⁠yámi֕ym ʼe֕lep şĕ̌lò֥ş̌ méʼ֖wòţ şĕ̌lòşǐ֥ym wa⁠ẖàmişáֽ̇̌h׃"],[12,13,"וְ⁠אַתָּ֖ה לֵ֣ךְ לַ⁠קֵּ֑ץ וְ⁠תָנ֛וּחַ וְ⁠תַעֲמֹ֥ד לְ⁠גֹרָלְ⁠ךָ֖ לְ⁠קֵ֥ץ הַ⁠יָּמִֽין׃","wĕ⁠ʼaţá֖̇h lé֣kĕ la⁠qé֑̇ẕ wĕ⁠ţán֛ẇẖa wĕ⁠ţaʻàmò֥d lĕ⁠gòrálĕ⁠ká֖ lĕ⁠qé֥ẕ ha⁠yá̇miֽyn׃"]]}};